      <Panel title="Compras recientes" subtitle="Abastecimiento registrado" action={<button className="text-button" onClick={() => onNavigate("compras")}>Ver compras →</button>}><div className="mini-orders">{data.purchases.slice(0, 4).map((purchase) => <article key={String(purchase.id)}><div><strong>C-{String(purchase.id)}</strong><span>{String(purchase.material ?? "Compra")}</span></div><div><Badge tone={String(purchase.status) === "Anulada" ? "danger" : "success"}>{String(purchase.status)}</Badge><small>{String(purchase.purchased_at).slice(0, 10)}</small></div></article>)}{!data.purchases.length && <p className="empty-operation">Todavía no hay compras registradas.</p>}</div></Panel>
