type ManufacturingOption = { id: number; code: string; name: string; type: "MANUFACTURED" | "COMBO"; comboId?: number; price: number };
type ManufacturingPreviewItem = { code: string; name: string; unit: string; perUnit: number; required: number; available: number; minimum: number; unitCost: number; subtotal: number; componentType?: string };

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function localManufacturingPreview(option: ManufacturingOption, quantity: number): ManufacturingPreviewItem[] {
  if (option.type === "COMBO") {
    const definition = comboDefinitions.find((item) => item.productCode === option.code);
    if (!definition) return [];
    const productItems = definition.productComponents.map((part) => { const product = products.find((item) => item.code === part.productCode)!; return { code: product.code, name: product.name, unit: "unidad", perUnit: part.quantity, required: part.quantity * quantity, available: product.stock, minimum: product.minimum, unitCost: product.cost, subtotal: part.quantity * quantity * product.cost }; });
    const materialItems = definition.materialComponents.map((part) => { const material = materials.find((item) => item.code === part.materialCode)!; return { code: material.code, name: material.name, unit: material.unit, perUnit: part.quantity, required: part.quantity * quantity, available: material.stock, minimum: material.minimum, unitCost: material.cost, subtotal: part.quantity * quantity * material.cost }; });
    return [...productItems, ...materialItems];
  }
  const recipe = recipeDefinitions.find((item) => item.productCode === option.code);
  return (recipe?.components ?? []).map((part) => { const material = materials.find((item) => item.code === part.materialCode)!; return { code: material.code, name: material.name, unit: material.unit, perUnit: part.quantity, required: part.quantity * quantity, available: material.stock, minimum: material.minimum, unitCost: material.cost, subtotal: part.quantity * quantity * material.cost }; });
}

function ManufactureFormDialog({ batch, initialCode, initialQuantity, onCancel, onSaved }: { batch?: ManufacturingRow; initialCode: string; initialQuantity: number; onCancel: () => void; onSaved: (message: string) => void }) {
  const [catalog, setCatalog] = useState<ManufacturingOption[]>([]);
  const [optionId, setOptionId] = useState(0);
  const [quantity, setQuantity] = useState(initialQuantity);
  const [date, setDate] = useState(batch ? String(batch.manufactured_at).slice(0, 10) : new Date().toISOString().slice(0, 10));
  const [notes, setNotes] = useState(batch?.notes ?? "");
  const [preview, setPreview] = useState<ManufacturingPreviewItem[]>([]);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const option = catalog.find((item) => item.id === optionId) ?? catalog[0];
  const totalCost = Math.round(preview.reduce((sum, item) => sum + item.subtotal, 0));
  const unitCost = quantity > 0 ? Math.round(totalCost / quantity) : 0;
  const canConfirm = preview.length > 0 && (Boolean(batch) || preview.every((item) => item.available >= item.required));
  const estimatedProfit = (option?.price ?? 0) - unitCost;
  const margin = unitCost > 0 ? estimatedProfit * 100 / unitCost : 0;

  useEffect(() => {
    let active = true;
    fetch("/api/khora?entity=products").then(async (response) => { if (!response.ok) throw new Error(); return response.json() as Promise<{ rows?: Array<Record<string, unknown>> }>; }).then((data) => {
      if (!active) return;
      const rows = (data.rows ?? []).filter((row) => Boolean(row.active) && (row.type === "MANUFACTURED" || row.type === "COMBO")).map((row) => ({ id: Number(row.id), code: String(row.code), name: String(row.name), type: String(row.type) as "MANUFACTURED" | "COMBO", comboId: row.combo_id ? Number(row.combo_id) : undefined, price: Number(row.sale_price_cents) }));
      if (rows.length) { setCatalog(rows); setOptionId((batch ? rows.find((item) => item.id === Number(batch.product_id)) : rows.find((item) => item.code === initialCode))?.id ?? rows[0].id); }
    }).catch(() => undefined);
    return () => { active = false; };
  }, [batch, initialCode]);

  useEffect(() => {
    if (!option || quantity <= 0) return;
    let active = true;
    const entity = option.type === "COMBO" ? "combo_preview" : "manufacture_preview";
    const key = option.type === "COMBO" ? `comboId=${option.comboId ?? 0}` : `productId=${option.id}`;
    fetch(`/api/khora?entity=${entity}&${key}&quantity=${quantity}`).then(async (response) => { if (!response.ok) throw new Error(); return response.json() as Promise<{ items?: Array<Record<string, unknown>>; materials?: Array<Record<string, unknown>> }>; }).then((data) => {
      if (!active) return;
       const rows = [...(data.items ?? []), ...(data.materials ?? [])].map((row) => ({ code: String(row.code), name: String(row.material ?? row.product), unit: String(row.unit ?? "unidad"), perUnit: Number(row.per_unit ?? row.quantity ?? 0), required: Number(row.required), available: Number(row.available), minimum: Number(row.minimum_stock ?? 0), unitCost: Number(row.current_cost_cents ?? row.estimated_cost_cents), subtotal: Number(row.subtotal_cents), componentType: String(row.component_type ?? (row.product ? "PRODUCT" : "MATERIAL")) }));
      setPreview(rows);
    }).catch(() => { if (active) setPreview([]); });
    return () => { active = false; };
  }, [option, quantity]);

  async function confirm() {
    if (!option || !canConfirm) { setError("No se puede fabricar: revisá los componentes faltantes."); return; }
    setSaving(true); setError("");
    try { const body = batch ? { action: "update_manufacturing", id: batch.id, batchKind: batch.batch_kind, productId: option.type === "MANUFACTURED" ? option.id : undefined, comboId: option.type === "COMBO" ? option.comboId : undefined, quantity, date, notes } : option.type === "COMBO" ? { action: "assemble_combo", comboId: option.comboId, quantity, date, notes } : { action: "manufacture", productId: option.id, quantity, date, notes }; const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }); const result = await response.json() as { error?: string; batchNumber?: string; unitCostCents?: number; message?: string }; if (!response.ok) throw new Error(result.error ?? "No se pudo confirmar la fabricación"); onSaved(result.message ?? (batch ? `${option.name}: producción actualizada correctamente.` : `${option.name}: lote ${result.batchNumber ?? "creado"} confirmado con costo unitario ${money((result.unitCostCents ?? unitCost) / 100)}.`)); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo confirmar la fabricación"); } finally { setSaving(false); }
  }

   return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar fabricación" /><aside className="inventory-form-drawer manufacture-form-drawer" role="dialog" aria-modal="true" aria-labelledby="manufacture-form-title"><header><div><p>FABRICACIÓN · SIMULACIÓN</p><h2 id="manufacture-form-title">{batch ? "Editar producción" : "Fabricar producto o combo"}</h2><span>{batch ? "Actualizá el lote mientras no tenga movimientos asociados." : "KHORA calcula materiales, disponibilidad y costo antes de confirmar."}</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="inventory-form-body"><div className="form-grid"><label><span>Producto o combo *</span><select value={optionId} onChange={(event) => setOptionId(Number(event.target.value))}>{catalog.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label><label><span>Cantidad *</span><input type="text" inputMode="numeric" value={quantity} onChange={(event) => setQuantity(Math.max(1, Number(event.target.value.replace(/[^0-9]/g, "")) || 1))} /></label></div><div className="form-grid"><label><span>Fecha *</span><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label><span>Notas del lote</span><input value={notes} onChange={(event) => setNotes(event.target.value)} /></label></div><section className="manufacture-materials"><header><div><strong>Insumos necesarios</strong><p>Materias primas y mezclas para fabricar {quantity} {quantity === 1 ? "unidad" : "unidades"}.</p></div><Badge tone={canConfirm ? "success" : "danger"}>{canConfirm ? "Stock suficiente" : "Hay faltantes"}</Badge></header><div className="manufacture-material-list" data-testid="manufacture-material-list">{preview.map((item) => { const shortage = Math.max(0, item.required - item.available); const remaining = item.available - item.required; const tone = shortage > 0 ? "danger" : remaining <= item.minimum ? "warning" : "success"; return <article className="manufacture-material-card" key={`${item.componentType ?? "MATERIAL"}-${item.code}`} data-testid={`manufacture-material-${item.code}`}><span className="recipe-line-icon" aria-hidden="true">{item.componentType === "MIXTURE" ? "◌" : "⚗"}</span><div className="manufacture-material-field manufacture-material-identity"><span>{item.componentType === "MIXTURE" ? "Mezcla preparada" : "Materia prima guardada"}</span><div>{item.code} · {item.name}</div><small>{formatQuantity(item.perUnit)} {item.unit} por unidad · Disponible {formatQuantity(item.available)} {item.unit}</small></div><div className="manufacture-material-field"><span>Cantidad necesaria para fabricar</span><div className="manufacture-quantity-field"><strong>{formatQuantity(item.required)}</strong><b>{item.unit}</b></div><small>Stock mínimo {formatQuantity(item.minimum)} {item.unit}</small></div><div className="recipe-line-cost manufacture-line-cost"><span>Costo para esta cantidad</span><strong>{money(item.subtotal / 100)}</strong><small>{money(item.unitCost / 100)} por {item.unit}</small></div><Badge tone={tone}>{shortage > 0 ? `Faltan ${formatQuantity(shortage)} ${item.unit}` : remaining <= item.minimum ? "Quedará bajo" : "Suficiente"}</Badge></article>; })}{!preview.length && <div className="recipe-empty">El producto no tiene una receta o composición activa.</div>}</div></section><section className="manufacture-cost-summary"><article><span>Cantidad</span><strong>{quantity} u.</strong></article><article><span>Costo total</span><strong>{money(totalCost / 100)}</strong></article><article><span>Costo unitario</span><strong>{money(unitCost / 100)}</strong></article><article><span>Precio actual</span><strong>{money((option?.price ?? 0) / 100)}</strong></article><article><span>Ganancia estimada/un.</span><strong>{money(estimatedProfit / 100)}</strong></article><article><span>Margen estimado</span><strong>{margin.toFixed(1)}%</strong></article></section><div className="material-zero-rule"><span>i</span><p>{batch ? "La edición revierte y reaplica el stock en una sola operación." : "Esta vista es una simulación. El stock cambia únicamente cuando confirmás la fabricación."}</p></div>{error && <p className="form-error" role="alert">{error}</p>}</div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="primary-button" disabled={saving || !canConfirm} aria-busy={saving} onClick={confirm}>{saving ? "Guardando…" : batch ? "Guardar cambios" : canConfirm ? "Confirmar fabricación" : "No se puede fabricar"}</button></footer></aside></div>;
}

function ManufacturingCancelDialog({ batch, onCancel, onSaved }: { batch: ManufacturingRow; onCancel: () => void; onSaved: (message: string) => void }) {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function cancel() {
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "cancel_manufacturing", id: batch.id, batchKind: batch.batch_kind }) });
      const result = await response.json() as { error?: string; message?: string };
      if (!response.ok) throw new Error(result.error ?? "No se pudo anular la producción");
      onSaved(result.message ?? "Producción anulada correctamente.");
    } catch (cause) { console.error(cause); setError(cause instanceof Error ? cause.message : "No se pudo anular la producción"); } finally { setSaving(false); }
  }
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar anulación" /><section className="confirm-dialog category-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="cancel-manufacturing-title"><header><div><p>FABRICACIÓN · TRAZABILIDAD</p><h2 id="cancel-manufacturing-title">Anular producción</h2><span>Se revertirán los materiales y el stock generado por este lote.</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="category-delete-body">{error ? <div className="confirm-note danger-note" role="alert"><i>!</i><p>{error}</p></div> : <><p>¿Seguro que querés anular el lote <strong>“{batch.batch_number}”</strong> de <strong>{batch.product}</strong>?</p><div className="confirm-note"><i>i</i><p>El lote quedará en el historial como anulado y no volverá a participar en FIFO ni en el stock activo.</p></div></>}</div><footer><button className="secondary-button" onClick={onCancel}>{error ? "Entendido" : "Cancelar"}</button>{!error && <button className="danger-button" disabled={saving} aria-busy={saving} onClick={cancel}>{saving ? "Anulando…" : "Anular producción"}</button>}</footer></section></div>;
}

type MixtureRow = { id: number; code: string; name: string; unit: string; yield_quantity: number; minimum_stock: number; current_stock: number; estimated_cost_cents: number; formula_count: number; active: number | boolean; notes?: string } & Record<string, unknown>;
type MixtureLotRow = { id: number; preparation_id: number; mixture_id: number; code: string; mixture: string; unit: string; lot_number: string; initial_quantity: number; available_quantity: number; total_cost_cents: number; unit_cost_cents: number; prepared_at: string; theoretical_quantity?: number; waste_percentage?: number; status: string; notes?: string } & Record<string, unknown>;
type MixtureFormulaLine = { materialId: number; quantity: string };
type MixtureMaterialOption = { id: number; code: string; material: string; unit: string; current_stock: number; current_cost_cents: number };

function MixturesPanel() {
  const mixtureData = useKhoraRows<MixtureRow>("mixtures");
  const [editing, setEditing] = useState<MixtureRow | null | undefined>(undefined);
  const [preparing, setPreparing] = useState<MixtureRow | null>(null);
  const [notice, setNotice] = useState("");
  const active = mixtureData.rows.filter((row) => Boolean(Number(row.active) || row.active === true));
  const activeWithStock = active.filter((row) => Number(row.current_stock) > 0);
  function saved(message: string) { setEditing(undefined); mixtureData.refresh(); setNotice(message); window.setTimeout(() => setNotice(""), 4500); }
   return <div className="mixtures-panel section-stack">
    {mixtureData.error && <div className="inline-notice error" role="alert"><span>!</span>{mixtureData.error}</div>}
    {notice && <div className="inline-notice" role="status"><span>✓</span>{notice}</div>}
    <div className="mixture-create-row"><div><strong>Mezclas intermedias</strong><span>Definí fórmulas reutilizables y prepará lotes con stock y costo histórico.</span></div><div><button className="secondary-button" onClick={() => setEditing(null)}>＋ Nueva mezcla</button>{active.length > 0 && <button className="primary-button" onClick={() => setPreparing(active[0])}>⚗ Preparar mezcla</button>}</div></div>
     <div className="summary-row"><MiniStat label="Mezclas activas" value={String(active.length)} detail="Fórmulas reutilizables" tone="success" /><MiniStat label="Con stock disponible" value={String(activeWithStock.length)} detail="Cada unidad conserva su medida" tone="info" /><MiniStat label="Costo promedio" value={money((active.reduce((sum, row) => sum + Number(row.estimated_cost_cents), 0) / Math.max(1, active.length)) / 100)} detail="Estimado por rendimiento" tone="neutral" /></div>
     <Panel title="Mezclas" subtitle={mixtureData.loading ? "Actualizando…" : `${active.length} mezclas activas`}>
       <div className="mixture-grid">{active.map((mixture) => <article className="mixture-card" key={mixture.id}><header><div><small>{mixture.code}</small><h3>{mixture.name}</h3></div><Badge tone="success">Activa</Badge></header><p className="mixture-card-description">Rendimiento: <strong>{formatQuantity(Number(mixture.yield_quantity))} {mixture.unit}</strong> · {Number(mixture.formula_count)} materias primas</p><dl><div><dt>Stock actual</dt><dd>{formatQuantity(Number(mixture.current_stock))} {mixture.unit}</dd></div><div><dt>Costo estimado</dt><dd>{money(Number(mixture.estimated_cost_cents) / 100)} / {mixture.unit}</dd></div><div><dt>Stock mínimo</dt><dd>{formatQuantity(Number(mixture.minimum_stock))} {mixture.unit}</dd></div></dl><footer><button className="secondary-button compact" onClick={() => setPreparing(mixture)}>Preparar lote</button><button className="secondary-button compact" onClick={() => setEditing(mixture)}>Editar fórmula</button></footer></article>)}</div>
       {!mixtureData.loading && !active.length && <div className="recipe-empty">Todavía no hay mezclas definidas. Creá la primera para reutilizar una fórmula en fabricación.</div>}
      </Panel>
    {editing !== undefined && <MixtureFormDialog mixture={editing ?? undefined} onCancel={() => setEditing(undefined)} onSaved={saved} />}
    {preparing && <MixturePrepareDialog mixture={preparing} onCancel={() => setPreparing(null)} onSaved={(message) => { setPreparing(null); mixtureData.refresh(); setNotice(message); window.setTimeout(() => setNotice(""), 4500); }} />}
  </div>;
}

function MixtureFormDialog({ mixture, onCancel, onSaved }: { mixture?: MixtureRow; onCancel: () => void; onSaved: (message: string) => void }) {
  useDrawerBodyLock();
  const [materials, setMaterials] = useState<MixtureMaterialOption[]>([]);
  const [code, setCode] = useState(mixture?.code ?? "MIX-NUEVA");
  const [name, setName] = useState(mixture?.name ?? "");
  const [unit, setUnit] = useState(mixture?.unit ?? "ml");
  const [yieldQuantity, setYieldQuantity] = useState(String(mixture?.yield_quantity ?? 1));
  const [minimumStock, setMinimumStock] = useState(String(mixture?.minimum_stock ?? 0));
  const [notes, setNotes] = useState(mixture?.notes ?? "");
  const [formula, setFormula] = useState<MixtureFormulaLine[]>([]);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    let active = true;
    fetch("/api/khora?entity=materials").then(async (response) => { if (!response.ok) throw new Error(); return response.json() as Promise<{ rows?: Array<Record<string, unknown>> }>; }).then((data) => { if (active) setMaterials((data.rows ?? []).filter((row) => Boolean(row.active)).map((row) => ({ id: Number(row.id), code: String(row.code), material: String(row.material), unit: String(row.unit), current_stock: Number(row.current_stock), current_cost_cents: Number(row.current_cost_cents) }))); }).catch(() => undefined);
    if (!mixture) fetch("/api/khora?entity=next_code&kind=MIXTURE").then(async (response) => { if (!response.ok) throw new Error(); return response.json() as Promise<{ code?: string }>; }).then((data) => { if (active && data.code) setCode(data.code); }).catch(() => undefined);
    if (mixture) fetch(`/api/khora?entity=mixture_definition&id=${mixture.id}`).then(async (response) => { if (!response.ok) throw new Error(); return response.json() as Promise<{ items?: Array<Record<string, unknown>> }>; }).then((data) => { if (active) setFormula((data.items ?? []).map((item) => ({ materialId: Number(item.material_id), quantity: String(item.quantity) }))); }).catch(() => undefined);
    return () => { active = false; };
  }, [mixture]);
  function addLine() {
    setFormula((lines) => {
      const nextMaterial = materials.find((item) => !lines.some((line) => line.materialId === item.id)) ?? materials[0];
      return [...lines, { materialId: nextMaterial?.id ?? 0, quantity: "1" }];
    });
  }
  function updateLine(index: number, patch: Partial<MixtureFormulaLine>) { setFormula((lines) => lines.map((line, lineIndex) => lineIndex === index ? { ...line, ...patch } : line)); }
  async function save() {
    setSaving(true); setError("");
    try {
      if (!name.trim()) throw new Error("Ingresá un nombre para la mezcla.");
      const yieldValue = Number(yieldQuantity.replace(",", ".")), minimumValue = Number(minimumStock.replace(",", "."));
      if (!(yieldValue > 0)) throw new Error("El rendimiento debe ser mayor que cero.");
      if (formula.length === 0 || formula.some((line) => !line.materialId || !(Number(line.quantity.replace(",", ".")) > 0))) throw new Error("Agregá materias primas y cantidades válidas.");
      const baseResponse = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "save_mixture", id: mixture?.id, code, name, unit, yieldQuantity: yieldValue, minimumStock: Math.max(0, minimumValue), notes }) });
      const baseResult = await baseResponse.json() as { id?: number; error?: string };
      if (!baseResponse.ok || !baseResult.id) throw new Error(baseResult.error ?? "No se pudo guardar la mezcla.");
      const formulaResponse = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "save_mixture_formula", mixtureId: baseResult.id, items: formula.map((line) => ({ materialId: line.materialId, quantity: Number(line.quantity.replace(",", ".")) })) }) });
      const formulaResult = await formulaResponse.json() as { error?: string };
      if (!formulaResponse.ok) throw new Error(formulaResult.error ?? "No se pudo guardar la fórmula.");
      onSaved(mixture ? "Mezcla actualizada correctamente." : "Mezcla creada correctamente.");
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo guardar la mezcla."); } finally { setSaving(false); }
  }
  return (
    <div className="drawer-layer">
      <button className="drawer-backdrop" onClick={onCancel} aria-label="Cerrar mezcla" />
      <aside className="inventory-form-drawer mixture-form-dialog" role="dialog" aria-modal="true" aria-labelledby="mixture-form-title">
        <header>
          <div>
            <p>PRODUCCIÓN · MEZCLAS</p>
            <h2 id="mixture-form-title">{mixture ? "Editar mezcla" : "Nueva mezcla"}</h2>
            <span>Definí el rendimiento, las materias primas y el stock mínimo.</span>
          </div>
          <button onClick={onCancel} aria-label="Cerrar">×</button>
        </header>
        <div className="inventory-form-body">
          <div className="form-grid">
            <label><span>Código</span><input value={code} onChange={(event) => setCode(event.target.value.toUpperCase())} /></label>
            <label><span>Nombre de la mezcla *</span><input value={name} onChange={(event) => setName(event.target.value)} placeholder="Ej. Base aromática" /></label>
            <label><span>Unidad de salida *</span><select value={unit} onChange={(event) => setUnit(event.target.value)}><option value="ml">Mililitro (ml)</option><option value="l">Litro (L)</option><option value="g">Gramo (g)</option><option value="u.">Unidad</option></select></label>
            <label><span>Rendimiento por lote *</span><input type="text" inputMode="decimal" value={yieldQuantity} onChange={(event) => setYieldQuantity(event.target.value)} /></label>
            <label><span>Stock mínimo</span><input type="text" inputMode="decimal" value={minimumStock} onChange={(event) => setMinimumStock(event.target.value)} /></label>
          </div>
          <label className="mixture-notes-field"><span>Notas internas</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Observaciones de la fórmula…" /></label>
          <section className="mixture-formula-section">
            <header>
              <div><strong>Materias primas de la fórmula</strong><p>Las cantidades se expresan para producir el rendimiento indicado.</p></div>
              <button className="secondary-button" type="button" onClick={addLine} disabled={!materials.length}>＋ Agregar materia prima</button>
            </header>
            <div className="mixture-formula-list">
              {formula.map((line, index) => {
                const material = materials.find((item) => item.id === line.materialId);
                return (
                  <div className="mixture-formula-row" key={`${index}-${line.materialId}`}>
                    <span className="recipe-line-icon" aria-hidden="true">⚗</span>
                    <label>
                      <span>Materia prima guardada</span>
                      <select value={line.materialId} onChange={(event) => updateLine(index, { materialId: Number(event.target.value) })}>
                        <option value={0}>Seleccionar materia prima…</option>
                        {materials.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.material}</option>)}
                      </select>
                      <small>{material?.unit ?? ""} · stock {formatQuantity(material?.current_stock ?? 0)}</small>
                    </label>
                    <label>
                      <span>Cantidad por lote</span>
                      <input type="text" inputMode="decimal" value={line.quantity} onChange={(event) => updateLine(index, { quantity: event.target.value })} />
                      <small>{material?.unit ?? unit}</small>
                    </label>
                    <button className="icon-button danger" type="button" title="Quitar materia prima" onClick={() => setFormula((lines) => lines.filter((_, lineIndex) => lineIndex !== index))}>×</button>
                  </div>
                );
              })}
              {!formula.length && <div className="recipe-empty">Agregá la primera materia prima para comenzar la fórmula.</div>}
            </div>
          </section>
          {error && <p className="form-error" role="alert">{error}</p>}
        </div>
        <footer>
          <button className="secondary-button" onClick={onCancel}>Cancelar</button>
          <button className="primary-button" disabled={saving} onClick={save}>{saving ? "Guardando…" : mixture ? "Guardar cambios" : "Crear mezcla"}</button>
        </footer>
      </aside>
    </div>
  );
}

type MixturePreviewItem = { material_id: number; code?: string | null; material: string; unit: string; required: number; available: number | null; current_cost_cents: number | null; subtotal_cents: number | null; material_active: boolean; cost_available: boolean } & Record<string, unknown>;
type MixturePreview = { mixture: { code: string; name: string; unit: string; yield_quantity: number }; items: MixturePreviewItem[]; formulaCount: number; formulaConfigured: boolean; formulaComplete: boolean; hasMissingCosts: boolean; quantity: number; currentStock: number; stockAfter: number; totalCostCents: number | null; unitCostCents: number | null; canPrepare: boolean };
type MixturePreviewStatus = "idle" | "loading" | "ready" | "error";

function MixturePrepareDialog({ mixture: initialMixture, preparation, onCancel, onSaved }: { mixture: MixtureRow; preparation?: MixtureLotRow; onCancel: () => void; onSaved: (message: string) => void }) {
  useDrawerBodyLock();
  const [mixtures, setMixtures] = useState<MixtureRow[]>([]);
  const [mixtureId, setMixtureId] = useState(initialMixture.id);
  const [quantity, setQuantity] = useState(String(preparation?.initial_quantity ?? preparation?.theoretical_quantity ?? initialMixture.yield_quantity ?? 1));
  const [notes, setNotes] = useState(preparation?.notes ?? "");
  const [preview, setPreview] = useState<MixturePreview | null>(null);
  const [previewStatus, setPreviewStatus] = useState<MixturePreviewStatus>("idle");
  const [previewError, setPreviewError] = useState("");
  const [loadedPreviewKey, setLoadedPreviewKey] = useState("");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  useEffect(() => { fetch("/api/khora?entity=mixtures").then(async (response) => { if (!response.ok) throw new Error(); return response.json() as Promise<{ rows?: MixtureRow[] }>; }).then((data) => setMixtures(data.rows ?? [])).catch(() => undefined); }, []);
  const previewAmount = Number(quantity.replace(",", "."));
  const previewInputValid = Number.isFinite(previewAmount) && previewAmount > 0 && mixtureId > 0;
  const previewKey = `${mixtureId}:${previewAmount}:${preparation?.preparation_id ?? ""}`;
  useEffect(() => {
    let active = true;
    if (!previewInputValid) {
      Promise.resolve().then(() => { if (active) { setPreview(null); setPreviewStatus("idle"); setPreviewError(""); setLoadedPreviewKey(""); } });
      return () => { active = false; };
    }
    Promise.resolve().then(() => { if (active) { setPreviewStatus("loading"); setPreviewError(""); setLoadedPreviewKey(""); } });
    fetch(`/api/khora?entity=mixture_preview&mixtureId=${mixtureId}&quantity=${previewAmount}${preparation ? `&preparationId=${preparation.preparation_id}` : ""}`).then(async (response) => {
      const data = await response.json() as MixturePreview & { error?: string };
      if (!response.ok) throw new Error(data.error ?? "No se pudo cargar la fórmula de esta mezcla.");
      return data;
    }).then((data) => { if (active) { setPreview(data); setPreviewStatus("ready"); setLoadedPreviewKey(previewKey); } }).catch((cause) => { if (active) { setPreview(null); setPreviewStatus("error"); setLoadedPreviewKey(previewKey); setPreviewError(cause instanceof Error ? cause.message : "No se pudo cargar la fórmula de esta mezcla."); } });
    return () => { active = false; };
  }, [mixtureId, previewAmount, previewInputValid, previewKey, preparation]);
  async function prepare() {
    if (!preview?.canPrepare) {
      setError(preview?.hasMissingCosts ? "No se puede calcular correctamente el costo: una o más materias primas no tienen costo registrado." : preview && !preview.formulaConfigured ? "Esta mezcla no tiene una fórmula configurada." : preview && !preview.formulaComplete ? "No se pudo cargar la fórmula completa de esta mezcla." : "No hay stock suficiente para preparar esta mezcla.");
      return;
    }
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: preparation ? "update_mixture_preparation" : "prepare_mixture", id: preparation?.preparation_id, mixtureId, quantity: Number(quantity.replace(",", ".")), notes }) });
      const result = await response.json() as { error?: string; lotNumber?: string; quantity?: number };
      if (!response.ok) throw new Error(result.error ?? "No se pudo guardar la preparación.");
      onSaved(preparation ? `Lote ${preparation.lot_number} actualizado correctamente.` : `Lote ${result.lotNumber ?? "creado"} confirmado · ${formatQuantity(Number(result.quantity ?? preview.quantity))} ${preview.mixture.unit}.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo guardar la preparación."); } finally { setSaving(false); }
  }
  const selected = mixtures.find((row) => row.id === mixtureId) ?? initialMixture;
  const readyPreview = previewStatus === "ready" && loadedPreviewKey === previewKey ? preview : null;
  const previewBadgeTone = previewStatus === "loading" ? "info" : previewStatus === "error" ? "danger" : readyPreview?.canPrepare ? "success" : "danger";
  const previewBadgeLabel = previewStatus === "loading" ? "Cargando…" : previewStatus === "error" ? "No disponible" : readyPreview?.canPrepare ? "Stock suficiente" : readyPreview?.formulaConfigured ? "Revisar fórmula" : "Sin fórmula";
  return (
    <div className="drawer-layer">
      <button className="drawer-backdrop" onClick={onCancel} aria-label="Cerrar preparación" />
      <aside className="inventory-form-drawer mixture-prepare-dialog" role="dialog" aria-modal="true" aria-labelledby="mixture-prepare-title">
        <header>
           <div><p>PRODUCCIÓN · MEZCLAS</p><h2 id="mixture-prepare-title">{preparation ? "Editar preparación" : "Preparar mezcla"}</h2><span>Calculá materiales, stock y costo antes de confirmar el lote.</span></div>
          <button onClick={onCancel} aria-label="Cerrar">×</button>
        </header>
        <div className="inventory-form-body">
          <div className="form-grid">
            <label><span>Mezcla *</span><select value={mixtureId} onChange={(event) => setMixtureId(Number(event.target.value))}>{mixtures.length ? mixtures.filter((row) => Boolean(Number(row.active) || row.active === true)).map((row) => <option key={row.id} value={row.id}>{row.code} · {row.name}</option>) : <option value={selected.id}>{selected.code} · {selected.name}</option>}</select></label>
             <label><span>Cantidad a preparar *</span><div className="mixture-quantity-input"><input type="text" inputMode="decimal" value={quantity} onChange={(event) => setQuantity(event.target.value)} /><b>{selected.unit}</b></div></label>
            <label><span>Notas del lote</span><input value={notes} onChange={(event) => setNotes(event.target.value)} /></label>
          </div>
          {previewInputValid && <section className="mixture-preview">
            <header>
               <div><strong>Materias primas necesarias</strong><p>{readyPreview ? `Para preparar ${formatQuantity(readyPreview.quantity)} ${readyPreview.mixture.unit}, según la fórmula guardada.` : "Consultando la fórmula real de la mezcla…"}</p></div>
              <Badge tone={previewBadgeTone}>{previewBadgeLabel}</Badge>
            </header>
            <div className="mixture-preview-list">
              {previewStatus === "loading" && <div className="mixture-preview-loading" role="status">Cargando materias primas…</div>}
              {previewStatus === "error" && <div className="mixture-preview-message error" role="alert">{previewError || "No se pudo cargar la fórmula de esta mezcla."}</div>}
              {readyPreview && !readyPreview.formulaConfigured && <div className="mixture-preview-message" role="status">Esta mezcla no tiene una fórmula configurada.</div>}
              {readyPreview && readyPreview.formulaConfigured && !readyPreview.formulaComplete && <div className="mixture-preview-message error" role="alert">No se pudo cargar la fórmula completa de esta mezcla.</div>}
              {readyPreview?.items.map((item) => {
                const required = Number(item.required), available = item.available === null ? null : Number(item.available), unit = String(item.unit || "unidad"), missing = available === null || available < required, cost = item.current_cost_cents === null ? null : Number(item.current_cost_cents), subtotal = item.subtotal_cents === null ? null : Number(item.subtotal_cents);
                return <article key={String(item.material_id)} className={missing || cost === null ? "is-invalid" : ""}>
                  <div className="mixture-preview-item-main"><strong>{String(item.code ?? "Materia prima")} · {String(item.material)}</strong><small>Necesitás {formatQuantity(required)} {unit} · Disponible {available === null ? "—" : `${formatQuantity(available)} ${unit}`}</small></div>
                  <div className="mixture-preview-item-cost"><small>Costo unitario</small><span>{cost === null || cost <= 0 ? "Sin costo" : `${money(cost / 100)} / ${unit}`}</span></div>
                  <div className="mixture-preview-item-subtotal"><small>Subtotal</small><b>{subtotal === null ? "—" : money(subtotal / 100)}</b></div>
                  <span className={`mixture-preview-item-status ${missing || cost === null ? "danger" : "success"}`}>{missing ? `Faltan ${formatQuantity(Math.max(0, required - (available ?? 0)))} ${unit}` : cost === null ? "Sin costo" : "✓ Stock suficiente"}</span>
                </article>;
              })}
               {readyPreview?.hasMissingCosts && <div className="mixture-preview-message error" role="alert">No se puede calcular correctamente el costo de esta preparación porque una o más materias primas no tienen costo.</div>}
             </div>
             {readyPreview && <div className="mixture-cost-summary mixture-stock-summary">
               <article><span>Stock actual de mezcla</span><strong>{formatQuantity(readyPreview.currentStock)} {readyPreview.mixture.unit}</strong></article>
               <article><span>Stock después de preparar</span><strong>{formatQuantity(readyPreview.stockAfter)} {readyPreview.mixture.unit}</strong></article>
               <article><span>Costo total</span><strong>{readyPreview.totalCostCents === null ? "Sin costo" : money(readyPreview.totalCostCents / 100)}</strong></article>
               <article><span>Costo unitario</span><strong>{readyPreview.unitCostCents === null ? "Sin costo" : `${money(readyPreview.unitCostCents / 100)} / ${readyPreview.mixture.unit}`}</strong></article>
             </div>}
           </section>}
           {!previewInputValid && <div className="recipe-empty">Ingresá una cantidad a preparar válida, mayor que cero.</div>}
          {error && <p className="form-error" role="alert">{error}</p>}
          <div className="material-zero-rule"><span>i</span><p>La simulación no mueve stock. Al confirmar, se descuenta cada materia prima y se crea un lote trazable con el costo congelado.</p></div>
        </div>
        <footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="primary-button" disabled={saving || !readyPreview?.canPrepare} onClick={prepare}>{saving ? "Confirmando…" : preparation ? "Guardar cambios" : "Confirmar preparación"}</button></footer>
      </aside>
    </div>
  );
}

function MixtureCancelDialog({ lot, onCancel, onSaved }: { lot: MixtureLotRow; onCancel: () => void; onSaved: (message: string) => void }) {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function cancel() {
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "cancel_mixture_preparation", id: lot.preparation_id }) });
      const result = await response.json() as { error?: string };
      if (!response.ok) throw new Error(result.error ?? "No se pudo anular la preparación.");
      onSaved(`Lote ${lot.lot_number} anulado y materias primas restauradas.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo anular la preparación."); } finally { setSaving(false); }
  }
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar anulación" /><section className="confirm-dialog category-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="mixture-cancel-title"><header><div><p>PRODUCCIÓN · MEZCLAS</p><h2 id="mixture-cancel-title">Anular preparación</h2><span>La acción revierte el consumo de materias primas y retira el lote del stock.</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="category-delete-body">{error ? <div className="confirm-note danger-note" role="alert"><i>!</i><p>{error}</p></div> : <><p>¿Seguro que querés anular el lote <strong>“{lot.lot_number}”</strong> de <strong>{lot.mixture}</strong>?</p><div className="confirm-note"><i>i</i><p>Solo se puede anular mientras el lote no tenga consumos.</p></div></>}</div><footer><button className="secondary-button" onClick={onCancel}>{error ? "Entendido" : "Cancelar"}</button>{!error && <button className="danger-button" disabled={saving} onClick={cancel}>{saving ? "Anulando…" : "Anular preparación"}</button>}</footer></section></div>;
}

function MixtureDeleteDialog({ lot, onCancel, onDeleted }: { lot: MixtureLotRow; onCancel: () => void; onDeleted: (message: string) => void }) {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function remove() {
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "delete_mixture_preparation", id: lot.preparation_id }) });
      const result = await response.json() as { error?: string };
      if (!response.ok) throw new Error(result.error ?? "No se pudo eliminar la preparación.");
      onDeleted(`Lote ${lot.lot_number} eliminado definitivamente.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo eliminar la preparación."); } finally { setSaving(false); }
  }
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar eliminación" /><section className="confirm-dialog category-delete-dialog" role="alertdialog" aria-modal="true" aria-labelledby="mixture-delete-title"><header><div><p>PRODUCCIÓN · MEZCLAS</p><h2 id="mixture-delete-title">Eliminar lote anulado</h2><span>Esta acción quita el registro definitivamente.</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="category-delete-body"><p>¿Seguro que querés eliminar el lote <strong>“{lot.lot_number}”</strong> de <strong>{lot.mixture}</strong>?</p><div className="confirm-note danger-note"><i>!</i><p>Se quitarán el lote anulado y sus movimientos asociados. Esta acción no se puede deshacer.</p></div>{error && <p className="form-error" role="alert">{error}</p>}</div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="danger-button" disabled={saving} aria-busy={saving} onClick={remove}>{saving ? "Eliminando…" : "Eliminar definitivamente"}</button></footer></section></div>;
}

function ComboPlanner() {
  const [quantity, setQuantity] = useState(5);
  const breakdown = getComboBreakdown("COM-001", quantity)!;
  const allChecks = [...breakdown.products, ...breakdown.materials];
  const ready = allChecks.every((item) => item.shortage === 0);
  return <><div className="combo-planner-hero"><div><span>K</span><div><small>COMBO INTELIGENTE</small><h2>{breakdown.product.name}</h2><p>KHORA expande productos, caja, tarjeta y packaging automáticamente.</p></div></div><label><span>Cantidad a preparar</span><input type="number" min="1" value={quantity} onChange={(event) => setQuantity(Math.max(1, Number(event.target.value) || 1))} /></label></div><div className="combo-requirements"><Panel title="Productos incluidos" subtitle="Stock terminado requerido"><div className="requirement-list">{breakdown.products.map((item) => <RequirementRow item={item} key={item.code} />)}</div></Panel><Panel title="Packaging e insumos" subtitle="Materias primas e insumos del combo"><div className="requirement-list">{breakdown.materials.map((item) => <RequirementRow item={item} key={item.code} />)}</div></Panel></div><div className={`combo-result ${ready ? "success" : "danger"}`}><span>{ready ? "✓" : "!"}</span><div><strong>{ready ? `Podés preparar ${quantity} combos` : "Hay componentes faltantes"}</strong><p>{ready ? "Todos los productos y materiales directos están disponibles." : "Revisá los faltantes antes de confirmar el armado."}</p></div><button disabled={!ready}>Preparar combos</button></div></>;
}

function BatchDetail({ batch, onClose }: { batch: (typeof batches)[number]; onClose: () => void }) {
  return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onClose} aria-label="Cerrar trazabilidad" /><aside className="batch-detail" role="dialog" aria-modal="true" aria-labelledby="batch-detail-title"><header><div><p>TRAZABILIDAD DEL LOTE</p><h2 id="batch-detail-title">{batch.lot}</h2></div><button onClick={onClose} aria-label="Cerrar">×</button></header><div className="batch-detail-body"><div className="batch-product"><span>⚗</span><div><strong>{batch.product}</strong><small>{batch.date} · {batch.quantity} unidades</small></div><Badge tone="success">{batch.status}</Badge></div><dl><div><dt>Costo total</dt><dd>{money(batch.cost)}</dd></div><div><dt>Costo unitario</dt><dd>{money(batch.unitCost)}</dd></div></dl><section><h3>Materiales utilizados</h3>{batch.materialsUsed.map((material) => <article key={material.name}><div><strong>{material.name}</strong><small>{material.quantity}</small></div><b>{money(material.cost)}</b></article>)}</section><div className="trace-note"><i>✓</i><span>Los costos corresponden a este lote y no cambian si los precios actuales se actualizan.</span></div></div></aside></div>;
}

type MaterialRecord = { id: number; code: string; name: string; category: string; categoryId: number; prefix: string; unit: string; stock: number; minimum: number; cost: number; supplier: string; supplierId?: number; notes?: string };
type MixtureStockRecord = MixtureRow;
type InventoryCategory = { id: number; name: string; prefix: string; kind: "MATERIAL"; active: boolean };
type InventorySupplier = { id: number; name: string };
type MovementRow = { id: number; created_at: string; item: string; movement: string; quantity_delta: number; balance_after: number; unit_cost_cents: number; notes?: string } & Record<string, unknown>;

function StockMixturesPanel({ rows, loading }: { rows: MixtureStockRecord[]; loading: boolean }) {
  return <Panel title="Mezclas" subtitle={loading ? "Actualizando…" : `${rows.length} mezclas visibles`}><DataTable headers={["Mezcla", "Stock disponible", "Mínimo", "Estado", "Costo unitario", "Valor en stock"]}>{rows.map((mixture) => { const stock = Number(mixture.current_stock) || 0, minimum = Number(mixture.minimum_stock) || 0, cost = Number(mixture.estimated_cost_cents) || 0, status = materialStockStatus(stock, minimum); return <tr key={mixture.id}><td><strong>{mixture.name}</strong><small className="table-sub">{mixture.code} · rendimiento {formatQuantity(Number(mixture.yield_quantity))} {mixture.unit}</small></td><td><StockValue value={stock} minimum={minimum} unit={mixture.unit} /></td><td>{formatQuantity(minimum)} {mixture.unit}</td><td><Badge tone={status.tone}>{status.label}</Badge></td><td>{money(cost / 100)} / {mixture.unit}</td><td><strong>{money(stock * cost / 100)}</strong></td></tr>; })}</DataTable>{!loading && !rows.length && <div className="recipe-empty">Todavía no hay mezclas preparadas.</div>}</Panel>;
}

function Stock({ search }: { search: string }) {
  const productData = useKhoraRows<ProductRow>("products");
  const movementData = useKhoraRows<MovementRow>("movements");
  const mixtureData = useKhoraRows<MixtureStockRecord>("mixtures");
  const [tab, setTab] = useState("Productos terminados");
  const [materialRows, setMaterialRows] = useState<MaterialRecord[]>([]);
  const [categoryRows, setCategoryRows] = useState<InventoryCategory[]>([]);
  const [supplierRows, setSupplierRows] = useState<InventorySupplier[]>([]);
  const [showMaterialForm, setShowMaterialForm] = useState(false);
  const [showCategoryForm, setShowCategoryForm] = useState(false);
  const [selectedMaterial, setSelectedMaterial] = useState<MaterialRecord | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<ProductRow | null>(null);
  const [editingMaterial, setEditingMaterial] = useState<MaterialRecord | null>(null);
  const [materialToDelete, setMaterialToDelete] = useState<MaterialRecord | null>(null);
  const [materialDeleteError, setMaterialDeleteError] = useState<{ kind: "blocked" | "error"; message: string } | null>(null);
  const [deletingMaterialId, setDeletingMaterialId] = useState<number | null>(null);
  const [categoryToDelete, setCategoryToDelete] = useState<InventoryCategory | null>(null);
  const [categoryDeleteError, setCategoryDeleteError] = useState<{ kind: "blocked" | "error"; message: string } | null>(null);
  const [deletingCategoryId, setDeletingCategoryId] = useState<number | null>(null);
  const [notice, setNotice] = useState("");
  // Los productos archivados se conservan para el historial, pero no deben
  // aparecer en el stock operativo ni en sus contadores.
  const productRows = productData.rows.filter((item) => Boolean(item.active) && includesSearch(item, search));
  const visibleMaterials = materialRows.filter((item) => includesSearch(item, search));
  const visibleMixtures = mixtureData.rows.filter((item) => Boolean(Number(item.active) || item.active === true) && includesSearch(item, search));

  useEffect(() => {
    let active = true;
    Promise.all(["materials", "categories", "suppliers"].map(async (entity) => {
      const response = await fetch(`/api/khora?entity=${entity}`);
      if (!response.ok) throw new Error("No se pudo leer el inventario");
      return response.json() as Promise<{ rows?: Array<Record<string, unknown>> }>;
    })).then(([materialData, categoryData, supplierData]) => {
      if (!active) return;
      const apiCategories = (categoryData.rows ?? []).filter((row) => row.kind === "MATERIAL").map((row) => ({ id: Number(row.id), name: String(row.name), prefix: String(row.prefix ?? categoryPrefix(String(row.name))), kind: "MATERIAL" as const, active: Boolean(row.active) }));
      const apiSuppliers = (supplierData.rows ?? []).filter((row) => Boolean(row.active)).map((row) => ({ id: Number(row.id), name: String(row.name) }));
      const apiMaterials = (materialData.rows ?? []).filter((row) => Boolean(row.active)).map((row) => ({ id: Number(row.id), code: String(row.code), name: String(row.material), category: String(row.category ?? "Sin categoría"), categoryId: Number(row.category_id), prefix: String(row.prefix ?? "MAT"), unit: String(row.unit), stock: Number(row.current_stock), minimum: Number(row.minimum_stock), cost: Number(row.current_cost_cents), supplier: String(row.preferred_supplier ?? "Sin proveedor"), supplierId: row.preferred_supplier_id ? Number(row.preferred_supplier_id) : undefined, notes: String(row.notes ?? "") }));
      setCategoryRows(apiCategories);
      setSupplierRows(apiSuppliers);
      setMaterialRows(apiMaterials);
    }).catch(() => undefined);
    return () => { active = false; };
  }, []);

  const critical = materialRows.filter((item) => item.stock < item.minimum).length;
  const normal = materialRows.filter((item) => item.stock > item.minimum * 1.25).length;
  const averageMaterialCost = materialRows.length ? materialRows.reduce((sum, item) => sum + item.cost, 0) / materialRows.length : 0;
  const activeProducts = productRows.filter((item) => Boolean(item.active));
  const normalProducts = activeProducts.filter((item) => Number(item.current_stock) > Number(item.minimum_stock)).length;
  const criticalProducts = activeProducts.filter((item) => Number(item.current_stock) <= 0).length;
  const lowProducts = activeProducts.filter((item) => Number(item.current_stock) > 0 && Number(item.current_stock) <= Number(item.minimum_stock)).length;
  function showNotice(message: string) { setNotice(message); window.setTimeout(() => setNotice(""), 3800); }

  return <div className="section-stack">
    <Tabs tabs={["Productos terminados", "Materias primas", "Mezclas", "Categorías", "Movimientos"]} active={tab} onChange={setTab} />
    {notice && <div className="inline-notice" role="status"><span>✓</span>{notice}</div>}
    {tab === "Productos terminados" ? <div className="summary-row"><MiniStat label="Productos activos" value={String(activeProducts.length)} detail={`${activeProducts.length} productos disponibles`} tone="info" /><MiniStat label="En nivel normal" value={String(normalProducts)} detail="Sin acción necesaria" tone="success" /><MiniStat label="Stock bajo" value={String(lowProducts)} detail="Planificar fabricación" tone="warning" /><MiniStat label="Críticos o sin stock" value={String(criticalProducts)} detail="Acción inmediata" tone="danger" /></div> : tab === "Materias primas" ? <div className="summary-row"><MiniStat label="Costo unitario promedio" value={money(averageMaterialCost / 100)} detail="Promedio vigente por insumo" tone="neutral" /><MiniStat label="En nivel normal" value={String(normal)} detail="Sin acción necesaria" tone="success" /><MiniStat label="Stock bajo" value={String(materialRows.length - normal - critical)} detail="Planificar reposición" tone="warning" /><MiniStat label="Críticos o sin stock" value={String(critical)} detail="Acción inmediata" tone="danger" /></div> : tab === "Mezclas" ? <div className="summary-row"><MiniStat label="Mezclas activas" value={String(visibleMixtures.length)} detail="Inventario intermedio" tone="info" /><MiniStat label="Mezclas con stock" value={String(visibleMixtures.filter((item) => Number(item.current_stock) > 0).length)} detail="Stock calculado desde lotes" tone="success" /><MiniStat label="Stock bajo" value={String(visibleMixtures.filter((item) => Number(item.current_stock) <= Number(item.minimum_stock)).length)} detail="Requieren preparación" tone="warning" /><MiniStat label="Costo promedio" value={visibleMixtures.length ? money(visibleMixtures.reduce((sum, item) => sum + Number(item.estimated_cost_cents), 0) / visibleMixtures.length / 100) : money(0)} detail="Por unidad de cada mezcla" tone="neutral" /></div> : null}
    {tab !== "Categorías" && tab !== "Movimientos" && <Toolbar placeholder="Buscar en el stock…" filters={["Todas las categorías", "Todos los estados"]} />}
    {tab === "Mezclas" && <StockMixturesPanel rows={visibleMixtures} loading={mixtureData.loading} />}
    {tab === "Productos terminados" && <Panel title="Productos terminados" subtitle={productData.loading ? "Actualizando…" : `${productRows.length} productos visibles`}><DataTable headers={["Producto", "Tipo", "Stock", "Mínimo", "Estado", "Costo unitario", "Valor", ""]}>{productRows.map((product) => { const cost = productCost(product), status = materialStockStatus(Number(product.current_stock), Number(product.minimum_stock)); return <tr key={product.id}><td><strong>{product.name}</strong><small className="table-sub">{product.code}</small></td><td>{productTypeLabel(product.type)}</td><td><StockValue value={Number(product.current_stock)} minimum={Number(product.minimum_stock)} unit="u." /></td><td>{Number(product.minimum_stock)} u.</td><td><Badge tone={status.tone}>{status.label}</Badge></td><td>{money(cost / 100)}</td><td><strong>{money(cost * Number(product.current_stock) / 100)}</strong></td><td><button className="more-button" aria-label={`Ver ficha y movimientos de ${product.name}`} title="Ver ficha y movimientos" onClick={() => setSelectedProduct(product)}>•••</button></td></tr>; })}</DataTable>{!productData.loading && !productRows.length && <div className="recipe-empty">Todavía no hay productos registrados.</div>}</Panel>}
    {tab === "Materias primas" && <Panel title="Materias primas" subtitle={`${visibleMaterials.length} insumos visibles`} action={<button className="primary-button" onClick={() => setShowMaterialForm(true)}>＋ Nueva materia prima</button>}><DataTable headers={["Materia prima", "Categoría", "Stock", "Mínimo", "Estado", "Costo", "Proveedor", "Acciones"]}>{visibleMaterials.map((material) => { const status = materialStockStatus(material.stock, material.minimum); return <tr key={material.code}><td><strong>{material.name}</strong><small className="table-sub">{material.code}</small></td><td>{material.category}</td><td><StockValue value={material.stock} minimum={material.minimum} unit={material.unit} /></td><td>{formatQuantity(material.minimum)} {material.unit}</td><td><Badge tone={status.tone}>{status.label}</Badge></td><td>{money(material.cost / 100)} / {material.unit}</td><td>{material.supplier}</td><td className="table-actions"><button className="table-open-button" onClick={() => setSelectedMaterial(material)}>Ver ficha</button><button className="row-icon-button edit" type="button" title="Editar materia prima" aria-label={`Editar materia prima ${material.name}`} onClick={() => setEditingMaterial(material)}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 16-.7 4.7L8 20l11.3-11.3a2 2 0 0 0-2.8-2.8L5.2 17.2M14.5 7.5l2 2" /></svg></button><button className="row-icon-button delete" type="button" title="Eliminar materia prima" aria-label={`Eliminar materia prima ${material.name}`} onClick={() => { setMaterialDeleteError(null); setMaterialToDelete(material); }}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 7h12M9 7V5h6v2m-7 3v7m4-7v7m4-7v7M7 7l1 13h8l1-13" /></svg></button></td></tr>; })}</DataTable>{!visibleMaterials.length && <div className="recipe-empty">Todavía no hay materias primas registradas.</div>}</Panel>}
    {tab === "Categorías" && <Panel title="Categorías de materias primas" subtitle="El prefijo organiza y valida los códigos" action={<button className="primary-button" onClick={() => setShowCategoryForm(true)}>＋ Nueva categoría</button>}><div className="inventory-category-grid">{categoryRows.map((category) => <article key={category.id}><span>{category.prefix}</span><div className="category-copy"><strong>{category.name}</strong><small>{materialRows.filter((item) => item.categoryId === category.id).length} materias primas</small></div><div className="category-actions"><Badge tone={category.active ? "success" : "neutral"}>{category.active ? "Activa" : "Inactiva"}</Badge><button className="category-delete-button" type="button" title="Eliminar categoría" aria-label={`Eliminar categoría ${category.name}`} onClick={() => { setCategoryDeleteError(null); setCategoryToDelete(category); }}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 7h12M9 7V5h6v2m-7 3v7m4-7v7m4-7v7M7 7l1 13h8l1-13" /></svg></button></div></article>)}</div></Panel>}
    {tab === "Movimientos" && <MovementList rows={movementData.rows} loading={movementData.loading} />}
    {showMaterialForm && <MaterialFormDialog categories={categoryRows.filter((category) => category.active)} suppliers={supplierRows} existingCodes={materialRows.map((item) => item.code)} onCancel={() => setShowMaterialForm(false)} onSaved={(material) => { setMaterialRows((current) => [...current, material]); setShowMaterialForm(false); showNotice(`${material.name} fue creada con stock inicial 0.`); }} />}
    {editingMaterial && <MaterialFormDialog material={editingMaterial} categories={categoryRows.filter((category) => category.active || category.id === editingMaterial.categoryId)} suppliers={supplierRows} existingCodes={materialRows.map((item) => item.code)} onCancel={() => setEditingMaterial(null)} onSaved={(material) => { setMaterialRows((current) => current.map((item) => item.id === material.id ? material : item)); setEditingMaterial(null); showNotice("Materia prima actualizada correctamente."); }} />}
    {showCategoryForm && <CategoryFormDialog onCancel={() => setShowCategoryForm(false)} onSaved={(category) => { setCategoryRows((current) => [...current, category]); setShowCategoryForm(false); showNotice(`Categoría ${category.name} creada.`); }} />}
    {selectedMaterial && <MaterialDetail material={selectedMaterial} onClose={() => setSelectedMaterial(null)} />}
    {selectedProduct && <ProductStockDetail product={selectedProduct} onClose={() => setSelectedProduct(null)} />}
    {materialToDelete && <MaterialDeleteDialog material={materialToDelete} error={materialDeleteError} deleting={deletingMaterialId === materialToDelete.id} onCancel={() => { setMaterialToDelete(null); setMaterialDeleteError(null); }} onConfirm={async () => { setDeletingMaterialId(materialToDelete.id); setMaterialDeleteError(null); try { const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "delete_material", id: materialToDelete.id }) }); const result = await response.json() as { error?: string; referenceCount?: number; deactivated?: boolean }; if (!response.ok) { setMaterialDeleteError({ kind: "error", message: "No pudimos eliminar la materia prima. Intentá nuevamente." }); return; } setMaterialRows((current) => current.filter((item) => item.id !== materialToDelete.id)); setMaterialToDelete(null); showNotice(result.deactivated ? "Materia prima archivada para proteger su historial." : "Materia prima eliminada correctamente."); } catch (cause) { console.error(cause); setMaterialDeleteError({ kind: "error", message: "No pudimos eliminar la materia prima. Intentá nuevamente." }); } finally { setDeletingMaterialId(null); } }} />}
    {categoryToDelete && <CategoryDeleteDialog category={categoryToDelete} error={categoryDeleteError} deleting={deletingCategoryId === categoryToDelete.id} onCancel={() => { setCategoryToDelete(null); setCategoryDeleteError(null); }} onConfirm={async () => { setDeletingCategoryId(categoryToDelete.id); setCategoryDeleteError(null); try { const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "delete_category", id: categoryToDelete.id }) }); const result = await response.json() as { error?: string; code?: string }; if (!response.ok) { setCategoryDeleteError({ kind: result.code === "CATEGORY_IN_USE" ? "blocked" : "error", message: result.code === "CATEGORY_IN_USE" ? (result.error ?? "Esta categoría tiene registros asociados y no se puede eliminar.") : "No pudimos eliminar la categoría. Intentá nuevamente." }); return; } setCategoryRows((current) => current.filter((category) => category.id !== categoryToDelete.id)); setCategoryToDelete(null); showNotice("Categoría eliminada correctamente."); } catch (cause) { console.error(cause); setCategoryDeleteError({ kind: "error", message: "No pudimos eliminar la categoría. Intentá nuevamente." }); } finally { setDeletingCategoryId(null); } }} />}
  </div>;
}

type ProductStockDetailData = { product?: ProductRow & { category?: string; unit_cost_cents?: number }; movements?: MovementRow[]; batches?: Array<{ id: number; batch_number: string; occurred_at: string; initial_quantity: number; available_quantity: number; unit_cost_cents: number; source: string }> };

function ProductStockDetail({ product, onClose }: { product: ProductRow; onClose: () => void }) {
  const [data, setData] = useState<ProductStockDetailData>({}), [loading, setLoading] = useState(true), [error, setError] = useState("");
  useEffect(() => { let active = true; fetch(`/api/khora?entity=product_detail&id=${product.id}`).then(async (response) => { const result = await response.json() as ProductStockDetailData & { error?: string }; if (!response.ok) throw new Error(result.error ?? "No se pudo cargar la ficha"); if (active) setData(result); }).catch((cause) => { if (active) setError(cause instanceof Error ? cause.message : "No se pudo cargar la ficha"); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [product.id]);
  const current = data.product ?? product, cost = Number((data.product as { unit_cost_cents?: number } | undefined)?.unit_cost_cents ?? productCost(product)), movements = data.movements ?? [], batches = data.batches ?? [], currentStatus = materialStockStatus(Number(current.current_stock), Number(current.minimum_stock));
  return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onClose} aria-label="Cerrar ficha del producto" /><aside className="material-detail product-stock-detail" role="dialog" aria-modal="true" aria-labelledby="product-stock-title"><header><div><p>{current.code} · STOCK TERMINADO</p><h2 id="product-stock-title">{current.name}</h2><span>Ficha y trazabilidad exclusiva de este producto.</span></div><button onClick={onClose} aria-label="Cerrar">×</button></header><div className="material-detail-body">{loading ? <div className="recipe-empty">Cargando movimientos…</div> : error ? <p className="form-error" role="alert">{error}</p> : <><section className="material-detail-hero"><div><small>STOCK ACTUAL</small><strong>{formatQuantity(Number(current.current_stock))} <i>u.</i></strong><Badge tone={currentStatus.tone}>{currentStatus.label}</Badge></div><div><small>VALOR EN STOCK</small><strong>{money(cost * Number(current.current_stock) / 100)}</strong><span>{money(cost / 100)} por unidad</span></div></section><section className="product-stock-section"><div><h3>Lotes disponibles</h3><span>{batches.length} lotes registrados</span></div>{batches.length ? <div className="material-usage-list">{batches.map((batch) => <article key={`${batch.source}-${batch.id}`}><span>{batch.source}</span><div><strong>{batch.batch_number}</strong><small>{formatDate(batch.occurred_at)} · Inicial {formatQuantity(Number(batch.initial_quantity))} u.</small></div><b>{formatQuantity(Number(batch.available_quantity))} u.</b></article>)}</div> : <div className="recipe-empty">No hay lotes registrados.</div>}</section><section className="product-stock-section"><div><h3>Movimientos del producto</h3><span>{movements.length} movimientos auditables</span></div><MovementList rows={movements} loading={false} compact /></section></>}</div></aside></div>;
}

function MaterialFormDialog({ material, categories, suppliers, existingCodes, onCancel, onSaved }: { material?: MaterialRecord; categories: InventoryCategory[]; suppliers: InventorySupplier[]; existingCodes: string[]; onCancel: () => void; onSaved: (material: MaterialRecord) => void }) {
  const [name, setName] = useState(material?.name ?? "");
  const [categoryId, setCategoryId] = useState(material?.categoryId ?? categories[0]?.id ?? 0);
  const [unit, setUnit] = useState(material?.unit ?? "unidad");
  const [minimum, setMinimum] = useState(material?.minimum ?? 0);
  const [supplierId, setSupplierId] = useState<number | undefined>(material?.supplierId);
  const [notes, setNotes] = useState(material?.notes ?? "");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const category = categories.find((item) => item.id === categoryId) ?? categories[0];
  const activeCategoryId = category?.id;
  const [serverSuggestion, setServerSuggestion] = useState<{ categoryId: number; code: string } | null>(null);
  const localSuggestion = category ? suggestMaterialCode(category.prefix, existingCodes) : "MAT-001";
  const suggestedCode = serverSuggestion?.categoryId === activeCategoryId ? serverSuggestion.code : localSuggestion;

  useEffect(() => {
    if (!activeCategoryId) return;
    let active = true;
    if (material) return () => { active = false; };
    fetch(`/api/khora?entity=next_material_code&categoryId=${activeCategoryId}`).then((response) => response.ok ? response.json() as Promise<{ code?: string }> : Promise.reject()).then((data) => { if (active && data.code) setServerSuggestion({ categoryId: activeCategoryId, code: data.code }); }).catch(() => undefined);
    return () => { active = false; };
  }, [activeCategoryId, material]);

  async function save() {
    if (!name.trim()) { setError("Ingresá el nombre de la materia prima."); return; }
    if (!category) { setError("Primero creá una categoría de materia prima."); return; }
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "save_material", id: material?.id, name, categoryId: category.id, unit, minimumStock: minimum, preferredSupplierId: supplierId, notes }) });
      const result = await response.json() as { error?: string; material?: { id?: number; code?: string; current_stock?: number; minimum_stock?: number; minimumStock?: number; current_cost_cents?: number; currentCostCents?: number } };
      if (!response.ok) throw new Error(result.error ?? "No se pudo guardar la materia prima");
      const supplier = suppliers.find((item) => item.id === supplierId);
      const materialId = Number(result.material?.id);
      if (!Number.isInteger(materialId) || materialId <= 0) throw new Error("La materia prima se guardó, pero no se recibió su identificador.");
      onSaved({ id: materialId, code: result.material?.code ?? material?.code ?? suggestedCode, name: name.trim(), category: category.name, categoryId: category.id, prefix: category.prefix, unit, stock: result.material?.current_stock ?? material?.stock ?? 0, minimum: result.material?.minimum_stock ?? result.material?.minimumStock ?? minimum, cost: result.material?.current_cost_cents ?? result.material?.currentCostCents ?? material?.cost ?? 0, supplier: supplier?.name ?? "Sin proveedor", supplierId, notes });
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo guardar la materia prima"); } finally { setSaving(false); }
  }
  return <div className="drawer-layer">
    <button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar alta" />
    <aside className="inventory-form-drawer" role="dialog" aria-modal="true" aria-labelledby="new-material-title">
      <header><div><p>INVENTARIO · MATERIA PRIMA</p><h2 id="new-material-title">{material ? "Editar materia prima" : "Nueva materia prima"}</h2><span>{material ? "Actualizá la ficha sin modificar stock ni costos históricos." : "Crear el insumo no registra una compra ni modifica existencias."}</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header>
      <div className="inventory-form-body">
        {categories.length ? <>
          <div className="form-grid"><label><span>Categoría *</span><select value={categoryId} onChange={(event) => setCategoryId(Number(event.target.value))}>{categories.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.prefix}</option>)}</select></label><label className="automatic-code-field"><span>Código</span>{material ? <input value={material.code} readOnly aria-describedby="material-code-help" /> : <input value={suggestedCode} readOnly aria-describedby="material-code-help" />}<small id="material-code-help">{material ? "Identificador protegido; no cambia al editar." : "Generado automáticamente según la categoría"}</small></label></div>
          <label><span>Nombre *</span><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="Ej. Esencia de coco" /></label>
          <div className="form-grid"><label><span>Unidad base *</span><select value={unit} onChange={(event) => setUnit(event.target.value)}>{baseUnits.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><label><span>Stock mínimo</span><input type="number" min="0" step="0.01" value={minimum} onChange={(event) => setMinimum(Math.max(0, Number(event.target.value) || 0))} /></label></div>
          <label><span>Proveedor preferido</span><select value={supplierId ?? ""} onChange={(event) => setSupplierId(event.target.value ? Number(event.target.value) : undefined)}><option value="">Sin proveedor preferido</option>{suppliers.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
          <label><span>Notas <small>OPCIONAL</small></span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Presentación, marca o dato útil…" /></label>
          <div className="material-code-rule"><span>{category?.prefix}</span><p>El código queda estable después de crear la materia prima, aunque más adelante cambie su categoría.</p></div>
          <div className="zero-stock-preview"><span>{material ? formatQuantity(material.stock) : "0"}</span><div><strong>{material ? `Stock actual: ${formatQuantity(material.stock)} ${material.unit}` : `Stock inicial: 0 ${unit}`}</strong><p>El stock cambia únicamente mediante compras, fabricación o ajustes autorizados.</p></div></div>
        </> : <div className="recipe-no-materials"><strong>Todavía no hay categorías de materia prima</strong><p>Creá una categoría con prefijo antes de registrar el primer insumo.</p></div>}
        {error && <p className="form-error" role="alert">{error}</p>}
      </div>
      <footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="primary-button" disabled={saving || !categories.length} aria-busy={saving} onClick={save}>{saving ? "Guardando…" : material ? "Guardar cambios" : "Crear materia prima"}</button></footer>
    </aside>
  </div>;
}

function CategoryFormDialog({ onCancel, onSaved }: { onCancel: () => void; onSaved: (category: InventoryCategory) => void }) {
  const [name, setName] = useState("");
  const [prefix, setPrefix] = useState("MAT");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  async function save() {
    if (name.trim().length < 2 || prefix.length < 2) { setError("Completá un nombre y un prefijo de 2 a 4 caracteres."); return; }
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "save_category", name, prefix, kind: "MATERIAL" }) });
      const result = await response.json() as { error?: string; id?: number; prefix?: string };
      if (!response.ok) throw new Error(result.error ?? "No se pudo guardar la categoría");
      const categoryId = Number(result.id);
      if (!Number.isInteger(categoryId) || categoryId <= 0) throw new Error("La categoría se guardó, pero no se recibió su identificador.");
      onSaved({ id: categoryId, name: name.trim(), prefix: result.prefix ?? prefix, kind: "MATERIAL", active: true });
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo guardar la categoría"); } finally { setSaving(false); }
  }
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar" /><section className="confirm-dialog category-dialog" role="dialog" aria-modal="true" aria-labelledby="category-title"><header><div><p>ORGANIZACIÓN</p><h2 id="category-title">Nueva categoría</h2><span>El prefijo se usará en los códigos de sus materias primas.</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="category-form-body"><label><span>Nombre *</span><input autoFocus value={name} onChange={(event) => { const value = event.target.value; setName(value); setPrefix(categoryPrefix(value)); }} placeholder="Ej. Esencias" /></label><label><span>Prefijo *</span><input maxLength={4} value={prefix} onChange={(event) => setPrefix(event.target.value.replace(/[^a-z0-9]/gi, "").toUpperCase())} /></label>{error && <p className="form-error" role="alert">{error}</p>}</div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="primary-button" disabled={saving} aria-busy={saving} onClick={save}>{saving ? "Guardando…" : "Crear categoría"}</button></footer></section></div>;
}

function CategoryDeleteDialog({ category, error, deleting, onCancel, onConfirm }: { category: InventoryCategory; error: { kind: "blocked" | "error"; message: string } | null; deleting: boolean; onCancel: () => void; onConfirm: () => void }) {
  const blocked = error?.kind === "blocked";
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cerrar" /><section className="confirm-dialog category-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="category-delete-title"><header><div><p>CATEGORÍAS · MATERIAS PRIMAS</p><h2 id="category-delete-title">{blocked ? "No se puede eliminar esta categoría" : error ? "No pudimos eliminar la categoría" : "Eliminar categoría"}</h2><span>{blocked ? "La información asociada debe conservarse para proteger el historial." : error ? "Intentá nuevamente más tarde." : "Esta acción no se puede deshacer."}</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="category-delete-body">{error ? <div className={`confirm-note ${blocked ? "danger-note" : ""}`} role="alert"><i>{blocked ? "!" : "×"}</i><p>{error.message}</p></div> : <><p>¿Seguro que querés eliminar la categoría <strong>“{category.name}”</strong>?</p><div className="confirm-note"><i>i</i><p>Solo se puede eliminar si no tiene materias primas ni registros asociados.</p></div></>}</div><footer><button className="secondary-button" onClick={onCancel}>{error ? "Entendido" : "Cancelar"}</button>{!error && <button className="danger-button" disabled={deleting} aria-busy={deleting} onClick={onConfirm}>{deleting ? "Eliminando…" : "Eliminar categoría"}</button>}</footer></section></div>;
}

function MaterialDeleteDialog({ material, error, deleting, onCancel, onConfirm }: { material: MaterialRecord; error: { kind: "blocked" | "error"; message: string } | null; deleting: boolean; onCancel: () => void; onConfirm: () => void }) {
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cerrar" /><section className="confirm-dialog category-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="material-delete-title"><header><div><p>INVENTARIO · MATERIA PRIMA</p><h2 id="material-delete-title">{error ? "No pudimos eliminar la materia prima" : "Eliminar materia prima"}</h2><span>{error ? "Intentá nuevamente más tarde." : "Esta acción no se puede deshacer."}</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="category-delete-body">{error ? <div className="confirm-note danger-note" role="alert"><i>×</i><p>{error.message}</p></div> : <><p>¿Seguro que querés eliminar <strong>“{material.name}”</strong>?</p><p className="delete-code-line">Código: <strong>{material.code}</strong></p><div className="confirm-note"><i>i</i><p>Si tiene compras, recetas o movimientos, se archivará para conservar el historial.</p></div></>}</div><footer><button className="secondary-button" onClick={onCancel}>{error ? "Entendido" : "Cancelar"}</button>{!error && <button className="danger-button" disabled={deleting} aria-busy={deleting} onClick={onConfirm}>{deleting ? "Eliminando…" : "Eliminar materia prima"}</button>}</footer></section></div>;
}

function MaterialDetail({ material, onClose }: { material: MaterialRecord; onClose: () => void }) {
  const [tab, setTab] = useState("Resumen");
  const [materialSnapshot, setMaterialSnapshot] = useState<{ current_stock?: number; current_cost_cents?: number; stock_value_cents?: number } | null>(null);
  const [history, setHistory] = useState<{ purchases: Array<Record<string, unknown>>; movements: Array<Record<string, unknown>>; products: Array<Record<string, unknown>> }>({ purchases: [], movements: [], products: [] });
  const usedBy = productsUsingMaterial(material.code, recipeDefinitions, products);
  const status = materialStockStatus(material.stock, material.minimum);
  useEffect(() => {
    let active = true;
    fetch(`/api/khora?entity=material_detail&id=${material.id}`).then(async (response) => {
      if (!response.ok) throw new Error("Detalle no disponible");
      return response.json() as Promise<{ material?: { current_stock?: number; current_cost_cents?: number; stock_value_cents?: number }; purchases?: Array<Record<string, unknown>>; movements?: Array<Record<string, unknown>>; products?: Array<Record<string, unknown>> }>;
    }).then((data) => { if (active) { setMaterialSnapshot(data.material ?? null); setHistory({ purchases: data.purchases ?? [], movements: data.movements ?? [], products: data.products ?? [] }); } }).catch(() => undefined);
    return () => { active = false; };
  }, [material.id]);
  const linkedProducts = history.products.length ? history.products : usedBy.map((product) => ({ code: product.code, product: product.name }));
  const stock = Number(materialSnapshot?.current_stock ?? material.stock), costCents = Number(materialSnapshot?.current_cost_cents ?? Math.round(material.cost * 100)), valueCents = Number(materialSnapshot?.stock_value_cents ?? Math.round(stock * costCents));
  return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onClose} aria-label="Cerrar ficha" /><aside className="material-detail" role="dialog" aria-modal="true" aria-labelledby="material-detail-title"><header><div><p>{material.code} · {material.category}</p><h2 id="material-detail-title">{material.name}</h2><span>Ficha maestra de inventario</span></div><button onClick={onClose} aria-label="Cerrar">×</button></header><div className="material-detail-body"><section className="material-detail-hero"><div><small>STOCK ACTUAL</small><strong>{formatQuantity(stock)} <i>{material.unit}</i></strong><Badge tone={status.tone}>{status.label}</Badge></div><div><small>VALOR EN STOCK</small><strong>{money(valueCents / 100)}</strong><span>{formatQuantity(stock)} {material.unit} × {money(costCents / 100)} / {material.unit}</span></div></section><Tabs tabs={["Resumen", "Compras", "Movimientos", "Productos que la utilizan"]} active={tab} onChange={setTab} />{tab === "Resumen" && <div className="material-master-data"><dl><div><dt>Categoría</dt><dd>{material.category}</dd></div><div><dt>Unidad base</dt><dd>{material.unit}</dd></div><div><dt>Stock mínimo</dt><dd>{formatQuantity(material.minimum)} {material.unit}</dd></div><div><dt>Proveedor preferido</dt><dd>{material.supplier}</dd></div></dl><div className="material-zero-rule"><span>i</span><p>El valor en stock se calcula como stock actual × costo vigente por {material.unit}. Crear o editar esta ficha no modifica existencias.</p></div>{material.notes && <section><small>NOTAS</small><p>{material.notes}</p></section>}</div>}{tab === "Compras" && (history.purchases.length ? <div className="material-usage-list">{history.purchases.map((purchase) => <article key={String(purchase.id)}><span>{String(purchase.purchased_at).slice(0, 10)}</span><div><strong>{String(purchase.supplier ?? "Sin proveedor")}</strong><small>{formatQuantity(Number(purchase.input_quantity))} {String(purchase.input_unit ?? material.unit)} → {formatQuantity(Number(purchase.base_quantity))} {String(purchase.base_unit ?? material.unit)} · Total compra: {money(Number(purchase.total_cost_cents) / 100)} · {money(Number(purchase.unit_cost_cents) / 100)} / {String(purchase.base_unit ?? material.unit)}</small></div><Badge tone={purchase.status === "CONFIRMED" ? "success" : "neutral"}>{purchase.status === "CONFIRMED" ? "Confirmada" : "Anulada"}</Badge></article>)}</div> : <div className="empty-material-tab"><span>↓</span><strong>Sin compras registradas</strong><p>Las compras confirmadas aparecerán aquí con proveedor, cantidad, unidad y costo histórico.</p></div>)}{tab === "Movimientos" && (history.movements.length ? <div className="material-usage-list">{history.movements.map((movement) => <article key={String(movement.id)}><span>{Number(movement.quantity_delta) > 0 ? "+" : "−"}{formatQuantity(Math.abs(Number(movement.quantity_delta)))}</span><div><strong>{String(movement.movement_type).replaceAll("_", " ")}</strong><small>{String(movement.created_at).slice(0, 16)} · saldo {formatQuantity(Number(movement.balance_after))} {material.unit}</small></div><Badge tone={Number(movement.quantity_delta) > 0 ? "success" : "info"}>Auditable</Badge></article>)}</div> : <div className="empty-material-tab"><span>↕</span><strong>Sin movimientos todavía</strong><p>Ingresos, consumos, ventas y ajustes conservarán su referencia y saldo resultante.</p></div>)}{tab === "Productos que la utilizan" && <div className="material-usage-list">{linkedProducts.length ? linkedProducts.map((product) => <article key={String(product.code)}><span>{String(product.code)}</span><div><strong>{String(product.product)}</strong><small>Receta de fabricación activa</small></div><button>Ver producto →</button></article>) : <div className="empty-material-tab"><strong>No participa en recetas activas</strong><p>Podés incorporarla cuando armes o edites una receta.</p></div>}</div>}</div></aside></div>;
}

type PurchaseRow = { id: number; purchased_at: string; category?: string; code: string; material: string; input_quantity: number; input_unit: string; base_quantity: number; base_unit: string; supplier?: string; unit_cost_cents: number; total_cost_cents: number; paid_cents?: number; pending_cents?: number; payment_status: string; invoice_number?: string; status: string; notes?: string } & Record<string, unknown>;
type MaterialApiRow = { id: number; code: string; material: string; unit: string; current_stock: number; minimum_stock: number; current_cost_cents: number; preferred_supplier?: string; active: boolean } & Record<string, unknown>;

function Purchases({ search, onCreate }: { search: string; onCreate?: (kind: string, section?: SectionId) => void }) {
  const purchaseData = useKhoraRows<PurchaseRow>("purchases");
  const materialData = useKhoraRows<MaterialApiRow>("materials");
  const [tab, setTab] = useState("Necesidades de compra");
  const [showPurchaseForm, setShowPurchaseForm] = useState(false);
  const [editingPurchase, setEditingPurchase] = useState<PurchaseRow | null>(null);
  const [viewingPurchase, setViewingPurchase] = useState<PurchaseRow | null>(null);
  const [deletingPurchase, setDeletingPurchase] = useState<PurchaseRow | null>(null);
  const [cancelingPurchase, setCancelingPurchase] = useState<PurchaseRow | null>(null);
  const [notice, setNotice] = useState("");
  const [purchaseQuery, setPurchaseQuery] = useState(search);
  const [purchaseDateFilter, setPurchaseDateFilter] = useState<SaleDateFilter>("all");
  const [purchaseCustomDate, setPurchaseCustomDate] = useState("");
  const [purchaseMaterialFilter, setPurchaseMaterialFilter] = useState("all");
  const [purchasePaymentFilter, setPurchasePaymentFilter] = useState("all");
  const needs = materialData.rows.filter((material) => material.active && Number(material.current_stock) <= Number(material.minimum_stock)).map((material) => ({ ...material, shortage: Math.max(0, Number(material.minimum_stock) - Number(material.current_stock)), suggested: Math.max(Number(material.minimum_stock) - Number(material.current_stock), Number(material.minimum_stock) > 0 ? Number(material.minimum_stock) * 0.25 : 1) }));
  useEffect(() => { if (!search) return; const timeout = window.setTimeout(() => setTab("Compras registradas"), 0); return () => window.clearTimeout(timeout); }, [search]);
  useEffect(() => { setPurchaseQuery(search); }, [search]);
  const rows = purchaseData.rows.filter((purchase) => {
    const query = purchaseQuery.trim().toLocaleLowerCase("es");
    const searchablePurchaseId = "c-" + purchase.id;
    if (query && !includesSearch(purchase, purchaseQuery) && ![searchablePurchaseId, String(purchase.invoice_number ?? "")].some((value) => value.toLocaleLowerCase("es").includes(query))) return false;
    if (!saleMatchesDate(String(purchase.purchased_at), purchaseDateFilter, purchaseCustomDate)) return false;
    if (purchaseMaterialFilter !== "all" && purchase.code !== purchaseMaterialFilter) return false;
    if (purchasePaymentFilter !== "all" && String(purchase.payment_status).toUpperCase() !== purchasePaymentFilter) return false;
    return true;
  });
  const purchaseMaterialOptions = Array.from(new Map(purchaseData.rows.map((purchase) => [purchase.code, String(purchase.code) + " · " + String(purchase.material)]))).sort((a, b) => a[1].localeCompare(b[1], "es"));
  const totalCents = rows.reduce((sum, purchase) => sum + Number(purchase.total_cost_cents), 0);
  const unpaidCents = rows.filter((purchase) => purchase.payment_status !== "PAID").reduce((sum, purchase) => sum + Number(purchase.total_cost_cents), 0);
  function saved(message: string) { setShowPurchaseForm(false); purchaseData.refresh(); materialData.refresh(); setNotice(message); window.setTimeout(() => setNotice(""), 4200); }
  const error = purchaseData.error || materialData.error;
  return <div className="section-stack"><Tabs tabs={["Necesidades de compra", "Compras registradas"]} active={tab} onChange={setTab} />{error && <div className="inline-notice error"><span>!</span>{error}</div>}{notice && <div className="inline-notice" role="status"><span>✓</span>{notice}</div>}<div className="purchase-create-row"><div><strong>Compras con conversión automática</strong><span>Seleccioná una materia prima existente; el costo promedio se calcula al confirmar.</span></div><div className="purchase-create-actions"><button className="primary-button" onClick={() => onCreate?.("gasto", "finanzas")}>＋ Nuevo gasto</button><button className="primary-button" onClick={() => setShowPurchaseForm(true)}>＋ Nueva compra</button></div></div>{tab === "Necesidades de compra" && <><div className="summary-row"><MiniStat label="Insumos a comprar" value={String(needs.length)} detail="Según stock mínimo" tone="warning" /><MiniStat label="Sin stock" value={String(needs.filter((need) => Number(need.current_stock) <= 0).length)} detail="Atención inmediata" tone="danger" /><MiniStat label="Bajo mínimo" value={String(needs.filter((need) => Number(need.current_stock) > 0).length)} detail="Planificar reposición" tone="info" /><MiniStat label="Compras automáticas" value="0" detail="Siempre requieren confirmación" tone="success" /></div><div className="purchase-method"><span>i</span><div><strong>Cómo calcula KHORA</strong><p>Compara el stock actual con el mínimo configurado. Nunca crea compras automáticamente.</p></div></div><div className="purchase-needs-grid">{needs.map((need) => <article key={need.id}><header><span>{need.code}</span><Badge tone={Number(need.current_stock) <= 0 ? "danger" : "warning"}>{Number(need.current_stock) <= 0 ? "Sin stock" : "Reposición"}</Badge></header><h3>{need.material}</h3><dl><div><dt>Stock</dt><dd>{formatQuantity(Number(need.current_stock))} {need.unit}</dd></div><div><dt>Mínimo</dt><dd>{formatQuantity(Number(need.minimum_stock))} {need.unit}</dd></div><div className="purchase-shortage"><dt>Sugerido</dt><dd>{formatQuantity(need.suggested)} {need.unit}</dd></div></dl><div className="purchase-supplier"><span>Proveedor habitual</span><strong>{need.preferred_supplier || "Sin proveedor"}</strong><small>Costo promedio: {money(Number(need.current_cost_cents) / 100)} / {need.unit}</small></div><button onClick={() => setShowPurchaseForm(true)}>Registrar compra</button></article>)}</div>{!materialData.loading && !needs.length && <div className="recipe-empty">No hay materias primas por debajo del mínimo.</div>}</>}{tab === "Compras registradas" && <><div className="summary-row"><MiniStat label="Compras registradas" value={money(totalCents / 100)} detail={`${rows.length} operaciones`} tone="info" /><MiniStat label="Por pagar" value={money(unpaidCents / 100)} detail={`${rows.filter((purchase) => purchase.payment_status !== "PAID").length} pendientes`} tone="warning" /><MiniStat label="Confirmadas" value={String(rows.filter((purchase) => purchase.status === "Confirmada").length)} detail="Ingresaron al stock" tone="success" /><MiniStat label="Anuladas" value={String(rows.filter((purchase) => purchase.status === "Anulada").length)} detail="Sin impacto vigente" tone="neutral" /></div><div className="toolbar purchases-toolbar"><label className="purchases-search-field" aria-label="Buscar compras"><KhoraIcon name="search" /><input value={purchaseQuery} onChange={(event) => setPurchaseQuery(event.target.value)} placeholder="Buscar compra, proveedor o comprobante…" /></label><div className="purchases-filter-controls"><label><span>Fecha</span><select aria-label="Filtrar compras por fecha" value={purchaseDateFilter} onChange={(event) => { const next = event.target.value as SaleDateFilter; setPurchaseDateFilter(next); if (next !== "custom") setPurchaseCustomDate(""); }}><option value="all">Todas las fechas</option><option value="today">Hoy</option><option value="week">Esta semana</option><option value="month">Este mes</option><option value="last30">Últimos 30 días</option><option value="custom">Fecha específica</option></select>{purchaseDateFilter === "custom" && <input type="date" aria-label="Elegir fecha exacta de compras" value={purchaseCustomDate} onChange={(event) => setPurchaseCustomDate(event.target.value)} />}</label><label><span>Materia prima</span><select aria-label="Filtrar compras por materia prima" value={purchaseMaterialFilter} onChange={(event) => setPurchaseMaterialFilter(event.target.value)}><option value="all">Todas las materias primas</option>{purchaseMaterialOptions.map(([code, label]) => <option key={code} value={code}>{label}</option>)}</select></label><label><span>Pago</span><select aria-label="Filtrar compras por pago" value={purchasePaymentFilter} onChange={(event) => setPurchasePaymentFilter(event.target.value)}><option value="all">Todos los pagos</option><option value="PAID">Pagado</option><option value="UNPAID">Pendiente</option></select></label></div></div><Panel title="Compras a proveedores" subtitle={purchaseData.loading ? "Actualizando…" : `${rows.length} compras encontradas`}><DataTable headers={["Compra", "Fecha", "Proveedor", "Detalle", "Cantidad", "Total", "Pago", "Estado", "Acciones"]}>{rows.map((purchase) => <tr key={purchase.id}><td><strong>C-{purchase.id}</strong><small className="table-sub">{purchase.invoice_number || "Sin comprobante"}</small></td><td>{formatDate(purchase.purchased_at)}</td><td><CellPerson name={purchase.supplier || "Sin proveedor"} /></td><td><strong>{purchase.material}</strong><small className="table-sub">{purchase.code} · {purchase.category || "Sin categoría"}</small></td><td>{formatQuantity(Number(purchase.input_quantity))} {purchase.input_unit}</td><td><strong>{money(Number(purchase.total_cost_cents) / 100)}</strong></td><td><Badge tone={purchase.payment_status === "PAID" ? "success" : "warning"}>{purchase.payment_status === "PAID" ? "Pagado" : "Pendiente"}</Badge></td><td><Badge tone={purchase.status === "Confirmada" ? "success" : "neutral"}>{purchase.status}</Badge></td><td><div className="table-row-actions"><Button variant="secondary" size="sm" icon={<KhoraIcon name="eye" />} onClick={() => setViewingPurchase(purchase)}>Ver detalle</Button><Button variant="secondary" size="sm" icon={<KhoraIcon name="pencil" />} onClick={() => setEditingPurchase(purchase)}>Editar</Button>{purchase.status === "Confirmada" ? <Button variant="danger" size="sm" icon={<KhoraIcon name="x" />} onClick={() => setCancelingPurchase(purchase)}>Anular</Button> : <Button variant="danger" size="sm" iconOnly icon={<KhoraIcon name="trash" />} title="Eliminar compra" aria-label={`Eliminar compra C-${purchase.id}`} onClick={() => setDeletingPurchase(purchase)} />}</div></td></tr>)}</DataTable>{!purchaseData.loading && !rows.length && <div className="recipe-empty">Todavía no hay compras registradas.</div>}</Panel></>}{showPurchaseForm && <PurchaseFormDialog onCancel={() => setShowPurchaseForm(false)} onSaved={saved} />} {editingPurchase && <PurchaseFormDialog purchase={editingPurchase} onCancel={() => setEditingPurchase(null)} onSaved={(message) => { setEditingPurchase(null); saved(message); }} />} {viewingPurchase && <PurchaseDetailDialog purchase={viewingPurchase} onClose={() => setViewingPurchase(null)} onEdit={() => { setViewingPurchase(null); setEditingPurchase(viewingPurchase); }} />} {cancelingPurchase && <PurchaseCancelDialog purchase={cancelingPurchase} onCancel={() => setCancelingPurchase(null)} onCancelled={(message) => { setCancelingPurchase(null); saved(message); }} />} {deletingPurchase && <PurchaseDeleteDialog purchase={deletingPurchase} onCancel={() => setDeletingPurchase(null)} onDeleted={(message) => { setDeletingPurchase(null); saved(message); }} />}</div>;
}

// Conservado temporalmente como referencia visual del planificador anterior.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyPurchases({ search, onCreate }: { search: string; onCreate?: (kind: string, section?: SectionId) => void }) {
  const rows = purchases.filter((purchase) => includesSearch(purchase, search));
  const needs = getPurchaseNeeds();
  const [tab, setTab] = useState("Necesidades de compra");
  const [selectedNeed, setSelectedNeed] = useState<PurchaseNeed | null>(null);
  const [showPurchaseForm, setShowPurchaseForm] = useState(false);
  const [notice, setNotice] = useState("");
  useEffect(() => { if (!search) return; const timeout = window.setTimeout(() => setTab("Compras registradas"), 0); return () => window.clearTimeout(timeout); }, [search]);
  function confirmPurchase(quantity: number) { const name = selectedNeed?.name ?? "Insumo"; setSelectedNeed(null); setNotice(`Compra preparada: ${name} · ${formatQuantity(quantity)}. Falta confirmar proveedor y precio.`); window.setTimeout(() => setNotice(""), 3600); }
  return <div className="section-stack"><Tabs tabs={["Necesidades de compra", "Compras registradas"]} active={tab} onChange={setTab} />{notice && <div className="inline-notice" role="status"><span>✓</span>{notice}</div>}<div className="purchase-create-row"><div><strong>Compras con conversión automática</strong><span>Seleccioná una materia prima existente; el costo promedio se calcula al confirmar.</span></div><div className="purchase-create-actions"><button className="primary-button" onClick={() => onCreate?.("gasto", "finanzas")}>＋ Nuevo gasto</button><button className="primary-button" onClick={() => setShowPurchaseForm(true)}>＋ Nueva compra</button></div></div>{tab === "Necesidades de compra" && <><div className="summary-row"><MiniStat label="Insumos a comprar" value={String(needs.length)} detail="Stock mínimo + producción" tone="warning" /><MiniStat label="Para producción" value={String(needs.filter((need) => need.requiredForPlan > 0).length)} detail="Afectados por pedidos" tone="danger" /><MiniStat label="Sólo reposición" value={String(needs.filter((need) => need.requiredForPlan === 0).length)} detail="Debajo del mínimo" tone="info" /><MiniStat label="Compras automáticas" value="0" detail="Siempre requieren confirmación" tone="success" /></div><div className="purchase-method"><span>i</span><div><strong>Cómo calcula KHORA</strong><p>Stock mínimo + insumos para la fabricación sugerida − stock disponible. No crea compras automáticamente.</p></div></div><div className="purchase-needs-grid">{needs.map((need) => <article key={need.code}><header><span>{need.code}</span><Badge tone={need.requiredForPlan > 0 ? "danger" : "warning"}>{need.requiredForPlan > 0 ? "Pedido" : "Reposición"}</Badge></header><h3>{need.name}</h3><dl><div><dt>Stock</dt><dd>{formatQuantity(need.stock)} {need.unit}</dd></div><div><dt>Necesario</dt><dd>{formatQuantity(need.requiredForPlan)} {need.unit}</dd></div><div className="purchase-shortage"><dt>Comprar</dt><dd>{formatQuantity(need.shortage)} {need.unit}</dd></div></dl><div className="purchase-supplier"><span>Proveedor habitual</span><strong>{need.supplier}</strong><small>Último precio: {money(need.lastPrice)} / {need.unit}</small></div><button onClick={() => setShowPurchaseForm(true)}>Registrar compra</button></article>)}</div></>}{tab === "Compras registradas" && <><div className="summary-row"><MiniStat label="Compras de agosto" value={money(284900)} detail="3 compras registradas" tone="info" /><MiniStat label="Por pagar" value={money(118400)} detail="1 compra pendiente" tone="warning" /><MiniStat label="Recibidas" value="2" detail="Ingresaron al stock" tone="success" /><MiniStat label="Pendientes" value="1" detail="Recepción parcial" tone="neutral" /></div><Toolbar placeholder="Buscar compra, proveedor o comprobante…" filters={["Este mes", "Todos los estados", "Todos los pagos"]} /><Panel title="Compras a proveedores" subtitle={`${rows.length} compras encontradas`} action={<Button variant="secondary" size="sm" icon={<KhoraIcon name="download" />}>Exportar</Button>}><DataTable headers={["Compra", "Fecha", "Proveedor", "Detalle", "Total", "Pago", "Recepción", ""]}>{rows.map((purchase) => <tr key={purchase.id}><td><strong>{purchase.id}</strong></td><td>{purchase.date}</td><td><CellPerson name={purchase.supplier} /></td><td>{purchase.detail}</td><td><strong>{money(purchase.total)}</strong></td><td><Badge tone={purchase.payment === "Pagado" ? "success" : "warning"}>{purchase.payment}</Badge></td><td><Badge tone={purchase.tone}>{purchase.status}</Badge></td><td><MoreButton /></td></tr>)}</DataTable></Panel></>}{selectedNeed && <ActionConfirmDialog key={selectedNeed.code} title={`Crear compra de ${selectedNeed.name}`} subtitle={`Proveedor habitual: ${selectedNeed.supplier}`} defaultQuantity={selectedNeed.shortage} unit={selectedNeed.unit} confirmLabel="Preparar compra" note="La compra queda lista para revisar. El stock cambia recién al registrar la recepción." onCancel={() => setSelectedNeed(null)} onConfirm={confirmPurchase} />}{showPurchaseForm && <PurchaseFormDialog onCancel={() => setShowPurchaseForm(false)} onSaved={(message) => { setShowPurchaseForm(false); setNotice(message); window.setTimeout(() => setNotice(""), 4200); }} />}</div>;
}

function PurchaseFormDialog({ purchase, onCancel, onSaved }: { purchase?: PurchaseRow; onCancel: () => void; onSaved: (message: string) => void }) {
  const [catalog, setCatalog] = useState<MaterialRecord[]>([]);
  const [supplierCatalog, setSupplierCatalog] = useState<InventorySupplier[]>([]);
  const [materialId, setMaterialId] = useState(0);
  const [supplierId, setSupplierId] = useState<number | undefined>();
  const [quantity, setQuantity] = useState(1);
  const [unit, setUnit] = useState("unidad");
  const [totalPesos, setTotalPesos] = useState(0);
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [paymentStatus, setPaymentStatus] = useState("PAID");
  const [invoiceNumber, setInvoiceNumber] = useState("");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const editing = Boolean(purchase);
  const material = catalog.find((item) => item.id === materialId) ?? catalog[0];
  const unitOptions = baseUnits.map((candidate) => { try { convertUnit(1, candidate.id, material?.unit ?? "unidad"); return { ...candidate, compatible: true }; } catch { return { ...candidate, compatible: false }; } });
  let projection: ReturnType<typeof purchaseProjection> | null = null;
  try { if (material && quantity > 0 && totalPesos >= 0) projection = purchaseProjection(material.stock, material.cost, quantity, unit, material.unit, Math.round(totalPesos * 100)); } catch { projection = null; }

  useEffect(() => {
    let active = true;
    Promise.all(["materials", "suppliers"].map(async (entity) => { const response = await fetch(`/api/khora?entity=${entity}`); if (!response.ok) throw new Error(); return response.json() as Promise<{ rows?: Array<Record<string, unknown>> }>; })).then(([materialData, supplierData]) => {
      if (!active) return;
      const apiMaterials = (materialData.rows ?? []).filter((row) => Boolean(row.active)).map((row) => ({ id: Number(row.id), code: String(row.code), name: String(row.material), category: String(row.category ?? "Sin categoría"), categoryId: Number(row.category_id), prefix: String(row.prefix ?? "MAT"), unit: String(row.unit), stock: Number(row.current_stock), minimum: Number(row.minimum_stock), cost: Number(row.current_cost_cents), supplier: String(row.preferred_supplier ?? "Sin proveedor"), supplierId: row.preferred_supplier_id ? Number(row.preferred_supplier_id) : undefined, notes: String(row.notes ?? "") }));
      const apiSuppliers = (supplierData.rows ?? []).filter((row) => Boolean(row.active)).map((row) => ({ id: Number(row.id), name: String(row.name) }));
      setCatalog(apiMaterials);
      setSupplierCatalog(apiSuppliers);
      const initial = purchase ? apiMaterials.find((item) => item.code === purchase.code) : apiMaterials[0];
      setMaterialId(initial?.id ?? apiMaterials[0]?.id ?? 0);
      setUnit(purchase?.input_unit ?? initial?.unit ?? "unidad");
      if (purchase) { setSupplierId(undefined); setQuantity(Number(purchase.input_quantity)); setTotalPesos(Number(purchase.total_cost_cents) / 100); setDate(String(purchase.purchased_at).slice(0, 10)); setPaymentStatus(purchase.payment_status); setInvoiceNumber(purchase.invoice_number ?? ""); setNotes(purchase.notes ?? ""); }
    }).catch(() => undefined);
    return () => { active = false; };
  }, [purchase]);

  function changeMaterial(id: number) { const next = catalog.find((item) => item.id === id); setMaterialId(id); if (next) { setUnit(next.unit); setSupplierId(next.supplierId); } }
  async function save() {
    if (!material || !projection) { setError("Revisá la materia prima, la cantidad y la unidad."); return; }
    if (totalPesos <= 0) { setError("Ingresá el costo total de la compra."); return; }
    setSaving(true); setError("");
    try {
      const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(editing ? { action: "update_purchase", id: purchase?.id, supplierId, date, paymentStatus, invoiceNumber, notes } : { action: "purchase", materialId: material.id, supplierId, quantity, unit, totalCostCents: Math.round(totalPesos * 100), date, paymentStatus, invoiceNumber, notes }) });
      const result = await response.json() as { error?: string; baseQuantity?: number; baseUnit?: string; weightedAverageCostCents?: number };
      if (!response.ok) throw new Error(result.error ?? "No se pudo confirmar la compra");
      onSaved(editing ? `Compra C-${purchase?.id} actualizada correctamente.` : `Compra confirmada: ingresaron ${formatQuantity(result.baseQuantity ?? projection.baseQuantity)} ${result.baseUnit ?? material.unit}. Nuevo costo promedio: ${money(result.weightedAverageCostCents ?? projection.unitCost)}.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo confirmar la compra"); } finally { setSaving(false); }
  }

  return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar compra" /><aside className="inventory-form-drawer purchase-form-drawer" role="dialog" aria-modal="true" aria-labelledby="purchase-form-title"><header><div><p>COMPRAS · COSTO PROMEDIO</p><h2 id="purchase-form-title">Nueva compra</h2><span>La confirmación actualiza stock, movimiento y costo en una sola operación.</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div className="inventory-form-body"><label><span>Materia prima existente *</span><select value={materialId} onChange={(event) => changeMaterial(Number(event.target.value))}>{catalog.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label><label><span>Proveedor</span><select value={supplierId ?? ""} onChange={(event) => setSupplierId(event.target.value ? Number(event.target.value) : undefined)}><option value="">Sin proveedor</option>{supplierCatalog.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="form-grid"><label><span>Cantidad comprada *</span><input type="number" min="0.001" step="0.001" value={quantity} onChange={(event) => setQuantity(Math.max(0, Number(event.target.value) || 0))} /></label><label><span>Unidad de compra *</span><select value={unit} onChange={(event) => setUnit(event.target.value)}>{unitOptions.map((item) => <option key={item.id} value={item.id} disabled={!item.compatible}>{item.label}{item.compatible ? "" : " · incompatible"}</option>)}</select><small>Mostramos todas las unidades; las incompatibles quedan deshabilitadas para evitar conversiones incorrectas.</small></label></div><div className="form-grid"><label><span>Costo total ($) *</span><input type="number" min="0" step="0.01" value={totalPesos} onChange={(event) => setTotalPesos(Math.max(0, Number(event.target.value) || 0))} /></label><label><span>Fecha *</span><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label></div><div className="form-grid"><label><span>Estado de pago</span><select value={paymentStatus} onChange={(event) => setPaymentStatus(event.target.value)}><option value="PAID">Pagado</option><option value="UNPAID">Pendiente</option></select></label><label><span>Comprobante</span><input value={invoiceNumber} onChange={(event) => setInvoiceNumber(event.target.value)} placeholder="Ej. FC A 0001-1234" /></label></div><label><span>Notas</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} /></label>{material && projection && <section className="purchase-projection"><header><strong>Conversión y costo</strong><Badge tone="info">Vista previa</Badge></header><div className="purchase-stock-equation"><span>Stock antes <strong>{formatQuantity(material.stock)} {material.unit}</strong></span><i>+</i><span>Esta compra <strong>{formatQuantity(projection.baseQuantity)} {material.unit}</strong></span><i>=</i><span>Stock resultante <strong>{formatQuantity(projection.newStock)} {material.unit}</strong></span></div><dl><div><dt>Ingresará al stock</dt><dd>{formatQuantity(projection.baseQuantity)} {material.unit}</dd></div><div><dt>Costo de esta compra</dt><dd>{projection.baseQuantity ? money(Math.round(totalPesos * 100 / projection.baseQuantity)) : money(0)} / {material.unit}</dd></div><div><dt>Nuevo promedio</dt><dd>{money(projection.unitCost)} / {material.unit}</dd></div></dl><p>El resultado suma el stock que ya figura en Supabase más la cantidad convertida de esta compra.</p></section>}{error && <p className="form-error" role="alert">{error}</p>}</div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="primary-button" disabled={saving} aria-busy={saving} onClick={save}>{saving ? "Confirmando…" : "Confirmar compra"}</button></footer></aside></div>;
}

function PurchaseDetailDialog({ purchase, onClose, onEdit }: { purchase: PurchaseRow; onClose: () => void; onEdit?: () => void }) {
  return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onClose} aria-label="Cerrar detalle" /><aside className="material-detail purchase-detail-drawer" role="dialog" aria-modal="true" aria-labelledby="purchase-detail-title"><header><div><p>COMPRAS · DETALLE</p><h2 id="purchase-detail-title">Compra C-{purchase.id}</h2><span>{purchase.material} · {formatDate(purchase.purchased_at)}</span></div><button onClick={onClose} aria-label="Cerrar">×</button></header><div className="material-detail-body"><section className="material-master-data"><dl><div><dt>Materia prima</dt><dd>{purchase.material} ({purchase.code})</dd></div><div><dt>Proveedor</dt><dd>{purchase.supplier || "Sin proveedor"}</dd></div><div><dt>Cantidad</dt><dd>{formatQuantity(Number(purchase.input_quantity))} {purchase.input_unit}</dd></div><div><dt>Total</dt><dd>{money(Number(purchase.total_cost_cents) / 100)}</dd></div><div><dt>Costo unitario</dt><dd>{money(Number(purchase.unit_cost_cents) / 100)} / {purchase.base_unit}</dd></div><div><dt>Pago</dt><dd>{purchase.payment_status === "PAID" ? "Pagado" : "Pendiente"}</dd></div><div><dt>Estado</dt><dd>{purchase.status}</dd></div></dl>{purchase.invoice_number && <p>Comprobante: {purchase.invoice_number}</p>}{purchase.notes && <p>{purchase.notes}</p>}</section></div><footer><button className="secondary-button" onClick={onClose}>Cerrar</button>{onEdit && <button className="primary-button" onClick={onEdit}>Editar compra</button>}</footer></aside></div>;
}


function PurchaseCancelDialog({ purchase, onCancel, onCancelled }: { purchase: PurchaseRow; onCancel: () => void; onCancelled: (message: string) => void }) {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  async function cancel() {
    setSaving(true);
    setError("");
    try {
      const response = await fetch("/api/khora", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ action: "cancel_purchase", id: purchase.id }),
      });
      const result = await response.json() as { error?: string };
      if (!response.ok) throw new Error(result.error ?? "No se pudo anular la compra");
      onCancelled(`Compra C-${purchase.id} anulada y stock revertido.`);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "No se pudo anular la compra");
    } finally {
      setSaving(false);
    }
  }

  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar anulación" /><section className="confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="purchase-cancel-title"><header><div><p>COMPRAS · ANULAR</p><h2 id="purchase-cancel-title">Anular compra C-{purchase.id}</h2><span>El stock y los registros financieros se revertirán de forma segura.</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div><p>¿Seguro que querés anular la compra de <strong>{purchase.material}</strong>?</p><div className="confirm-note"><i>i</i><p>La compra permanecerá en el historial como anulada. Después podrás eliminarla definitivamente si no tiene dependencias.</p></div>{error && <p className="form-error" role="alert">{error}</p>}</div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="danger-button" disabled={saving} onClick={cancel}>{saving ? "Anulando…" : "Anular compra"}</button></footer></section></div>;
}

function PurchaseDeleteDialog({ purchase, onCancel, onDeleted }: { purchase: PurchaseRow; onCancel: () => void; onDeleted: (message: string) => void }) {
  const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  async function remove() { setSaving(true); setError(""); try { const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "delete_purchase", id: purchase.id }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "No se pudo eliminar la compra"); onDeleted(`Compra C-${purchase.id} eliminada definitivamente.`); } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo eliminar la compra"); } finally { setSaving(false); } }
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar eliminación" /><section className="confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="purchase-delete-title"><header><div><p>COMPRAS · ELIMINAR</p><h2 id="purchase-delete-title">Eliminar compra C-{purchase.id}</h2><span>Esta acción no se puede deshacer.</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div><p>¿Seguro que querés eliminar la compra de <strong>{purchase.material}</strong>?</p>{error && <p className="form-error" role="alert">{error}</p>}</div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="danger-button" disabled={saving} onClick={remove}>{saving ? "Eliminando…" : "Eliminar compra"}</button></footer></section></div>;
}

function ActionConfirmDialog({ title, subtitle, defaultQuantity, unit = "u.", confirmLabel, note, onCancel, onConfirm }: { title: string; subtitle: string; defaultQuantity: number; unit?: string; confirmLabel: string; note: string; onCancel: () => void; onConfirm: (quantity: number) => void }) {
  const [quantity, setQuantity] = useState(defaultQuantity);
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label="Cancelar" /><section className="confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><header><div><p>CONFIRMACIÓN</p><h2 id="confirm-title">{title}</h2><span>{subtitle}</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div><label><span>Cantidad</span><div><input type="number" min="0.01" step="0.01" value={quantity} onChange={(event) => setQuantity(Math.max(0.01, Number(event.target.value) || 0.01))} /><b>{unit}</b></div></label><div className="confirm-note"><i>i</i><p>{note}</p></div></div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="primary-button" onClick={() => onConfirm(quantity)}>{confirmLabel}</button></footer></section></div>;
}

function LegacySuppliers({ search, onCreate }: { search: string; onCreate?: (kind: string, section?: SectionId) => void }) {
  type SupplierRow = { id: number; name: string; phone?: string; email?: string; address?: string; active: boolean } & Record<string, unknown>;
  type PurchaseRow = { supplier?: string; purchased_at: string; total_cost_cents: number; payment_status: string; status?: string } & Record<string, unknown>;
  const supplierData = useKhoraRows<SupplierRow>("suppliers"), purchaseData = useKhoraRows<PurchaseRow>("purchases");
  const [query, setQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "active">("all");
  const [selected, setSelected] = useState<SupplierRow | null>(null);
  const purchaseStats = (supplier: SupplierRow) => { const own = purchaseData.rows.filter((purchase) => purchase.supplier === supplier.name); const total = own.reduce((sum, purchase) => sum + Number(purchase.total_cost_cents), 0); const pending = own.filter((purchase) => purchase.payment_status !== "PAID").reduce((sum, purchase) => sum + Number(purchase.total_cost_cents), 0); const last = own.map((purchase) => String(purchase.purchased_at).slice(0, 10)).sort().reverse()[0]; return { count: own.length, total, pending, last }; };
  const effectiveQuery = query || search;
  const rows = supplierData.rows.filter((supplier) => (statusFilter === "all" || supplier.active) && includesSearch(supplier, effectiveQuery));
  const purchaseTotal = purchaseData.rows.reduce((sum, purchase) => sum + Number(purchase.total_cost_cents), 0), pendingTotal = purchaseData.rows.filter((purchase) => purchase.payment_status !== "PAID").reduce((sum, purchase) => sum + Number(purchase.total_cost_cents), 0);
  return <div className="section-stack">{supplierData.error && <div className="inline-notice error"><span>!</span>{supplierData.error}</div>}<div className="summary-row three"><MiniStat label="Proveedores activos" value={String(supplierData.rows.filter((supplier) => supplier.active).length)} detail={`${supplierData.rows.length} registrados`} tone="info" /><MiniStat label="Comprado" value={money(purchaseTotal / 100)} detail={`${purchaseData.rows.length} compras reales`} tone="neutral" /><MiniStat label="Saldo pendiente" value={money(pendingTotal / 100)} detail="Compras no pagadas" tone="warning" /></div><div className="toolbar supplier-toolbar"><label><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar proveedor, contacto o localidad…" /></label><div><button className={statusFilter === "all" ? "active-filter" : ""} onClick={() => setStatusFilter("all")}>Todos los proveedores<span>⌄</span></button><button className={statusFilter === "active" ? "active-filter" : ""} onClick={() => setStatusFilter("active")}>Activos<span>⌄</span></button></div></div><Panel title="Proveedores" subtitle={supplierData.loading ? "Actualizando…" : `${rows.length} ${rows.length === 1 ? "proveedor visible" : "proveedores visibles"}`} action={<button className="primary-button" onClick={() => onCreate?.("proveedor", "proveedores")}>＋ Nuevo proveedor</button>}><DataTable headers={["Proveedor", "Contacto", "Última compra", "Compras", "Total comprado", "Saldo pendiente", "Estado", ""]}>{rows.map((supplier) => { const stats = purchaseStats(supplier); return <tr key={supplier.id}><td><CellPerson name={supplier.name} subtitle={supplier.address || "Sin localidad"} /></td><td><span>{supplier.phone || "Sin teléfono"}</span><small className="table-sub">{supplier.email || "Sin email"}</small></td><td>{stats.last || "Sin compras"}</td><td>{stats.count}</td><td><strong>{money(stats.total / 100)}</strong></td><td>{money(stats.pending / 100)}</td><td><Badge tone={supplier.active ? "success" : "neutral"}>{supplier.active ? "Activo" : "Inactivo"}</Badge></td><td><button className="table-open-button" onClick={() => setSelected(supplier)}>Ver ficha</button></td></tr>; })}</DataTable>{!supplierData.loading && !rows.length && <div className="recipe-empty"><strong>Todavía no hay proveedores</strong><br />Agregá tu primer proveedor para empezar a registrar compras e insumos.</div>}</Panel>{selected && <LegacySupplierDetail supplier={selected} stats={purchaseStats(selected)} onClose={() => setSelected(null)} />}</div>;
}

function LegacySupplierDetail({ supplier, stats, onClose }: { supplier: { name: string; phone?: string; email?: string; address?: string; active: boolean }; stats: { count: number; total: number; pending: number; last?: string }; onClose: () => void }) {
  return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onClose} aria-label="Cerrar ficha" /><aside className="customer-detail" role="dialog" aria-modal="true" aria-labelledby="supplier-detail-title"><header><div><p>FICHA DEL PROVEEDOR</p><h2 id="supplier-detail-title">{supplier.name}</h2></div><button onClick={onClose} aria-label="Cerrar">×</button></header><div className="customer-detail-body"><div className="customer-profile"><Avatar text={initials(supplier.name)} /><div><strong>{supplier.name}</strong><span>{supplier.phone || "Sin teléfono"} · {supplier.email || "Sin email"}</span><small>{supplier.address || "Sin localidad"}</small></div><Badge tone={supplier.active ? "success" : "neutral"}>{supplier.active ? "Activo" : "Inactivo"}</Badge></div><div className="customer-kpis"><div><span>Compras</span><strong>{stats.count}</strong></div><div><span>Total comprado</span><strong>{money(stats.total / 100)}</strong></div><div><span>Saldo pendiente</span><strong>{money(stats.pending / 100)}</strong></div><div><span>Última compra</span><strong>{stats.last || "—"}</strong></div></div><section className="customer-activity"><header><h3>Relación comercial</h3><Badge tone="success">Datos reales</Badge></header><dl><div><dt>Estado</dt><dd>{supplier.active ? "Activo" : "Inactivo"}</dd></div><div><dt>Contacto</dt><dd>{supplier.phone || "Sin teléfono"}</dd></div><div><dt>Email</dt><dd>{supplier.email || "Sin email"}</dd></div></dl></section></div><footer><button className="secondary-button" onClick={onClose}>Cerrar</button>{supplier.phone && <a className="primary-button" href={buildWhatsAppLink(supplier.phone, `Hola ${supplier.name}, te escribimos desde KHORA.`)} target="_blank" rel="noreferrer">Contactar ↗</a>}</footer></aside></div>;
}

function Suppliers({ search, onCreate }: { search: string; onCreate?: (kind: string, section?: SectionId) => void }) {
  const supplierData = useKhoraRows<SupplierRow>("suppliers");
  const purchaseData = useKhoraRows<Record<string, unknown>>("purchases");
  const [query, setQuery] = useState(search);
  const [statusFilter, setStatusFilter] = useState<"all" | "active">("active");
  const [selected, setSelected] = useState<SupplierRow | null>(null);
  const [editing, setEditing] = useState<SupplierRow | null>(null);
  const [deleting, setDeleting] = useState<SupplierRow | null>(null);
  const [notice, setNotice] = useState("");
  useEffect(() => { setQuery(search); }, [search]);
  function notify(message: string) { setNotice(message); window.setTimeout(() => setNotice(""), 4500); }
  const purchaseStats = (supplier: SupplierRow) => { const own = purchaseData.rows.filter((purchase) => Number(purchase.supplier_id) === supplier.id || String(purchase.supplier ?? "") === supplier.name); const total = own.reduce((sum, purchase) => sum + Number(purchase.total_cost_cents ?? 0), 0); const pending = own.filter((purchase) => String(purchase.payment_status ?? "") !== "PAID").reduce((sum, purchase) => sum + Number(purchase.total_cost_cents ?? 0), 0); const last = own.map((purchase) => String(purchase.purchased_at ?? "").slice(0, 10)).filter(Boolean).sort().reverse()[0]; return { count: own.length, total, pending, last }; };
  const effectiveQuery = query.trim();
  const rows = supplierData.rows.filter((supplier) => (statusFilter === "all" || Boolean(supplier.active)) && includesSearch(supplier, effectiveQuery));
  const purchaseTotal = purchaseData.rows.reduce((sum, purchase) => sum + Number(purchase.total_cost_cents ?? 0), 0), pendingTotal = purchaseData.rows.filter((purchase) => String(purchase.payment_status ?? "") !== "PAID").reduce((sum, purchase) => sum + Number(purchase.total_cost_cents ?? 0), 0);
  return <div className="section-stack">{notice && <div className="inline-notice success"><span>✓</span>{notice}</div>}{supplierData.error && <div className="inline-notice error"><span>!</span>{supplierData.error}</div>}<div className="summary-row three"><MiniStat label="Proveedores activos" value={String(supplierData.rows.filter((supplier) => Boolean(supplier.active)).length)} detail={`${supplierData.rows.length} registrados`} tone="info" /><MiniStat label="Comprado" value={money(purchaseTotal / 100)} detail={`${purchaseData.rows.length} compras reales`} tone="neutral" /><MiniStat label="Saldo pendiente" value={money(pendingTotal / 100)} detail="Compras no pagadas" tone="warning" /></div><div className="toolbar supplier-toolbar"><label aria-label="Buscar proveedores"><KhoraIcon name="search" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar proveedor, contacto o localidad…" /></label><div><button type="button" className={statusFilter === "active" ? "active-filter" : ""} aria-pressed={statusFilter === "active"} onClick={() => setStatusFilter((current) => current === "active" ? "all" : "active")}>{statusFilter === "active" ? "Activos" : "Todos"}<span>⌄</span></button></div></div><Panel title="Proveedores" subtitle={supplierData.loading ? "Actualizando…" : `${rows.length} ${rows.length === 1 ? "proveedor visible" : "proveedores visibles"}`}><DataTable headers={["Proveedor", "Contacto", "Última compra", "Compras", "Total comprado", "Saldo pendiente", "Estado", "Acciones"]}>{rows.map((supplier) => { const stats = purchaseStats(supplier); return <tr key={supplier.id}><td><CellPerson name={supplier.name} subtitle={supplier.address || "Sin localidad"} /></td><td><span>{supplier.phone || "Sin teléfono"}</span><small className="table-sub">{supplier.email || "Sin email"}</small></td><td>{stats.last ? formatDate(stats.last) : "Sin compras"}</td><td>{stats.count}</td><td><strong>{money(stats.total / 100)}</strong></td><td>{money(stats.pending / 100)}</td><td><Badge tone={Boolean(supplier.active) ? "success" : "neutral"}>{Boolean(supplier.active) ? "Activo" : "Inactivo"}</Badge></td><td><div className="table-actions"><button className="table-open-button" onClick={() => setSelected(supplier)}>Ver ficha</button><button className="row-icon-button" onClick={() => setEditing(supplier)} title="Editar proveedor" aria-label={`Editar ${supplier.name}`}>✎</button><button className="row-icon-button danger" onClick={() => setDeleting(supplier)} title="Eliminar proveedor" aria-label={`Eliminar ${supplier.name}`}>⌫</button></div></td></tr>; })}</DataTable>{!supplierData.loading && !rows.length && <div className="recipe-empty"><strong>Todavía no hay proveedores</strong><br />Agregá tu primer proveedor para empezar a registrar compras e insumos.</div>}</Panel>{selected && <SupplierDetail supplier={selected} stats={purchaseStats(selected)} onClose={() => setSelected(null)} onEdit={() => { setSelected(null); setEditing(selected); }} onDelete={() => { setSelected(null); setDeleting(selected); }} />}{editing && <ContactEditDialog kind="supplier" contact={editing} onCancel={() => setEditing(null)} onSaved={(message) => { setEditing(null); notify(message); }} />}{deleting && <ContactDeleteDialog kind="supplier" contact={deleting} onCancel={() => setDeleting(null)} onDeleted={(message) => { setDeleting(null); notify(message); }} />}</div>;
}

function SupplierDetail({ supplier, stats, onClose, onEdit, onDelete }: { supplier: SupplierRow; stats: { count: number; total: number; pending: number; last?: string }; onClose: () => void; onEdit: () => void; onDelete: () => void }) {
  const [message, setMessage] = useState("");
  const [viewingPurchase, setViewingPurchase] = useState<PurchaseRow | null>(null);

  const hasEmail = Boolean(supplier.email?.trim());
  return <div className="drawer-layer"><button className="drawer-backdrop" onClick={onClose} aria-label="Cerrar ficha" /><aside className="customer-detail" role="dialog" aria-modal="true" aria-labelledby="supplier-detail-title"><header><div><p>FICHA DEL PROVEEDOR</p><h2 id="supplier-detail-title">{supplier.name}</h2></div><button onClick={onClose} aria-label="Cerrar">×</button></header><div className="customer-detail-body"><div className="customer-profile"><Avatar text={initials(supplier.name)} /><div><strong>{supplier.name}</strong><span>{supplier.phone || "Sin teléfono"} · {supplier.email || "Sin email"}</span><small>{supplier.address || "Sin localidad"}</small></div><Badge tone={Boolean(supplier.active) ? "success" : "neutral"}>{Boolean(supplier.active) ? "Activo" : "Inactivo"}</Badge></div><div className="customer-kpis"><div><span>Compras</span><strong>{stats.count}</strong></div><div><span>Total comprado</span><strong>{money(stats.total / 100)}</strong></div><div><span>Saldo pendiente</span><strong>{money(stats.pending / 100)}</strong></div><div><span>Última compra</span><strong>{stats.last ? formatDate(stats.last) : "—"}</strong></div></div><section className="customer-activity"><header><h3>Relación comercial</h3><Badge tone="info">Datos reales</Badge></header><dl><div><dt>Estado</dt><dd>{Boolean(supplier.active) ? "Activo" : "Inactivo"}</dd></div><div><dt>Contacto</dt><dd>{supplier.phone || "Sin teléfono"}</dd></div><div><dt>Email</dt><dd>{supplier.email || "Sin email"}</dd></div></dl></section><ContactHistory kind="supplier" id={supplier.id} onPurchaseClick={(row) => setViewingPurchase({ id: Number(row.id), purchased_at: String(row.purchased_at ?? ""), category: String(row.category ?? ""), code: String(row.code ?? ""), material: String(row.material ?? "Materia prima"), input_quantity: Number(row.input_quantity ?? row.quantity ?? 0), input_unit: String(row.input_unit ?? row.unit ?? "unidad"), base_quantity: Number(row.base_quantity ?? row.quantity ?? 0), base_unit: String(row.base_unit ?? row.unit ?? "unidad"), supplier: supplier.name, unit_cost_cents: Number(row.unit_cost_cents ?? 0), total_cost_cents: Number(row.total_cost_cents ?? 0), paid_cents: Number(row.paid_cents ?? 0), pending_cents: Number(row.pending_cents ?? 0), payment_status: String(row.payment_status ?? "PAID"), invoice_number: String(row.invoice_number ?? ""), status: String(row.status ?? "").toLowerCase().includes("cancel") || String(row.status ?? "").toLowerCase().includes("anul") ? "Anulada" : "Confirmada", notes: String(row.notes ?? "") })} />{message && <small className="form-success">{message}</small>}{viewingPurchase && <PurchaseDetailDialog purchase={viewingPurchase} onClose={() => setViewingPurchase(null)} />}</div><footer><button className="secondary-button" onClick={onClose}>Cerrar</button>{hasEmail ? <a className="secondary-button" href={`mailto:${supplier.email}`}>Enviar email</a> : <button className="secondary-button" onClick={() => setMessage("Este proveedor no tiene un email cargado.")}>Enviar email</button>}{supplier.phone && <a className="primary-button" href={buildWhatsAppLink(supplier.phone, `Hola ${supplier.name}, te escribimos desde KHORA.`)} target="_blank" rel="noreferrer">Contactar ↗</a>}<button className="secondary-button" onClick={onEdit}>Editar</button><button className="danger-button" onClick={onDelete}>Eliminar</button></footer></aside></div>;
}


type ExpenseRow = { id: number; incurred_at: string; category?: string; code?: string; type: string; quantity: number; amount_cents: number; paid_cents?: number; pending_cents?: number; unit_cost_cents: number; supplier?: string; payment_status: string; invoice_number?: string; status: string; notes?: string } & Record<string, unknown>;
type ProfitRow = { id: number; month: string; sales_cents: number; product_cost_cents: number; expense_cents: number; profit_cents: number; calculated_at: string } & Record<string, unknown>;
type PaymentRow = { id: number; paid_at: string; reference: string; client?: string; method: string; amount_cents: number; direction: string; status: string; notes?: string } & Record<string, unknown>;
type FinanceSaleRow = { id: number; client?: string; status: string; payment_status: string; total_cents: number; total_cost_cents: number; paid_cents: number; pending_cents: number } & Record<string, unknown>;

type FinanceSummaryData = {
  month: string;
  salesGeneratedCents: number;
  collectedCents: number;
  receivableCents: number;
  purchasesCents: number;
  purchasesPaidCents: number;
  purchasesPendingCents: number;
  expensesCents: number;
  expensesPaidCents: number;
  expensesPendingCents: number;
  totalOutgoingsRegisteredCents: number;
  cashIncomeCents: number;
  cashOutgoingCents: number;
  cashResultCents: number;
  soldCostCents: number;
  grossProfitCents: number;
  netProfitCents: number;
  reinvestment: { mode: "PERCENT" | "FIXED" | null; percentValue: number | null; fixedAmountCents: number | null; reservedCents: number; reinvestedCents: number; availableCents: number };
  availableProfitCents: number;
  metrics?: {
    salesCount: number;
    averageTicketCents: number;
    largestExpense: { description: string; amountCents: number } | null;
    bestSalesDay: { date: string; amountCents: number } | null;
  };
  closure: { id: number; status: "CLOSED" | "REOPENED"; closedAt: string } | null;
};
type FinanceCashMovement = { id: string; occurred_at: string; direction: "IN" | "OUT"; category: string; description: string; counterpart: string; method?: string; amount: number };
type FinanceCashData = { start: string; end: string; incoming: number; outgoing: number; net: number; pendingIncome: number; pendingOutgoing: number; movements: FinanceCashMovement[] };
type FinanceClosureRow = { id: number; month: string; sales_generated_cents: number; collected_cents: number; receivable_cents: number; purchases_cents: number; purchases_paid_cents: number; purchases_pending_cents: number; expenses_cents: number; expenses_paid_cents: number; expenses_pending_cents: number; sold_cost_cents: number; gross_profit_cents: number; net_profit_cents: number; reinvestment_reserved_cents: number; reinvested_cents: number; available_profit_cents: number; cash_income_cents: number; cash_outgoing_cents: number; cash_result_cents: number; status: string; closed_at: string } & Record<string, unknown>;

const financeMoney = (cents: number) => money(Number(cents || 0) / 100);
const financeMonthLabel = (month: string) => new Intl.DateTimeFormat("es-AR", { month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${month}-01T12:00:00Z`));
const shiftFinanceMonth = (month: string, offset: number) => { const date = new Date(`${month}-01T12:00:00Z`); date.setUTCMonth(date.getUTCMonth() + offset); return date.toISOString().slice(0, 7); };
const currentFinanceMonth = () => { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "America/Argentina/Buenos_Aires", year: "numeric", month: "2-digit" }).formatToParts(new Date()); return `${parts.find((part) => part.type === "year")?.value}-${parts.find((part) => part.type === "month")?.value}`; };

function FinanceMetric({ label, value, help, tone = "neutral" }: { label: string; value: number; help: string; tone?: "neutral" | "success" | "warning" | "danger" }) {
  return <article className={`finance-summary-metric ${tone}`}><span>{label}</span><strong>{financeMoney(value)}</strong><small>{help}</small></article>;
}

function ReinvestmentEditor({ summary, onSaved }: { summary: FinanceSummaryData; onSaved: () => void }) {
  const [mode, setMode] = useState<"PERCENT" | "FIXED">(summary.reinvestment.mode ?? "PERCENT");
  const [percent, setPercent] = useState(summary.reinvestment.percentValue ?? 0);
  const [fixedPesos, setFixedPesos] = useState((summary.reinvestment.fixedAmountCents ?? 0) / 100);
  const [saving, setSaving] = useState(false), [error, setError] = useState("");
  async function save() { setSaving(true); setError(""); try { const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "save_reinvestment_plan", month: summary.month, mode, percentValue: mode === "PERCENT" ? percent : null, fixedAmountCents: mode === "FIXED" ? Math.round(fixedPesos * 100) : null }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "No se pudo guardar la reinversión"); onSaved(); } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo guardar la reinversión"); } finally { setSaving(false); } }
  const disabled = summary.netProfitCents <= 0 || summary.closure?.status === "CLOSED";
  return <div className="reinvestment-editor"><div className="reinvestment-choice"><button className={mode === "PERCENT" ? "active" : ""} disabled={disabled} onClick={() => setMode("PERCENT")}>Porcentaje</button><button className={mode === "FIXED" ? "active" : ""} disabled={disabled} onClick={() => setMode("FIXED")}>Monto fijo</button></div><label><span>{mode === "PERCENT" ? "Porcentaje a reservar" : "Monto a reservar"}</span><div><input type="number" min="0" max={mode === "PERCENT" ? 100 : undefined} step={mode === "PERCENT" ? 1 : 0.01} value={mode === "PERCENT" ? percent : fixedPesos} disabled={disabled} onChange={(event) => mode === "PERCENT" ? setPercent(Math.max(0, Math.min(100, Number(event.target.value) || 0))) : setFixedPesos(Math.max(0, Number(event.target.value) || 0))} /><b>{mode === "PERCENT" ? "%" : "$"}</b></div></label><button className="primary-button" disabled={saving || disabled} onClick={save}>{saving ? "Guardando…" : "Guardar reinversión"}</button>{summary.netProfitCents <= 0 && <p>No hay ganancia disponible para reinvertir en este período.</p>}{summary.closure?.status === "CLOSED" && <p>El período está cerrado. Reabrilo para modificar la reinversión.</p>}{error && <p className="form-error" role="alert">{error}</p>}</div>;
}

type ReinvestmentMovementRow = { id: number; occurred_at: string; concept: string; category: string; amount_cents: number; purchase_reference?: string; expense_reference?: string; raw_material_purchase_id?: number; expense_id?: number };

function ReinvestmentMovements({ summary, onSaved }: { summary: FinanceSummaryData; onSaved: () => void }) {
  const movementData = useKhoraObject<{ rows: ReinvestmentMovementRow[] }>(`/api/khora?entity=reinvestment_movements&month=${summary.month}`);
  const purchasesData = useKhoraRows<PurchaseRow>("purchases"), expensesData = useKhoraRows<ExpenseRow>("expenses");
  const [open, setOpen] = useState(false), [saving, setSaving] = useState(false), [error, setError] = useState("");
  const [date, setDate] = useState(`${summary.month}-01`), [concept, setConcept] = useState(""), [category, setCategory] = useState("Materia prima"), [amountPesos, setAmountPesos] = useState(0), [reference, setReference] = useState("") , [notes, setNotes] = useState("");
  const remaining = summary.reinvestment.availableCents;
  async function save() { setSaving(true); setError(""); try { const [referenceKind, referenceId] = reference.split(":"); const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "save_reinvestment_movement", month: summary.month, occurredAt: date, concept, category, amountCents: Math.round(amountPesos * 100), rawMaterialPurchaseId: referenceKind === "purchase" ? Number(referenceId) : null, expenseId: referenceKind === "expense" ? Number(referenceId) : null, notes }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "No se pudo registrar la reinversión"); setOpen(false); setConcept(""); setAmountPesos(0); setReference(""); setNotes(""); movementData.refresh(); onSaved(); } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo registrar la reinversión"); } finally { setSaving(false); } }
  const disabled = remaining <= 0 || summary.closure?.status === "CLOSED";
  return <section className="reinvestment-movements"><header><div><strong>Uso del fondo</strong><span>Registrar una reinversión no duplica una compra o gasto asociado.</span></div><button className="secondary-button" disabled={disabled} onClick={() => setOpen((value) => !value)}>{open ? "Cancelar" : "＋ Registrar uso"}</button></header>{open && <div className="reinvestment-movement-form"><div className="form-grid"><label><span>Fecha</span><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label><span>Categoría</span><select value={category} onChange={(event) => setCategory(event.target.value)}><option>Materia prima</option><option>Packaging</option><option>Máquina</option><option>Herramientas</option><option>Equipamiento</option><option>Publicidad</option><option>Expansión</option><option>Otros</option></select></label></div><div className="form-grid"><label><span>Concepto</span><input value={concept} onChange={(event) => setConcept(event.target.value)} placeholder="Ej. Compra de envases" /></label><label><span>Monto ($)</span><input type="number" min="0" max={remaining / 100} step="0.01" value={amountPesos} onChange={(event) => setAmountPesos(Math.max(0, Number(event.target.value) || 0))} /></label></div><label><span>Referencia opcional</span><select value={reference} onChange={(event) => setReference(event.target.value)}><option value="">Sin asociar</option><optgroup label="Compras">{purchasesData.rows.filter((row) => row.status === "Confirmada").map((row) => <option key={`purchase-${row.id}`} value={`purchase:${row.id}`}>{row.code} · {row.material} · {financeMoney(Number(row.total_cost_cents))}</option>)}</optgroup><optgroup label="Gastos">{expensesData.rows.filter((row) => row.status === "Confirmado").map((row) => <option key={`expense-${row.id}`} value={`expense:${row.id}`}>{row.code || `G-${row.id}`} · {row.type} · {financeMoney(Number(row.amount_cents))}</option>)}</optgroup></select><small>La asociación indica de dónde se financió; no crea otro egreso.</small></label><label><span>Notas opcionales</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} /></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="primary-button" disabled={saving || !concept.trim() || amountPesos <= 0} onClick={save}>{saving ? "Guardando…" : "Registrar reinversión"}</button></div>}<div className="reinvestment-movement-list">{(movementData.data?.rows ?? []).map((movement) => <article key={movement.id}><div><strong>{movement.concept}</strong><span>{movement.category} · {formatDate(movement.occurred_at)}</span><small>{movement.purchase_reference ? `Compra ${movement.purchase_reference}` : movement.expense_reference ? `Gasto ${movement.expense_reference}` : "Sin referencia asociada"}</small></div><b>{financeMoney(Number(movement.amount_cents))}</b></article>)}{!movementData.loading && !(movementData.data?.rows.length) && <p>Todavía no registraste usos del fondo.</p>}</div></section>;
}

function financePeriodVariation(current: number, previous?: number) { if (previous === undefined || previous === null) return null; if (previous === 0) return current === 0 ? 0 : null; return ((current - previous) / Math.abs(previous)) * 100; }
function FinanceVariation({ value, label }: { value: number | null; label: string }) { if (value === null) return <small className="finance-variation neutral">{label}: sin período comparable</small>; return <small className={`finance-variation ${value > 0 ? "positive" : value < 0 ? "negative" : "neutral"}`}>{label}: {value > 0 ? "↑" : value < 0 ? "↓" : "="} {Math.abs(value).toFixed(1)}%</small>; }

function FinanceSummaryView({ summary, previousSummary, onRefresh }: { summary: FinanceSummaryData; previousSummary?: FinanceSummaryData | null; onRefresh: () => void }) {
  const metrics = summary.metrics ?? { salesCount: 0, averageTicketCents: 0, largestExpense: null, bestSalesDay: null };
  const salesVariation = financePeriodVariation(summary.salesGeneratedCents, previousSummary?.salesGeneratedCents);
  const profitVariation = financePeriodVariation(summary.netProfitCents, previousSummary?.netProfitCents);
  const expenseVariation = financePeriodVariation(summary.expensesCents, previousSummary?.expensesCents);
  const netMargin = summary.salesGeneratedCents > 0 ? (summary.netProfitCents * 100) / summary.salesGeneratedCents : 0;
  const empty = summary.salesGeneratedCents === 0 && summary.purchasesCents === 0 && summary.expensesCents === 0;
  return <div className="finance-summary-layout">
    <section className="finance-summary-overview"><FinanceMetric label="Ventas" value={summary.salesGeneratedCents} help="Total vendido en el período." /><FinanceMetric label="Compras" value={summary.purchasesCents} help="Abastecimiento registrado." tone="warning" /><FinanceMetric label="Gastos" value={summary.expensesCents} help="Egresos generales registrados." tone="warning" /><FinanceMetric label="Ganancia neta" value={summary.netProfitCents} help="Ventas − costo vendido − gastos." tone={summary.netProfitCents < 0 ? "danger" : "success"} /></section>
    {empty && <div className="finance-empty-state"><span>✓</span><div><strong>Todavía no hay movimientos registrados para este período.</strong><p>Cuando registres ventas, compras o gastos, este resumen se actualizará automáticamente.</p></div></div>}
    <section className="finance-summary-block finance-executive-chart"><header><div><small>VISIÓN EJECUTIVA</small><h2>Ingresos vs. egresos</h2><p>Comparación del período seleccionado.</p></div><Badge tone="info">Datos reales</Badge></header><div className="finance-bar-chart" role="img" aria-label="Ventas, compras y gastos del período"><div className="finance-bar-item"><span>Ventas</span><i><em className="sales" style={{ width: `${Math.max(4, summary.salesGeneratedCents ? 100 : 0)}%` }} /></i><strong>{financeMoney(summary.salesGeneratedCents)}</strong></div><div className="finance-bar-item"><span>Compras</span><i><em className="purchases" style={{ width: `${summary.salesGeneratedCents ? Math.min(100, Math.max(4, summary.purchasesCents * 100 / summary.salesGeneratedCents)) : summary.purchasesCents ? 100 : 0}%` }} /></i><strong>{financeMoney(summary.purchasesCents)}</strong></div><div className="finance-bar-item"><span>Gastos</span><i><em className="expenses" style={{ width: `${summary.salesGeneratedCents ? Math.min(100, Math.max(4, summary.expensesCents * 100 / summary.salesGeneratedCents)) : summary.expensesCents ? 100 : 0}%` }} /></i><strong>{financeMoney(summary.expensesCents)}</strong></div></div></section>
    <section className="finance-summary-insight-grid"><article className="finance-insight-card"><header><small>RENTABILIDAD</small><Badge tone={netMargin >= 0 ? "success" : "danger"}>Margen neto</Badge></header><strong>{netMargin.toFixed(1)}%</strong><FinanceVariation value={profitVariation} label="Ganancia vs. mes anterior" /><div className="finance-insight-subgrid"><span>Ventas <b>{financeMoney(summary.salesGeneratedCents)}</b></span><span>Ganancia <b>{financeMoney(summary.netProfitCents)}</b></span></div></article><article className="finance-insight-card"><header><small>RESUMEN DEL MES</small><Badge tone="info">Indicadores</Badge></header><div className="finance-detail-list"><span>Ventas registradas <b>{metrics.salesCount}</b></span><span>Ticket promedio <b>{financeMoney(metrics.averageTicketCents)}</b></span><span>Mayor gasto <b>{metrics.largestExpense ? `${metrics.largestExpense.description} · ${financeMoney(metrics.largestExpense.amountCents)}` : "—"}</b></span><span>Día con más ventas <b>{metrics.bestSalesDay ? `${formatDate(metrics.bestSalesDay.date)} · ${financeMoney(metrics.bestSalesDay.amountCents)}` : "—"}</b></span></div></article></section>
    <section className="finance-summary-comparison"><header><div><small>COMPARACIÓN MENSUAL</small><h2>Cómo viene el negocio</h2></div><Badge tone="info">{previousSummary ? "Vs. mes anterior" : "Sin histórico"}</Badge></header><div className="finance-comparison-grid"><article><span>Ventas</span><strong>{financeMoney(summary.salesGeneratedCents)}</strong><FinanceVariation value={salesVariation} label="vs. anterior" /></article><article><span>Ganancia neta</span><strong>{financeMoney(summary.netProfitCents)}</strong><FinanceVariation value={profitVariation} label="vs. anterior" /></article><article><span>Gastos</span><strong>{financeMoney(summary.expensesCents)}</strong><FinanceVariation value={expenseVariation === null ? null : -expenseVariation} label="vs. anterior" /></article></div></section>
    <section className="finance-summary-block"><header><div><small>BLOQUE 1</small><h2>Actividad comercial</h2></div><Badge tone="info">Devengado</Badge></header><div className="finance-summary-grid three"><FinanceMetric label="Ventas generadas" value={summary.salesGeneratedCents} help="Total vendido durante el mes, esté cobrado o pendiente." /><FinanceMetric label="Cobrado" value={summary.collectedCents} help="Cobrado sobre las ventas generadas en este período." tone="success" /><FinanceMetric label="Por cobrar" value={summary.receivableCents} help="Saldo pendiente de las ventas del mes." tone="warning" /></div></section>
    <section className="finance-summary-block"><header><div><small>BLOQUE 2</small><h2>Egresos registrados</h2></div><Badge tone="warning">Compras ≠ gastos</Badge></header><div className="finance-summary-grid three"><FinanceMetric label="Compras" value={summary.purchasesCents} help="Compras de materias primas e insumos registradas." /><FinanceMetric label="Compras pagadas" value={summary.purchasesPaidCents} help="Parte abonada de las compras del mes." tone="success" /><FinanceMetric label="Compras pendientes" value={summary.purchasesPendingCents} help="Saldo pendiente con proveedores." tone="warning" /><FinanceMetric label="Gastos" value={summary.expensesCents} help="Egresos generales; no incluye compras de stock." /><FinanceMetric label="Gastos pagados" value={summary.expensesPaidCents} help="Gastos generales efectivamente pagados." tone="success" /><FinanceMetric label="Gastos pendientes" value={summary.expensesPendingCents} help="Gastos registrados que todavía no se pagaron." tone="warning" /></div><div className="finance-inline-total"><span>Total de egresos registrados</span><strong>{financeMoney(summary.totalOutgoingsRegisteredCents)}</strong></div></section>
    <section className="finance-summary-block"><header><div><small>BLOQUE 3</small><h2>Resultado de caja</h2></div><Badge tone="info">Dinero real</Badge></header><div className="finance-summary-grid three"><FinanceMetric label="Ingresos reales" value={summary.cashIncomeCents} help="Dinero efectivamente recibido durante el mes." tone="success" /><FinanceMetric label="Salidas reales" value={summary.cashOutgoingCents} help="Compras y gastos efectivamente pagados." tone="warning" /><FinanceMetric label="Resultado de caja" value={summary.cashResultCents} help="Ingresos reales menos salidas reales. No es ganancia." tone={summary.cashResultCents < 0 ? "danger" : "success"} /></div></section>
    <section className="finance-summary-block"><header><div><small>BLOQUE 4</small><h2>Rentabilidad</h2></div><Badge tone="success">Costo histórico</Badge></header><div className="finance-equation-detailed"><div><span>Ventas</span><strong>{financeMoney(summary.salesGeneratedCents)}</strong></div><i>−</i><div><span>Costo vendido</span><strong>{financeMoney(summary.soldCostCents)}</strong><small>Costo congelado en cada venta.</small></div><i>=</i><div><span>Ganancia bruta</span><strong>{financeMoney(summary.grossProfitCents)}</strong></div><i>−</i><div><span>Gastos</span><strong>{financeMoney(summary.expensesCents)}</strong></div><i>=</i><div className={summary.netProfitCents < 0 ? "negative" : "result"}><span>{summary.netProfitCents < 0 ? "Pérdida neta" : "Ganancia neta"}</span><strong>{financeMoney(summary.netProfitCents)}</strong></div></div></section>
    <section className="finance-summary-block"><header><div><small>BLOQUE 5</small><h2>Reinversión</h2></div><Badge tone="warning">Reserva, no gasto</Badge></header><div className="reinvestment-layout"><ReinvestmentEditor key={`${summary.month}-${summary.reinvestment.mode}-${summary.reinvestment.reservedCents}`} summary={summary} onSaved={onRefresh} /><div className="finance-summary-grid"><FinanceMetric label="Fondo reservado" value={summary.reinvestment.reservedCents} help="Parte de la ganancia separada para volver a invertir." tone="warning" /><FinanceMetric label="Reinvertido" value={summary.reinvestment.reinvestedCents} help="Uso real registrado del fondo." /><FinanceMetric label="Disponible para reinvertir" value={summary.reinvestment.availableCents} help="Fondo reservado menos lo ya utilizado." tone="success" /></div></div><ReinvestmentMovements summary={summary} onSaved={onRefresh} /></section>
    <section className={`available-profit-card ${summary.availableProfitCents < 0 ? "negative" : ""}`}><div><small>BLOQUE 6 · RESULTADO FINAL</small><h2>{summary.availableProfitCents < 0 ? "Pérdida disponible" : "Ganancia disponible"}</h2><p>Ganancia neta luego de separar el fondo de reinversión. No representa el saldo bancario.</p></div><strong>{financeMoney(summary.availableProfitCents)}</strong></section>
  </div>;
}

function FinanceCashView({ summary }: { summary: FinanceSummaryData }) {
  const endDate = new Date(`${shiftFinanceMonth(summary.month, 1)}-01T12:00:00Z`); endDate.setUTCDate(0);
  const end = endDate.toISOString().slice(0, 10);
  const start = `${summary.month}-01`;
  const cashData = useKhoraObject<FinanceCashData>(`/api/khora?entity=cash_summary&start=${start}&end=${end}`);
  const [filter, setFilter] = useState<"ALL" | "IN" | "OUT">("ALL");
  const movements = (cashData.data?.movements ?? []).filter((movement) => filter === "ALL" || movement.direction === filter);
  const daily = Object.values((cashData.data?.movements ?? []).reduce<Record<string, { date: string; incoming: number; outgoing: number }>>((map, movement) => { const date = movement.occurred_at.slice(0, 10); const row = map[date] ?? { date, incoming: 0, outgoing: 0 }; if (movement.direction === "IN") row.incoming += Number(movement.amount); else row.outgoing += Number(movement.amount); map[date] = row; return map; }, {})).sort((a, b) => b.date.localeCompare(a.date));
  const maxDaily = Math.max(1, ...daily.flatMap((row) => [row.incoming, row.outgoing]));
  return <div className="finance-cash-layout"><section className="cash-hero"><div className="cash-net"><small>BALANCE DEL PERÍODO · {financeMonthLabel(summary.month).toUpperCase()}</small><strong className={summary.cashResultCents >= 0 ? "positive" : "negative"}>{financeMoney(summary.cashResultCents)}</strong><span>Dinero real cobrado menos pagos efectivamente realizados.</span></div><div className="cash-flow"><article><span className="cash-arrow in">↓</span><div><small>Entradas</small><strong>{financeMoney(summary.cashIncomeCents)}</strong></div></article><article><span className="cash-arrow out">↑</span><div><small>Salidas</small><strong>{financeMoney(summary.cashOutgoingCents)}</strong></div></article></div></section><div className="cash-pending"><article><span>$</span><div><small>PENDIENTE DE COBRAR</small><strong>{financeMoney(summary.receivableCents)}</strong><p>Ventas del período con saldo abierto</p></div></article><article><span>↓</span><div><small>PENDIENTE DE PAGAR</small><strong>{financeMoney(summary.purchasesPendingCents + summary.expensesPendingCents)}</strong><p>Compras y gastos todavía no abonados</p></div></article></div><Panel title="Entradas vs. salidas" subtitle="Flujo efectivo por día del mes seleccionado"><div className="cash-daily-chart">{daily.map((row) => <article key={row.date}><time>{formatDate(row.date)}</time><div><span><i>Entradas</i><em className="in" style={{ width: `${row.incoming ? Math.max(4, row.incoming * 100 / maxDaily) : 0}%` }} />{financeMoney(row.incoming)}</span><span><i>Salidas</i><em className="out" style={{ width: `${row.outgoing ? Math.max(4, row.outgoing * 100 / maxDaily) : 0}%` }} />{financeMoney(row.outgoing)}</span></div></article>)}{!cashData.loading && !daily.length && <div className="recipe-empty">No hay movimientos de caja en este período.</div>}</div></Panel><Panel title="Movimientos de caja" subtitle={cashData.loading ? "Actualizando…" : `${movements.length} movimientos efectivos`} action={<div className="cash-filter-group" role="group" aria-label="Filtrar movimientos"><button className={filter === "ALL" ? "active" : ""} onClick={() => setFilter("ALL")}>Todos</button><button className={filter === "IN" ? "active" : ""} onClick={() => setFilter("IN")}>Ingresos</button><button className={filter === "OUT" ? "active" : ""} onClick={() => setFilter("OUT")}>Egresos</button></div>}><DataTable headers={["Fecha", "Movimiento", "Origen", "Entrada", "Salida"]}>{movements.map((movement) => <tr key={movement.id}><td>{formatDate(movement.occurred_at)}</td><td><strong>{movement.description}</strong><small className="table-sub">{movement.counterpart}</small></td><td><Badge tone={movement.direction === "IN" ? "success" : "warning"}>{movement.category}</Badge></td><td className="success-text">{movement.direction === "IN" ? financeMoney(Number(movement.amount)) : "—"}</td><td className="danger-text">{movement.direction === "OUT" ? financeMoney(Number(movement.amount)) : "—"}</td></tr>)}</DataTable>{!cashData.loading && !movements.length && <div className="recipe-empty">No hay movimientos que coincidan con el filtro.</div>}</Panel><div className="cash-method-note"><i>i</i><p>Caja usa la fecha efectiva del cobro o pago. Una venta pendiente no aparece como entrada hasta registrar el cobro; reservar reinversión no crea una salida.</p></div></div>;
}

type PayableSelection = { kind: "sale" | "purchase" | "expense"; id: number; title: string; subtitle: string; pendingCents: number };

function FinancialPaymentDialog({ item, onCancel, onSaved }: { item: PayableSelection; onCancel: () => void; onSaved: () => void }) {
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10)), [amountPesos, setAmountPesos] = useState(item.pendingCents / 100), [method, setMethod] = useState("Transferencia"), [notes, setNotes] = useState(""), [saving, setSaving] = useState(false), [error, setError] = useState("");
  const isCollection = item.kind === "sale";
  async function save() { setSaving(true); setError(""); try { const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(isCollection ? { action: "register_payment", saleId: item.id, date, amountCents: Math.round(amountPesos * 100), method, notes } : { action: "register_financial_payment", kind: item.kind, id: item.id, paidAt: date, amountCents: Math.round(amountPesos * 100), method, notes }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? (isCollection ? "No se pudo registrar el cobro" : "No se pudo registrar el pago")); window.dispatchEvent(new Event("khora:data-changed")); onSaved(); } catch (cause) { setError(cause instanceof Error ? cause.message : isCollection ? "No se pudo registrar el cobro" : "No se pudo registrar el pago"); } finally { setSaving(false); } }
  return <div className="confirm-layer"><button className="drawer-backdrop" onClick={onCancel} aria-label={isCollection ? "Cancelar cobro" : "Cancelar pago"} /><section className="confirm-dialog financial-payment-dialog" role="dialog" aria-modal="true" aria-labelledby="financial-payment-title"><header><div><p>{isCollection ? "CUENTAS POR COBRAR" : "CUENTAS POR PAGAR"}</p><h2 id="financial-payment-title">Registrar {isCollection ? "cobro" : "pago"}</h2><span>{item.title} · {item.subtitle}</span></div><button onClick={onCancel} aria-label="Cerrar">×</button></header><div><div className="form-grid"><label><span>Fecha efectiva</span><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label><span>Medio</span><select value={method} onChange={(event) => setMethod(event.target.value)}><option>Transferencia</option><option>Efectivo</option><option>Tarjeta</option><option>Débito</option><option>Otro</option></select></label></div><label><span>Monto a {isCollection ? "cobrar" : "pagar"}</span><div><input type="number" min="0.01" max={item.pendingCents / 100} step="0.01" value={amountPesos} onChange={(event) => setAmountPesos(Math.max(0, Number(event.target.value) || 0))} /><b>$</b></div><small>Saldo pendiente: {financeMoney(item.pendingCents)}</small></label><label><span>Notas opcionales</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} /></label>{error && <p className="form-error" role="alert">{error}</p>}</div><footer><button className="secondary-button" onClick={onCancel}>Cancelar</button><button className="primary-button" disabled={saving || amountPesos <= 0 || amountPesos * 100 > item.pendingCents} onClick={save}>{saving ? "Registrando…" : `Confirmar ${isCollection ? "cobro" : "pago"}`}</button></footer></section></div>;
}

const financeVariation = (current: number, baseline: number) => baseline === 0 ? (current === 0 ? 0 : 100) : ((current - baseline) * 100) / Math.abs(baseline);

function FinanceClosureComparison({ rows, currentMonth, onSelectMonth }: { rows: FinanceClosureRow[]; currentMonth: string; onSelectMonth: (month: string) => void }) {
  const closed = rows.filter((row) => row.status === "CLOSED"), current = closed.find((row) => row.month === currentMonth) ?? closed[0];
  const [baselineMonth, setBaselineMonth] = useState("");
  useEffect(() => { if (!current || (baselineMonth && baselineMonth !== current.month && closed.some((row) => row.month === baselineMonth))) return; const next = closed.find((row) => row.month !== current?.month)?.month ?? ""; const timeout = window.setTimeout(() => setBaselineMonth(next), 0); return () => window.clearTimeout(timeout); }, [baselineMonth, closed, current]);
  const baseline = closed.find((row) => row.month === baselineMonth);
  if (!current || !baseline) return <div className="close-no-comparison"><span>i</span><p>Guardá al menos dos cierres mensuales para poder compararlos.</p></div>;
  const metrics = [
    { label: "Ventas generadas", key: "sales_generated_cents" as const, inverse: false },
    { label: "Cobrado", key: "collected_cents" as const, inverse: false },
    { label: "Compras", key: "purchases_cents" as const, inverse: true },
    { label: "Gastos", key: "expenses_cents" as const, inverse: true },
    { label: "Resultado de caja", key: "cash_result_cents" as const, inverse: false },
    { label: "Ganancia neta", key: "net_profit_cents" as const, inverse: false },
    { label: "Ganancia disponible", key: "available_profit_cents" as const, inverse: false },
  ];
  return <Panel title="Comparación mensual" subtitle="Compará cualquier par de cierres históricos sin recalcularlos" action={<div className="finance-comparison-selectors"><select aria-label="Mes principal" value={current.month} onChange={(event) => onSelectMonth(event.target.value)}>{closed.map((row) => <option key={row.id} value={row.month}>{financeMonthLabel(row.month)}</option>)}</select><span>vs.</span><select aria-label="Mes de comparación" value={baseline.month} onChange={(event) => setBaselineMonth(event.target.value)}>{closed.filter((row) => row.month !== current.month).map((row) => <option key={row.id} value={row.month}>{financeMonthLabel(row.month)}</option>)}</select></div>}><div className="close-comparison">{metrics.map((metric) => { const currentValue = Number(current[metric.key]), baselineValue = Number(baseline[metric.key]), change = financeVariation(currentValue, baselineValue), favorable = metric.inverse ? change <= 0 : change >= 0; return <article className={favorable ? "positive" : "negative"} key={metric.key}><span>{metric.label}</span><strong>{change >= 0 ? "↑" : "↓"} {Math.abs(change).toFixed(1)}%</strong><small>{financeMoney(currentValue)} vs. {financeMoney(baselineValue)}</small></article>; })}</div></Panel>;
}

function FinanceReports({ closures, summary }: { closures: FinanceClosureRow[]; summary?: FinanceSummaryData | null }) {
  type ExportType = "financial" | "sales" | "purchases" | "expenses" | "profitability" | "stock" | "complete";
  type PeriodPreset = "current-month" | "previous-month" | "current-year" | "previous-year" | "custom";
  const today = new Date(), formatIso = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  const [preset, setPreset] = useState<PeriodPreset>("current-month"), [customFrom, setCustomFrom] = useState(`${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-01`), [customTo, setCustomTo] = useState(formatIso(today)), [downloading, setDownloading] = useState<ExportType | null>(null), [error, setError] = useState("");
  const monthStart = (year: number, month: number) => `${year}-${String(month + 1).padStart(2, "0")}-01`, monthEnd = (year: number, month: number) => formatIso(new Date(year, month + 1, 0));
  const previous = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const period = preset === "current-month" ? { from: monthStart(today.getFullYear(), today.getMonth()), to: formatIso(today) } : preset === "previous-month" ? { from: monthStart(previous.getFullYear(), previous.getMonth()), to: monthEnd(previous.getFullYear(), previous.getMonth()) } : preset === "current-year" ? { from: `${today.getFullYear()}-01-01`, to: formatIso(today) } : preset === "previous-year" ? { from: `${today.getFullYear() - 1}-01-01`, to: `${today.getFullYear() - 1}-12-31` } : { from: customFrom, to: customTo };
  const cards: Array<{ type: ExportType; eyebrow: string; title: string; description: string; sheets: string }> = [
    { type: "financial", eyebrow: "GESTIÓN", title: "Resumen financiero", description: "Ventas, cobros, compras, gastos, costos y resultados consolidados.", sheets: "Resumen · Ventas · Compras · Gastos" },
    { type: "sales", eyebrow: "COMERCIAL", title: "Ventas y clientes", description: "Detalle vendido, clientes, precios históricos y productos más vendidos.", sheets: "Ventas · Clientes · Productos vendidos" },
    { type: "purchases", eyebrow: "ABASTECIMIENTO", title: "Compras y proveedores", description: "Compras, proveedores, materias primas y costos del período.", sheets: "Compras · Proveedores · Materias compradas" },
    { type: "expenses", eyebrow: "EGRESOS", title: "Gastos", description: "Detalle completo y resumen agrupado por categoría.", sheets: "Gastos · Resumen de gastos" },
    { type: "profitability", eyebrow: "RENTABILIDAD", title: "Ganancias y reinversión", description: "Cierres históricos, márgenes, ganancia disponible y movimientos del fondo.", sheets: "Rentabilidad · Reinversiones" },
    { type: "stock", eyebrow: "INVENTARIO", title: "Stock y costos", description: "Fotografía actual de productos y materias primas con alertas críticas.", sheets: "Productos · Materias primas" },
  ];
  async function download(type: ExportType) { setDownloading(type); setError(""); try { if (!period.from || !period.to || period.from > period.to) throw new Error("Revisá las fechas del período personalizado."); const response = await fetch(`/api/khora/reports?type=${type}&from=${period.from}&to=${period.to}`); if (!response.ok) { const result = await response.json() as { error?: string }; throw new Error(result.error ?? "No se pudo generar el reporte"); } const blob = await response.blob(), disposition = response.headers.get("content-disposition") ?? "", match = disposition.match(/filename="?([^";]+)"?/i), anchor = document.createElement("a"), objectUrl = URL.createObjectURL(blob); anchor.href = objectUrl; anchor.download = match?.[1] ?? `KHORA-${type}.xlsx`; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(objectUrl), 1200); } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo generar el reporte."); } finally { setDownloading(null); } }
  function exportCsv() { const rows = [["Métrica", "Importe"], ["Ventas generadas", String((summary?.salesGeneratedCents ?? 0) / 100)], ["Compras", String((summary?.purchasesCents ?? 0) / 100)], ["Gastos", String((summary?.expensesCents ?? 0) / 100)], ["Ganancia neta", String((summary?.netProfitCents ?? 0) / 100)], ["Ganancia disponible", String((summary?.availableProfitCents ?? 0) / 100)]]; const csv = `\\uFEFF${rows.map((row) => row.map((cell) => `"${cell.replaceAll('"', '""')}"`).join(";")).join("\\n")}`; const anchor = document.createElement("a"), objectUrl = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); anchor.href = objectUrl; anchor.download = `KHORA-resumen-${period.from}-${period.to}.csv`; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(objectUrl), 1200); }
  return <div className="section-stack"><section className="report-period-card"><div><small>CENTRO DE REPORTES</small><h2>Información lista para analizar</h2><p>Todos los archivos se generan con los datos reales guardados en Supabase.</p><div className="report-utility-actions"><button className="secondary-button report-print-button" type="button" onClick={() => window.print()}>Imprimir / PDF</button><button className="secondary-button" type="button" onClick={exportCsv}>Exportar CSV</button></div></div><div className="report-period-controls"><label><span>Período</span><select value={preset} onChange={(event) => setPreset(event.target.value as PeriodPreset)}><option value="current-month">Este mes</option><option value="previous-month">Mes anterior</option><option value="current-year">Este año</option><option value="previous-year">Año anterior</option><option value="custom">Personalizado</option></select></label>{preset === "custom" && <><label><span>Desde</span><input type="date" value={customFrom} onChange={(event) => setCustomFrom(event.target.value)} /></label><label><span>Hasta</span><input type="date" value={customTo} onChange={(event) => setCustomTo(event.target.value)} /></label></>}<div className="report-period-summary"><span>Período aplicado</span><strong>{period.from.split("-").reverse().join("/")} — {period.to.split("-").reverse().join("/")}</strong></div></div></section>{error && <div className="inline-notice error" role="alert"><span>!</span>{error}</div>}<div className="report-card-grid professional">{cards.map((card) => <article className="report-card" key={card.type}><div><small>{card.eyebrow}</small><h2>{card.title}</h2><p>{card.description}</p><span className="report-sheets">{card.sheets}</span></div><button className="secondary-button" disabled={downloading !== null} aria-busy={downloading === card.type} onClick={() => download(card.type)}>{downloading === card.type ? "Generando…" : "↓ Descargar Excel"}</button></article>)}</div><section className="complete-report-card"><div><small>REPORTE COMPLETO</small><h2>Todo KHORA en un solo libro</h2><p>Incluye las hojas financieras, comerciales, de compras, gastos, rentabilidad y stock.</p></div><button className="primary-button" disabled={downloading !== null} onClick={() => download("complete")}>{downloading === "complete" ? "Generando libro completo…" : "↓ Descargar reporte completo"}</button></section>{summary && <Panel title="Vista rápida del período financiero activo" subtitle={`${financeMonthLabel(summary.month)} · ${closures.filter((row) => row.status === "CLOSED").length} cierres históricos protegidos`}><div className="finance-summary-grid three"><FinanceMetric label="Ventas generadas" value={summary.salesGeneratedCents} help="Actividad comercial" /><FinanceMetric label="Ganancia neta" value={summary.netProfitCents} help="Resultado después de costos y gastos" tone={summary.netProfitCents >= 0 ? "success" : "danger"} /><FinanceMetric label="Ganancia disponible" value={summary.availableProfitCents} help="Después de reinversión" tone="success" /></div></Panel>}<div className="report-security-note"><span>✓</span><div><strong>Exportación privada y trazable</strong><p>Los archivos se generan en el servidor para la usuaria autenticada; no se publican ni se almacenan como archivos públicos.</p></div></div></div>;
}

function Finance() {
  const [tab, setTab] = useState("Resumen"), [month, setMonth] = useState(currentFinanceMonth);
  const summaryData = useKhoraObject<FinanceSummaryData>(`/api/khora?entity=finance_summary&month=${month}`);
  const previousMonth = shiftFinanceMonth(month, -1);
  const previousSummaryData = useKhoraObject<FinanceSummaryData>(`/api/khora?entity=finance_summary&month=${previousMonth}`);
  const expenseData = useKhoraRows<ExpenseRow>("expenses"), profitData = useKhoraRows<ProfitRow>("profits"), saleData = useKhoraRows<FinanceSaleRow>("sales"), purchaseData = useKhoraRows<PurchaseRow>("purchases"), closureData = useKhoraRows<FinanceClosureRow>("finance_closures");
  const [notice, setNotice] = useState(""), [savingClose, setSavingClose] = useState(false);
  async function changeClosure(action: "close_finance_month" | "reopen_finance_month") { setSavingClose(true); setNotice(""); try { const response = await fetch("/api/khora", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action, month }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "No se pudo actualizar el cierre"); setNotice(action === "close_finance_month" ? "Cierre mensual guardado. Los valores quedaron congelados." : "Período reabierto. Los cambios volverán a reflejarse en el resumen."); summaryData.refresh(); closureData.refresh(); } catch (cause) { setNotice(cause instanceof Error ? cause.message : "No se pudo actualizar el cierre"); } finally { setSavingClose(false); } }
  const summary = summaryData.data, error = summaryData.error || previousSummaryData.error || expenseData.error || profitData.error || saleData.error || purchaseData.error || closureData.error;
  return <div className="section-stack"><Tabs tabs={["Resumen", "Caja", "Cierre mensual", "Gastos", "Ganancias", "Cuentas", "Reportes"]} active={tab} onChange={setTab} />{error && <div className="inline-notice error"><span>!</span>{error}</div>}{notice && <div className="inline-notice"><span>✓</span>{notice}</div>}{(tab === "Resumen" || tab === "Caja" || tab === "Cierre mensual") && <div className="finance-month-selector"><button aria-label="Mes anterior" onClick={() => setMonth(shiftFinanceMonth(month, -1))}>‹</button><label><span>Período</span><input type="month" value={month} onChange={(event) => setMonth(event.target.value)} /></label><strong>{financeMonthLabel(month)}</strong><button aria-label="Mes siguiente" onClick={() => setMonth(shiftFinanceMonth(month, 1))}>›</button>{summary?.closure?.status === "CLOSED" && <Badge tone="success">Cerrado</Badge>}</div>}{summaryData.loading && (tab === "Resumen" || tab === "Caja" || tab === "Cierre mensual") && <div className="recipe-empty">Calculando el período…</div>}{tab === "Resumen" && summary && <FinanceSummaryView summary={summary} previousSummary={previousSummaryData.data} onRefresh={summaryData.refresh} />}{tab === "Caja" && summary && <FinanceCashView summary={summary} />}{tab === "Cierre mensual" && summary && <><section className="finance-close-card"><div><small>CIERRE MENSUAL AUTOMÁTICO</small><h2>{financeMonthLabel(month)}</h2><p>{summary.closure?.status === "CLOSED" ? "Este snapshot histórico quedó protegido y no se recalcula." : summary.closure?.status === "REOPENED" ? "El período fue reabierto y puede volver a cerrarse." : "KHORA guardará automáticamente este período al comenzar el mes siguiente. También podés cerrarlo ahora."}</p></div><button className={summary.closure?.status === "CLOSED" ? "secondary-button" : "primary-button"} disabled={savingClose} onClick={() => changeClosure(summary.closure?.status === "CLOSED" ? "reopen_finance_month" : "close_finance_month")}>{savingClose ? "Guardando…" : summary.closure?.status === "CLOSED" ? "Reabrir período" : "Cerrar ahora"}</button></section><FinanceSummaryView summary={summary} previousSummary={previousSummaryData.data} onRefresh={summaryData.refresh} /><FinanceClosureComparison rows={closureData.rows} currentMonth={month} onSelectMonth={setMonth} /><Panel title="Historial de resúmenes" subtitle="Meses cerrados y conservados como snapshot"><DataTable headers={["Mes", "Generado", "Compras", "Gastos", "Ganancia neta", "Reinversión", "Ganancia disponible", ""]}>{closureData.rows.filter((row) => row.status === "CLOSED").map((row) => <tr key={row.id}><td><strong>{financeMonthLabel(row.month)}</strong><small className="table-sub">Cerrado {formatDate(row.closed_at)}</small></td><td>{financeMoney(Number(row.sales_generated_cents))}</td><td>{financeMoney(Number(row.purchases_cents))}</td><td>{financeMoney(Number(row.expenses_cents))}</td><td><strong>{financeMoney(Number(row.net_profit_cents))}</strong></td><td>{financeMoney(Number(row.reinvestment_reserved_cents))}</td><td><strong>{financeMoney(Number(row.available_profit_cents))}</strong></td><td><button className="table-open-button" onClick={() => setMonth(row.month)}>Ver resumen</button></td></tr>)}</DataTable>{!closureData.loading && !closureData.rows.some((row) => row.status === "CLOSED") && <div className="recipe-empty">Todavía no hay cierres mensuales guardados.</div>}</Panel></>}{tab === "Gastos" && <Panel title="Gastos registrados" subtitle={`Total: ${financeMoney(expenseData.rows.reduce((sum, expense) => sum + Number(expense.amount_cents), 0))}`}><DataTable headers={["Fecha", "Categoría", "Descripción", "Importe", "Estado", "Comprobante"]}>{expenseData.rows.map((expense) => <tr key={expense.id}><td>{formatDate(expense.incurred_at)}</td><td><Badge tone="neutral">{expense.category || "Sin categoría"}</Badge></td><td><strong>{expense.type}</strong><small className="table-sub">{expense.code || `G-${expense.id}`}</small></td><td><strong>{financeMoney(Number(expense.amount_cents))}</strong></td><td><Badge tone={expense.status === "Confirmado" && expense.payment_status === "Pagado" ? "success" : "warning"}>{expense.status === "Anulado" ? "Anulado" : expense.payment_status}</Badge></td><td>{expense.invoice_number || "—"}</td></tr>)}</DataTable>{!expenseData.loading && !expenseData.rows.length && <div className="recipe-empty">Todavía no hay gastos registrados.</div>}</Panel>}{tab === "Ganancias" && <RealProfitHistory rows={profitData.rows} />}{tab === "Cuentas" && <RealAccounts sales={saleData.rows} purchases={purchaseData.rows} expenses={expenseData.rows} onSaved={() => { purchaseData.refresh(); expenseData.refresh(); summaryData.refresh(); }} />}{tab === "Reportes" && <FinanceReports closures={closureData.rows} summary={summary} />}</div>;
}

function FinanceLegacy() {
  const expenseData = useKhoraRows<ExpenseRow>("expenses");
  const profitData = useKhoraRows<ProfitRow>("profits");
  const saleData = useKhoraRows<FinanceSaleRow>("sales");
  const purchaseData = useKhoraRows<PurchaseRow>("purchases");
  const paymentData = useKhoraRows<PaymentRow>("payments");
  const [tab, setTab] = useState("Resumen");
  const latest = profitData.rows[0];
  const sales = Number(latest?.sales_cents ?? saleData.rows.reduce((sum, sale) => sum + Number(sale.total_cents), 0));
  const costs = Number(latest?.product_cost_cents ?? saleData.rows.reduce((sum, sale) => sum + Number(sale.total_cost_cents ?? 0), 0));
  const expensesTotal = Number(latest?.expense_cents ?? expenseData.rows.reduce((sum, expense) => sum + Number(expense.amount_cents), 0));
  const net = Number(latest?.profit_cents ?? sales - costs - expensesTotal);
  const grossMargin = sales ? ((sales - costs) * 100) / sales : 0, netMargin = sales ? (net * 100) / sales : 0;
  const paidSales = saleData.rows.reduce((sum, sale) => sum + Number(sale.paid_cents), 0), collectionRate = sales ? paidSales * 100 / sales : 0;
  const error = expenseData.error || profitData.error || saleData.error || purchaseData.error || paymentData.error;
  return <div className="section-stack"><Tabs tabs={["Resumen", "Caja", "Cierre mensual", "Gastos", "Ganancias", "Cuentas", "Reportes"]} active={tab} onChange={setTab} />{error && <div className="inline-notice error"><span>!</span>{error}</div>}{tab === "Resumen" && <><div className="finance-hero"><div><p>GANANCIA NETA · {latest?.month ?? "ACUMULADA"}</p><strong>{money(net / 100)}</strong><span><b>Datos reales</b> actualizados desde Supabase</span></div><div className="profit-equation"><div><span>Ventas</span><strong>{money(sales / 100)}</strong></div><i>−</i><div><span>Costos vendidos</span><strong>{money(costs / 100)}</strong></div><i>−</i><div><span>Gastos</span><strong>{money(expensesTotal / 100)}</strong></div><i>=</i><div className="result"><span>Ganancia</span><strong>{money(net / 100)}</strong></div></div></div><div className="dashboard-grid dashboard-main"><Panel title="Evolución del negocio" subtitle="Cierres mensuales guardados"><RealMonthlyChart rows={profitData.rows} /></Panel><Panel title="Salud financiera" subtitle={latest?.month ?? "Período actual"}><div className="health-list"><Health label="Margen bruto" value={`${grossMargin.toFixed(1)}%`} level={Math.min(100, Math.max(0, grossMargin))} tone="success" /><Health label="Margen neto" value={`${netMargin.toFixed(1)}%`} level={Math.min(100, Math.max(0, netMargin))} tone={netMargin >= 0 ? "success" : "danger"} /><Health label="Cobranza" value={`${collectionRate.toFixed(1)}%`} level={Math.min(100, collectionRate)} tone="info" /><Health label="Gastos / ventas" value={`${sales ? (expensesTotal * 100 / sales).toFixed(1) : "0.0"}%`} level={sales ? Math.min(100, expensesTotal * 100 / sales) : 0} tone="warning" /></div></Panel></div></>}{tab === "Caja" && <RealCashView payments={paymentData.rows} expenses={expenseData.rows} purchases={purchaseData.rows} />}{tab === "Cierre mensual" && <RealMonthlyCloseView rows={profitData.rows} />}{tab === "Gastos" && <Panel title="Gastos registrados" subtitle={`Total: ${money(expenseData.rows.reduce((sum, expense) => sum + Number(expense.amount_cents), 0) / 100)}`}><DataTable headers={["Fecha", "Categoría", "Descripción", "Importe", "Estado", "Comprobante"]}>{expenseData.rows.map((expense) => <tr key={expense.id}><td>{formatDate(expense.incurred_at)}</td><td><Badge tone="neutral">{expense.category || "Sin categoría"}</Badge></td><td><strong>{expense.type}</strong><small className="table-sub">{expense.code || `G-${expense.id}`}</small></td><td><strong>{money(Number(expense.amount_cents) / 100)}</strong></td><td><Badge tone={expense.status === "Confirmado" && expense.payment_status === "Pagado" ? "success" : "warning"}>{expense.status === "Anulado" ? "Anulado" : expense.payment_status}</Badge></td><td>{expense.invoice_number || "—"}</td></tr>)}</DataTable>{!expenseData.loading && !expenseData.rows.length && <div className="recipe-empty">Todavía no hay gastos registrados.</div>}</Panel>}{tab === "Ganancias" && <RealProfitHistory rows={profitData.rows} />}{tab === "Cuentas" && <RealAccounts sales={saleData.rows} purchases={purchaseData.rows} />}{tab === "Reportes" && <Reports />}</div>;
}

void FinanceLegacy;

function RealMonthlyChart({ rows }: { rows: ProfitRow[] }) { const ordered = rows.slice().reverse(), max = Math.max(1, ...ordered.map((row) => Number(row.sales_cents))); return <div className="chart"><div className="chart-y"><span>{money(max / 100)}</span><span>{money(max / 200)}</span><span>$ 0</span></div><div className="chart-area">{ordered.map((row) => <div className="chart-month" key={row.id}><div className="bar-group"><i className="sales-bar" style={{ height: `${Number(row.sales_cents) * 100 / max}%` }} /><i className="profit-bar" style={{ height: `${Math.max(0, Number(row.profit_cents)) * 100 / max}%` }} /><i className="cost-bar" style={{ height: `${Number(row.product_cost_cents) * 100 / max}%` }} /></div><span>{row.month}</span></div>)}</div><div className="chart-legend"><span><i className="sales" />Ventas</span><span><i className="profit" />Ganancia</span><span><i className="cost" />Costos</span></div></div>; }
function RealCashView({ payments, expenses: expenseRows, purchases: purchaseRows }: { payments: PaymentRow[]; expenses: ExpenseRow[]; purchases: PurchaseRow[] }) { const incoming = payments.filter((payment) => payment.status === "CONFIRMED" && payment.direction === "IN").reduce((sum, payment) => sum + Number(payment.amount_cents), 0), expenseOut = expenseRows.filter((expense) => expense.status === "Confirmado" && expense.payment_status === "Pagado").reduce((sum, expense) => sum + Number(expense.amount_cents), 0), purchaseOut = purchaseRows.filter((purchase) => purchase.status === "Confirmada" && purchase.payment_status === "PAID").reduce((sum, purchase) => sum + Number(purchase.total_cost_cents), 0), outgoing = expenseOut + purchaseOut; return <><section className="cash-hero"><div className="cash-net"><small>SALDO NETO REGISTRADO</small><strong className={incoming - outgoing >= 0 ? "positive" : "negative"}>{money((incoming - outgoing) / 100)}</strong><span>{payments.length + expenseRows.length + purchaseRows.length} movimientos considerados</span></div><div className="cash-flow"><article><span className="cash-arrow in">↓</span><div><small>Entró</small><strong>{money(incoming / 100)}</strong></div></article><article><span className="cash-arrow out">↑</span><div><small>Salió</small><strong>{money(outgoing / 100)}</strong></div></article></div></section><Panel title="Cobros confirmados" subtitle={`${payments.length} pagos registrados`}><DataTable headers={["Fecha", "Referencia", "Cliente", "Medio", "Importe", "Estado"]}>{payments.map((payment) => <tr key={payment.id}><td>{formatDate(payment.paid_at)}</td><td>{payment.reference}</td><td>{payment.client || "Consumidor final"}</td><td>{payment.method}</td><td><strong className={payment.direction === "IN" ? "success-text" : "danger-text"}>{money(Number(payment.amount_cents) / 100)}</strong></td><td><Badge tone={payment.status === "CONFIRMED" ? "success" : "neutral"}>{payment.status === "CONFIRMED" ? "Confirmado" : payment.status}</Badge></td></tr>)}</DataTable></Panel></>; }
function RealMonthlyCloseView({ rows }: { rows: ProfitRow[] }) { const [month, setMonth] = useState(rows[0]?.month ?? ""); const close = rows.find((row) => row.month === month) ?? rows[0]; if (!close) return <div className="recipe-empty">Todavía no hay cierres mensuales calculados.</div>; const margin = Number(close.sales_cents) ? Number(close.profit_cents) * 100 / Number(close.sales_cents) : 0; return <><div className="monthly-close-head"><div><small>CIERRE MENSUAL · HISTORIAL</small><h2>{close.month}</h2><p>Los valores se conservan en Supabase para consulta histórica.</p></div><label><span>Período</span><select value={close.month} onChange={(event) => setMonth(event.target.value)}>{rows.map((row) => <option key={row.id} value={row.month}>{row.month}</option>)}</select></label></div><section className="close-hero"><div><small>GANANCIA NETA</small><strong>{money(Number(close.profit_cents) / 100)}</strong><span className="comparison-value up">Histórico guardado</span></div><dl><div><dt>Ventas</dt><dd>{money(Number(close.sales_cents) / 100)}</dd></div><div><dt>Costos vendidos</dt><dd>− {money(Number(close.product_cost_cents) / 100)}</dd></div><div><dt>Gastos</dt><dd>− {money(Number(close.expense_cents) / 100)}</dd></div><div className="close-result"><dt>Margen neto</dt><dd>{margin.toFixed(1)}%</dd></div></dl></section></>; }
function RealProfitHistory({ rows }: { rows: ProfitRow[] }) { return <Panel title="Ganancia por mes" subtitle="Cierres calculados con costos históricos"><DataTable headers={["Mes", "Ventas", "Costos vendidos", "Ganancia bruta", "Gastos", "Ganancia neta", "Margen"]}>{rows.map((row) => { const salesValue = Number(row.sales_cents), gross = salesValue - Number(row.product_cost_cents), netValue = Number(row.profit_cents); return <tr key={row.id}><td><strong>{row.month}</strong></td><td>{money(salesValue / 100)}</td><td>{money(Number(row.product_cost_cents) / 100)}</td><td>{money(gross / 100)}</td><td>{money(Number(row.expense_cents) / 100)}</td><td><strong className={netValue >= 0 ? "success-text" : "danger-text"}>{money(netValue / 100)}</strong></td><td>{salesValue ? (netValue * 100 / salesValue).toFixed(1) : "0.0"}%</td></tr>; })}</DataTable></Panel>; }
function RealAccounts({ sales: saleRows, purchases: purchaseRows, expenses: expenseRows = [], onSaved = () => undefined }: { sales: FinanceSaleRow[]; purchases: PurchaseRow[]; expenses?: ExpenseRow[]; onSaved?: () => void }) {
  const [selected, setSelected] = useState<PayableSelection | null>(null);
  const receivable = saleRows.filter((sale) => Number(sale.pending_cents) > 0 && sale.status !== "CANCELLED"), purchasePayable = purchaseRows.filter((purchase) => Number(purchase.pending_cents ?? (purchase.payment_status === "PAID" ? 0 : purchase.total_cost_cents)) > 0 && purchase.status === "Confirmada"), expensePayable = expenseRows.filter((expense) => Number(expense.pending_cents ?? (expense.payment_status === "Pagado" ? 0 : expense.amount_cents)) > 0 && expense.status === "Confirmado");
  const complete = () => { setSelected(null); onSaved(); };
  return <><div className="account-grid"><Panel title="Cuentas por cobrar" subtitle={`${receivable.length} saldos pendientes`}><div className="account-list">{receivable.map((sale) => <article key={sale.id}><CellPerson name={sale.client || "Consumidor final"} /><div><strong>{financeMoney(Number(sale.pending_cents))}</strong><small>V-{sale.id} · {sale.payment_status === "PARTIAL" ? "Parcial" : "Pendiente"}</small></div><button onClick={() => setSelected({ kind: "sale", id: sale.id, title: `Venta V-${sale.id}`, subtitle: sale.client || "Consumidor final", pendingCents: Number(sale.pending_cents) })}>Registrar cobro</button></article>)}{!receivable.length && <p className="account-empty">No hay cobros pendientes.</p>}</div></Panel><Panel title="Cuentas por pagar" subtitle={`${purchasePayable.length + expensePayable.length} saldos pendientes`}><div className="account-list">{purchasePayable.map((purchase) => { const pending = Number(purchase.pending_cents ?? purchase.total_cost_cents); return <article key={`purchase-${purchase.id}`}><CellPerson name={purchase.supplier || "Sin proveedor"} /><div><strong>{financeMoney(pending)}</strong><small>Compra C-{purchase.id} · {purchase.material}</small></div><button onClick={() => setSelected({ kind: "purchase", id: purchase.id, title: purchase.material, subtitle: purchase.supplier || "Sin proveedor", pendingCents: pending })}>Registrar pago</button></article>; })}{expensePayable.map((expense) => { const pending = Number(expense.pending_cents ?? expense.amount_cents); return <article key={`expense-${expense.id}`}><CellPerson name={expense.supplier || "Gasto general"} /><div><strong>{financeMoney(pending)}</strong><small>{expense.code || `G-${expense.id}`} · {expense.type}</small></div><button onClick={() => setSelected({ kind: "expense", id: expense.id, title: expense.type, subtitle: expense.supplier || "Gasto general", pendingCents: pending })}>Registrar pago</button></article>; })}{!purchasePayable.length && !expensePayable.length && <p className="account-empty">No hay pagos pendientes.</p>}</div></Panel></div>{selected && <FinancialPaymentDialog item={selected} onCancel={() => setSelected(null)} onSaved={complete} />}</>;
}

