function CashView() {
  const [period, setPeriod] = useState<CashPeriod>("today");
  const cash = getCashPanel(period);
  return <><div className="finance-period"><div><small>PANEL DE CAJA</small><h2>{cash.label}</h2><p>Movimientos confirmados según su fecha efectiva.</p></div><div role="group" aria-label="Período de caja">{([['today','Hoy'],['week','Semana'],['month','Mes']] as Array<[CashPeriod,string]>).map(([value,label]) => <button key={value} className={period === value ? "active" : ""} aria-pressed={period === value} onClick={() => setPeriod(value)}>{label}</button>)}</div></div><section className="cash-hero"><div className="cash-net"><small>SALDO NETO</small><strong className={cash.net >= 0 ? "positive" : "negative"}>{money(cash.net)}</strong><span>{cash.movements.length} movimientos confirmados</span></div><div className="cash-flow"><article><span className="cash-arrow in">↓</span><div><small>Entró</small><strong>{money(cash.incoming)}</strong></div></article><article><span className="cash-arrow out">↑</span><div><small>Salió</small><strong>{money(cash.outgoing)}</strong></div></article></div></section><div className="cash-pending"><article><span>$</span><div><small>PENDIENTE DE COBRAR</small><strong>{money(cash.pendingIncome)}</strong><p>Pedidos con saldo abierto</p></div><button>Ver cuentas →</button></article><article><span>↓</span><div><small>PENDIENTE DE PAGAR</small><strong>{money(cash.pendingOutgoing)}</strong><p>Compras y gastos pendientes</p></div><button>Ver cuentas →</button></article></div><Panel title="Movimientos de caja" subtitle={`${cash.movements.length} movimientos en ${cash.label.toLocaleLowerCase("es")}`} action={<Button variant="secondary" size="sm" icon={<KhoraIcon name="download" />}>Exportar</Button>}>{cash.movements.length ? <div className="cash-movements">{cash.movements.map((movement) => <article key={movement.id}><span className={`cash-movement-icon ${movement.direction === "IN" ? "in" : "out"}`}>{movement.direction === "IN" ? "↓" : "↑"}</span><div><strong>{movement.description}</strong><small>{movement.counterpart} · {movement.category}</small></div><time dateTime={movement.occurredAt}>{new Intl.DateTimeFormat("es-AR", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(movement.occurredAt))}</time><b className={movement.direction === "IN" ? "success-text" : "danger-text"}>{movement.direction === "IN" ? "+" : "−"}{money(movement.amount)}</b></article>)}</div> : <div className="empty-cash"><span>✓</span><strong>No hay movimientos en este período</strong><p>Probá con Semana o Mes para ampliar la consulta.</p></div>}</Panel><div className="cash-method-note"><i>i</i><p>Caja usa la fecha del cobro o pago. Una venta pendiente no aparece como entrada hasta que se registra el pago.</p></div></>;
}

function MonthlyCloseView() {
  const closures = getAvailableClosures();
  const [monthKey, setMonthKey] = useState(closures[0]?.key ?? "2026-08");
  const [baselineKey, setBaselineKey] = useState(closures[1]?.key ?? closures[0]?.key ?? "2026-07");
  const close = getMonthlyClose(monthKey)!;
  const comparison = compareMonthlyClosures(monthKey, baselineKey);
  useEffect(() => { if (baselineKey !== monthKey) return; const timeout = window.setTimeout(() => setBaselineKey(closures.find((item) => item.key !== monthKey)?.key ?? baselineKey), 0); return () => window.clearTimeout(timeout); }, [baselineKey, monthKey, closures]);
  const displayMetric = (label: string, value: number) => label === "Pedidos" || label === "Unidades" ? String(value) : label === "Margen neto" ? `${value.toFixed(1)}%` : money(value);
  return <><div className="monthly-close-head"><div><small>CIERRE MENSUAL · HISTORIAL</small><h2>{close.name}</h2><p>Los cierres quedan guardados para comparar cualquier mes disponible.</p></div><div className="monthly-close-selectors"><label><span>Período</span><select value={monthKey} onChange={(event) => setMonthKey(event.target.value)}>{closures.map((item) => <option key={item.key} value={item.key}>{item.label}</option>)}</select></label><label><span>Comparar con</span><select value={baselineKey} onChange={(event) => setBaselineKey(event.target.value)}>{closures.filter((item) => item.key !== monthKey).map((item) => <option key={item.key} value={item.key}>{item.label}</option>)}</select></label></div></div><section className="close-hero"><div><small>GANANCIA NETA</small><strong>{money(close.netProfit)}</strong><span className="comparison-value up">Histórico guardado</span></div><dl><div><dt>Ventas</dt><dd>{money(close.sales)}</dd></div><div><dt>Costos vendidos</dt><dd>− {money(close.costs)}</dd></div><div><dt>Gastos</dt><dd>− {money(close.expenses)}</dd></div><div className="close-result"><dt>Margen neto</dt><dd>{close.netMargin.toFixed(1)}%</dd></div></dl></section><div className="summary-row"><MiniStat label="Ventas" value={money(close.sales)} detail={`${close.grossMargin.toFixed(1)}% margen bruto`} tone="success" /><MiniStat label="Gastos" value={money(close.expenses)} detail="Egresos del período" tone="warning" /><MiniStat label="Pedidos" value={String(close.orders)} detail="Pedidos registrados" tone="info" /><MiniStat label="Productos vendidos" value={`${close.productsSold} u.`} detail="Unidades entregadas" tone="neutral" /></div>{comparison ? <Panel title={`Comparación: ${comparison.current.name} vs. ${comparison.baseline.name}`} subtitle="Variación porcentual sobre el cierre histórico seleccionado"><div className="close-comparison">{comparison.metrics.map((metric) => { const favorable = metric.inverse ? metric.change <= 0 : metric.change >= 0; return <article className={favorable ? "positive" : "negative"} key={metric.label}><span>{metric.label}</span><strong>{metric.change >= 0 ? "↑" : "↓"} {Math.abs(metric.change).toFixed(1)}{metric.points ? " puntos" : "%"}</strong><small>{displayMetric(metric.label, metric.current)} vs. {displayMetric(metric.label, metric.baseline)} · {favorable ? "Evolución favorable" : "Revisar variación"}</small></article>; })}</div></Panel> : <div className="close-no-comparison"><span>i</span><p>Elegí dos meses distintos para ver la comparación.</p></div>}<Panel title="Resumen del cierre guardado" subtitle="El historial conserva los valores del período seleccionado"><div className="close-highlights"><CloseHighlight icon={moduleIcons.productos} title="Producto más vendido" value={close.highlights.topProduct.label} detail={close.highlights.topProduct.detail} /><CloseHighlight icon={moduleIcons.finanzas} title="Producto más rentable" value={close.highlights.profitableProduct.label} detail={close.highlights.profitableProduct.detail} /><CloseHighlight icon={moduleIcons.clientes} title="Mejor cliente" value={close.highlights.bestCustomer.label} detail={close.highlights.bestCustomer.detail} /><CloseHighlight icon={moduleIcons.finanzas} title="Mayor gasto" value={close.highlights.largestExpense.label} detail={money(close.highlights.largestExpense.detail)} /><CloseHighlight icon={moduleIcons.stock} title="Materia prima más comprada" value={close.highlights.mostPurchasedMaterial.label} detail={close.highlights.mostPurchasedMaterial.detail} /></div></Panel><div className="close-history-note"><span>✓</span><div><strong>Historial mensual protegido</strong><p>Podés volver a cualquier mes y compararlo con otro sin modificar los datos históricos.</p></div></div></>;
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyMonthlyCloseView() {
  const closures = getAvailableClosures();
  const [monthKey, setMonthKey] = useState("2026-08");
  const close = getMonthlyClose(monthKey)!;
  return <><div className="monthly-close-head"><div><small>CIERRE MENSUAL</small><h2>{close.name}</h2><p>Resultado del negocio con costos históricos de cada venta.</p></div><label><span>Período</span><select value={monthKey} onChange={(event) => setMonthKey(event.target.value)}>{closures.map((item) => <option key={item.key} value={item.key}>{item.label}</option>)}</select></label></div><section className="close-hero"><div><small>GANANCIA NETA</small><strong>{money(close.netProfit)}</strong><ComparisonValue value={close.comparison?.netProfit ?? 0} suffix={` vs. ${close.comparison?.month ?? "mes anterior"}`} /></div><dl><div><dt>Ventas</dt><dd>{money(close.sales)}</dd></div><div><dt>Costos vendidos</dt><dd>− {money(close.costs)}</dd></div><div><dt>Gastos</dt><dd>− {money(close.expenses)}</dd></div><div className="close-result"><dt>Margen neto</dt><dd>{close.netMargin.toFixed(1)}%</dd></div></dl></section><div className="summary-row"><MiniStat label="Ventas" value={money(close.sales)} detail={`${close.grossMargin.toFixed(1)}% margen bruto`} tone="success" /><MiniStat label="Gastos" value={money(close.expenses)} detail="Egresos del período" tone="warning" /><MiniStat label="Pedidos" value={String(close.orders)} detail="Pedidos registrados" tone="info" /><MiniStat label="Productos vendidos" value={`${close.productsSold} u.`} detail="Unidades entregadas" tone="neutral" /></div><Panel title="Lo más importante del mes" subtitle="Productos, clientes, gastos y abastecimiento"><div className="close-highlights"><CloseHighlight icon={moduleIcons.productos} title="Producto más vendido" value={close.highlights.topProduct.label} detail={close.highlights.topProduct.detail} /><CloseHighlight icon={moduleIcons.finanzas} title="Producto más rentable" value={close.highlights.profitableProduct.label} detail={close.highlights.profitableProduct.detail} /><CloseHighlight icon={moduleIcons.clientes} title="Mejor cliente" value={close.highlights.bestCustomer.label} detail={close.highlights.bestCustomer.detail} /><CloseHighlight icon={moduleIcons.finanzas} title="Mayor gasto" value={close.highlights.largestExpense.label} detail={money(close.highlights.largestExpense.detail)} /><CloseHighlight icon={moduleIcons.stock} title="Materia prima más comprada" value={close.highlights.mostPurchasedMaterial.label} detail={close.highlights.mostPurchasedMaterial.detail} /></div></Panel>{close.comparison ? <Panel title={`Comparación con ${close.comparison.month}`} subtitle="Variación respecto del mes anterior"><div className="close-comparison"><ComparisonCard label="Ventas" value={close.comparison.sales} /><ComparisonCard label="Ganancia" value={close.comparison.netProfit} /><ComparisonCard label="Gastos" value={close.comparison.expenses} inverse /><ComparisonCard label="Pedidos" value={close.comparison.orders} /><ComparisonCard label="Unidades" value={close.comparison.productsSold} /></div></Panel> : <div className="close-no-comparison"><span>i</span><p>Este es el primer mes disponible; todavía no hay un período anterior para comparar.</p></div>}<div className="close-history-note"><span>✓</span><div><strong>Resultado histórico protegido</strong><p>Se utilizan los precios y costos guardados al momento de cada venta. Los cambios actuales no reescriben este cierre.</p></div></div></>;
}

function CloseHighlight({ icon, title, value, detail }: { icon: KhoraIconName; title: string; value: string; detail: string }) { return <article><span><KhoraIcon name={icon} /></span><div><small>{title}</small><strong>{value}</strong><p>{detail}</p></div></article>; }
function ComparisonValue({ value, suffix = "" }: { value: number; suffix?: string }) { const direction = value >= 0 ? "up" : "down"; return <span className={`comparison-value ${direction}`}>{value >= 0 ? "↑" : "↓"} {Math.abs(value).toFixed(1)}%{suffix}</span>; }
function ComparisonCard({ label, value, inverse = false }: { label: string; value: number; inverse?: boolean }) { const positive = inverse ? value <= 0 : value >= 0; return <article className={positive ? "positive" : "negative"}><span>{label}</span><strong>{value >= 0 ? "↑" : "↓"} {Math.abs(value).toFixed(1)}%</strong><small>{positive ? "Evolución favorable" : "Revisar variación"}</small></article>; }

function Metric({ label, value, detail, tone, icon, onClick }: { label: string; value: string; detail: string; tone: Tone; icon: KhoraIconName; onClick?: () => void }) { return <button className={`metric-card ${tone}`} onClick={onClick}><div className="metric-icon"><KhoraIcon name={icon} /></div><span>{label}</span><strong>{value}</strong><small>{detail}</small>{onClick && <i className="metric-arrow">→</i>}</button>; }
function MiniStat({ label, value, detail, tone }: { label: string; value: string; detail: string; tone: Tone }) { const normalizedDetail = detail === "Sobre precio de venta" ? "Sobre costo actual" : detail; return <article className={`mini-stat ${tone}`}><span>{label}</span><strong>{value}</strong><small>{normalizedDetail}</small></article>; }
function Panel({ title, subtitle, action, children, className = "" }: { title: string; subtitle?: string; action?: React.ReactNode; children: React.ReactNode; className?: string }) { return <section className={`panel ${className}`}><header className="panel-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</header><div className="panel-body">{children}</div></section>; }
function Badge({ tone = "neutral", children }: { tone?: Tone; children: React.ReactNode }) { return <span className={`badge ${tone}`}><i />{children}</span>; }
function Avatar({ text, small = false }: { text: string; small?: boolean }) { return <span className={`avatar ${small ? "small" : ""}`}>{text}</span>; }
function MoreButton() { return <Button variant="utility" size="xs" iconOnly aria-label="Más acciones" icon={<span aria-hidden="true">•••</span>} />; }
function CellPerson({ name, subtitle, initialsText }: { name: string; subtitle?: string; initialsText?: string }) { return <div className="cell-person"><Avatar text={initialsText ?? initials(name)} small /><div><strong>{name}</strong>{subtitle && <small>{subtitle}</small>}</div></div>; }
function Tabs({ tabs, active, onChange }: { tabs: string[]; active: string; onChange: (tab: string) => void }) { return <div className="tabs" role="tablist">{tabs.map((tab) => <button key={tab} role="tab" aria-selected={tab === active} className={tab === active ? "active" : ""} onClick={() => onChange(tab)}>{tab}</button>)}</div>; }
function Toolbar({ placeholder, filters, compact = false }: { placeholder: string; filters: string[]; compact?: boolean }) { return <div className={`toolbar ${compact ? "compact" : ""}`}><label><span>⌕</span><input placeholder={placeholder} /></label><div>{filters.map((filter) => <Button key={filter} variant="utility" size="xs" iconPosition="end" icon={<span aria-hidden="true">⌄</span>}>{filter}</Button>)}</div></div>; }
function DataTable({ headers, children }: { headers: string[]; children: React.ReactNode }) { return <div className="data-table-wrap"><table className="data-table"><thead><tr>{headers.map((header, index) => <th key={`${header}-${index}`}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function inventoryBatchStatus(available: number, initial: number) { const current = Number(available) || 0, total = Number(initial) || 0; if (current <= 0) return { label: "Agotado", tone: "danger" as const }; if (total > 0 && current < total) return { label: "Poco stock", tone: "warning" as const }; return { label: "Disponible", tone: "success" as const }; }

function StockValue({ value, minimum, unit }: { value: number; minimum: number; unit: string }) { const safeMinimum = minimum > 0 ? minimum : Math.max(value, 1), percent = Math.min(100, Math.max(0, Math.round((value / safeMinimum) * 75))), status = materialStockStatus(value, minimum); return <div className="stock-value"><strong>{formatQuantity(value)} {unit}</strong><i><em className={status.tone} style={{ width: `${percent}%` }} /></i></div>; }
function MonthlyChart({ showCosts = false }: { showCosts?: boolean }) { const max = Math.max(...months.map((month) => month.sales)); return <div className="chart"><div className="chart-y"><span>$1,5 M</span><span>$1,0 M</span><span>$500 k</span><span>$0</span></div><div className="chart-area">{months.map((month) => { const profit = month.sales - month.costs - month.expenses; return <div className="chart-month" key={month.month}><div className="bar-group"><i className="sales-bar" style={{ height: `${(month.sales / max) * 100}%` }} title={`Ventas ${money(month.sales)}`} /><i className="profit-bar" style={{ height: `${(profit / max) * 100}%` }} title={`Ganancia ${money(profit)}`} />{showCosts && <i className="cost-bar" style={{ height: `${(month.costs / max) * 100}%` }} />}</div><span>{month.month}</span></div>; })}</div><div className="chart-legend"><span><i className="sales" />Ventas</span><span><i className="profit" />Ganancia</span>{showCosts && <span><i className="cost" />Costos</span>}</div></div>; }
function Health({ label, value, level, tone }: { label: string; value: string; level: number; tone: Tone }) { return <div className="health"><div><span>{label}</span><strong>{value}</strong></div><i><em className={tone} style={{ width: `${level}%` }} /></i></div>; }

function RecipeDetailDialog({ recipe, onClose, onEdit }: { recipe: RecipeRow; onClose: () => void; onEdit: () => void }) {
  useDrawerBodyLock();
  const detail = useKhoraObject<RecipeDetailData>(`/api/khora?entity=recipe_detail&productId=${recipe.product_id}`);
  const items = detail.data?.items ?? [], mixtureItems = detail.data?.mixtureItems ?? [], components = items.length + mixtureItems.length;
  const yieldQuantity = Number(detail.data?.recipe?.yield_quantity ?? recipe.yield_quantity) || 1, unitCost = Number(recipe.estimated_cost_cents) || 0;
  return <div className="drawer-layer">
    <button className="drawer-backdrop" onClick={onClose} aria-label="Cerrar receta" />
    <aside className="inventory-form-drawer recipe-detail-drawer" role="dialog" aria-modal="true" aria-labelledby="recipe-detail-title">
      <header><div><p>PRODUCTOS · RECETA</p><h2 id="recipe-detail-title">Receta de {recipe.product}</h2><span>{recipe.code} · Ingredientes y cantidades guardadas.</span></div><button onClick={onClose} aria-label="Cerrar">×</button></header>
      <div className="inventory-form-body recipe-detail-body">
        {detail.loading ? <div className="recipe-empty">Cargando receta…</div> : detail.error ? <p className="form-error" role="alert">{detail.error}</p> : <>
          <section className="recipe-detail-summary" aria-label="Resumen de la receta"><article><span>Rendimiento</span><strong>{formatQuantity(yieldQuantity)} u.</strong></article><article><span>Componentes</span><strong>{components}</strong></article><article><span>Costo estimado</span><strong>{money(unitCost / 100)}</strong></article></section>
          <section className="recipe-detail-section"><header><div><strong>Materias primas</strong><p>Insumos necesarios para producir el rendimiento indicado.</p></div><span>{items.length}</span></header><div className="recipe-detail-list">{items.map((item, index) => <article key={`recipe-material-detail-${item.material_id ?? index}`}><span className="recipe-line-icon" aria-hidden="true">⚗</span><div><strong>{item.code} · {item.material ?? "Materia prima"}</strong><small>{item.category || "Materia prima guardada"}</small></div><div className="recipe-detail-quantity"><span>Cantidad</span><strong>{formatQuantity(Number(item.quantity))} {item.unit === "u." ? "unidad" : item.unit}</strong></div><div className="recipe-detail-cost"><span>Costo</span><strong>{money(Number(item.subtotal_cents ?? 0) / 100)}</strong></div></article>)}{!items.length && <div className="recipe-empty">Esta receta no tiene materias primas directas.</div>}</div></section>
          {mixtureItems.length > 0 && <section className="recipe-detail-section"><header><div><strong>Mezclas preparadas</strong><p>Mezclas intermedias incluidas en la receta del producto.</p></div><span>{mixtureItems.length}</span></header><div className="recipe-detail-list">{mixtureItems.map((item, index) => <article key={`recipe-mixture-detail-${item.mixture_id ?? index}`}><span className="recipe-line-icon" aria-hidden="true">◌</span><div><strong>{item.code} · {item.mixture ?? "Mezcla preparada"}</strong><small>Mezcla guardada</small></div><div className="recipe-detail-quantity"><span>Cantidad</span><strong>{formatQuantity(Number(item.quantity))} {item.unit === "u." ? "unidad" : item.unit}</strong></div><div className="recipe-detail-cost"><span>Costo</span><strong>{money(Number(item.subtotal_cents ?? 0) / 100)}</strong></div></article>)}</div></section>}
        </>}
      </div>
      <footer><button className="secondary-button" onClick={onClose}>Cerrar</button><button className="primary-button" disabled={detail.loading || Boolean(detail.error)} onClick={onEdit}><KhoraIcon name="pencil" /> Editar receta</button></footer>
    </aside>
  </div>;
}

function RecipeList({ rows, loading, onView, onEdit }: { rows: RecipeRow[]; loading: boolean; onView: (recipe: RecipeRow) => void; onEdit: (recipe: RecipeRow) => void }) {
  return <Panel title="Recetas de fabricación" subtitle={loading ? "Actualizando…" : `${rows.length} recetas registradas`}><DataTable headers={["Producto", "Rendimiento", "Ingredientes", "Costo receta", "Costo unitario", "Actualizada", "Estado", "Acciones"]}>{rows.map((recipe) => { const yieldQuantity = Number(recipe.yield_quantity) || 1; const unitCost = Number(recipe.estimated_cost_cents); return <tr key={recipe.id}><td><strong>{recipe.product}</strong><small className="table-sub">{recipe.code}</small></td><td>{formatQuantity(yieldQuantity)} u.</td><td>{Number(recipe.components)} componentes</td><td>{money(unitCost * yieldQuantity / 100)}</td><td><strong>{money(unitCost / 100)}</strong></td><td>{formatDate(recipe.updated_at)}</td><td><Badge tone={recipe.active ? "success" : "neutral"}>{recipe.active ? "Activa" : "Inactiva"}</Badge></td><td><div className="table-actions recipe-table-actions"><button className="table-open-button recipe-view-button" type="button" onClick={() => onView(recipe)}><KhoraIcon name="eye" /> Ver receta</button><button className="row-icon-button edit" type="button" title="Editar receta" aria-label={`Editar receta de ${recipe.product}`} onClick={() => onEdit(recipe)}><KhoraIcon name="pencil" /></button></div></td></tr>; })}</DataTable>{!loading && !rows.length && <div className="recipe-empty">Todavía no hay recetas registradas.</div>}</Panel>;
}
function ComboList({ rows, products: productRows, loading, onCreate, onEdit, onArchive }: { rows: ComboRow[]; products: ProductRow[]; loading: boolean; onCreate: () => void; onEdit: (combo: ComboRow) => void; onArchive: (combo: ComboRow) => void }) { return <Panel title="Combos" subtitle={loading ? "Actualizando…" : `${rows.length} combos registrados`} action={<button className="primary-button" onClick={onCreate}>＋ Nuevo combo</button>}><div className="combo-grid">{rows.map((combo) => { const product = productRows.find((candidate) => Number(candidate.id) === Number(combo.product_id)); const cost = Number(combo.last_batch_unit_cost_cents) > 0 ? Number(combo.last_batch_unit_cost_cents) : Number(combo.estimated_cost_cents); return <article key={combo.id}><div className="combo-icon">K</div><div><small>{combo.code}</small><h3>{combo.combo}</h3><p>{Number(combo.components)} componentes · stock {formatQuantity(Number(combo.current_stock))} u.</p><dl><div><dt>Costo</dt><dd>{money(cost / 100)}</dd></div><div><dt>Precio</dt><dd>{money(Number(product?.sale_price_cents ?? combo.sale_price_cents ?? 0) / 100)}</dd></div></dl><div className="combo-card-footer"><Badge tone={combo.active ? "success" : "neutral"}>{combo.active ? "Activo" : "Inactivo"}</Badge>{Boolean(combo.active) && <div><button className="secondary-button" onClick={() => onEdit(combo)}>Editar</button><button className="definition-archive-button" onClick={() => onArchive(combo)} title="Archivar combo" aria-label={`Archivar ${combo.combo}`}>⌫</button></div>}</div></div></article>; })}</div>{!loading && !rows.length && <div className="recipe-empty">Todavía no hay combos registrados.</div>}</Panel>; }
function SimpleCategories({ rows }: { rows: CategoryRow[] }) { const productCategories = rows.filter((category) => category.kind === "PRODUCT"); return <Panel title="Categorías" subtitle="Organización de productos"><div className="category-list">{productCategories.map((category) => <article key={category.id}><span>{category.prefix || category.code || category.name.slice(0, 1)}</span><strong>{category.name}</strong><small>{category.category_type} · {category.active ? "Activa" : "Inactiva"}</small><Badge tone={category.active ? "success" : "neutral"}>{category.active ? "Activa" : "Inactiva"}</Badge></article>)}</div>{!productCategories.length && <div className="recipe-empty">Todavía no hay categorías de producto registradas.</div>}</Panel>; }
function MovementList({ rows, loading, compact = false }: { rows: MovementRow[]; loading: boolean; compact?: boolean }) { const content = <><DataTable headers={["Fecha", "Tipo", "Producto o insumo", "Movimiento", "Saldo", "Costo unitario", "Notas"]}>{rows.map((row) => { const delta = Number(row.quantity_delta), positive = delta > 0; return <tr key={row.id}><td>{formatDate(row.created_at)}</td><td><Badge tone={positive ? "success" : "info"}>{row.movement}</Badge></td><td><strong>{row.item || "Movimiento"}</strong></td><td className={positive ? "success-text" : "danger-text"}>{positive ? "+" : "−"}{formatQuantity(Math.abs(delta))}</td><td>{formatQuantity(Number(row.balance_after))}</td><td>{money(Number(row.unit_cost_cents) / 100)}</td><td>{row.notes || "—"}</td></tr>; })}</DataTable>{!loading && !rows.length && <div className="recipe-empty">Todavía no hay movimientos de stock para este producto.</div>}</>; return compact ? <div className="product-movement-table">{content}</div> : <Panel title="Movimientos de stock" subtitle={loading ? "Actualizando…" : `${rows.length} movimientos auditables`}>{content}</Panel>; }
function ProfitHistory() { return <Panel title="Ganancia por mes" subtitle="El costo corresponde a los productos efectivamente vendidos" action={<Button variant="secondary" size="sm" icon={<KhoraIcon name="download" />}>Exportar</Button>}><DataTable headers={["Mes", "Ventas", "Costos vendidos", "Ganancia bruta", "Gastos", "Ganancia neta", "Margen"]}>{months.slice().reverse().map((month) => { const gross = month.sales - month.costs, net = gross - month.expenses; return <tr key={month.month}><td><strong>{month.month} 2026</strong></td><td>{money(month.sales)}</td><td>{money(month.costs)}</td><td>{money(gross)}</td><td>{money(month.expenses)}</td><td><strong className="success-text">{money(net)}</strong></td><td>{((net / month.sales) * 100).toFixed(1)}%</td></tr>; })}</DataTable></Panel>; }
function Accounts() { return <div className="account-grid"><Panel title="Cuentas por cobrar" subtitle="3 pagos pendientes"><div className="account-list">{orders.filter((o) => o.payment !== "Pagado").map((order) => <article key={order.id}><CellPerson name={order.customer} /><div><strong>{money(order.total)}</strong><small>{order.id} · {order.payment}</small></div><button>Registrar pago</button></article>)}</div></Panel><Panel title="Cuentas por pagar" subtitle="1 compra pendiente"><div className="account-list">{purchases.filter((p) => p.payment !== "Pagado").map((purchase) => <article key={purchase.id}><CellPerson name={purchase.supplier} /><div><strong>{money(purchase.total)}</strong><small>{purchase.id} · {purchase.payment}</small></div><button>Registrar pago</button></article>)}</div></Panel></div>; }
function Reports() { const reports: Array<{ title: string; detail: string; icon: KhoraIconName }> = [{ title: "Ventas", detail: "Detalle, productos y medios de pago", icon: moduleIcons.ventas }, { title: "Stock", detail: "Productos y materias primas", icon: moduleIcons.stock }, { title: "Ganancias", detail: "Ventas, costos, gastos y margen", icon: moduleIcons.finanzas }, { title: "Clientes", detail: "Actividad e historial de compras", icon: moduleIcons.clientes }, { title: "Fabricación", detail: "Lotes, consumos y costos", icon: moduleIcons.fabricacion }, { title: "Compras y gastos", detail: "Proveedores y movimientos", icon: moduleIcons.compras }]; return <div className="report-grid">{reports.map((report) => <article key={report.title}><span><KhoraIcon name={report.icon} /></span><div><h3>{report.title}</h3><p>{report.detail}</p></div><select aria-label={`Formato para ${report.title}`}><option>Excel</option><option>PDF</option></select><button>Generar</button></article>)}</div>; }

function productCost(product: ProductRow) { return Number(product.last_batch_unit_cost_cents) > 0 ? Number(product.last_batch_unit_cost_cents) : Number(product.estimated_cost_cents) || 0; }
function productMargin(product: ProductRow) { const savedTarget = product.target_margin_percentage == null ? null : Number(product.target_margin_percentage); if (savedTarget !== null && Number.isFinite(savedTarget) && savedTarget >= 0) return savedTarget; const price = Number(product.sale_price_cents) || 0, cost = productCost(product); return cost > 0 ? ((price - cost) * 100) / cost : 0; }
function productTypeLabel(type: string) { return type === "COMBO" ? "Combo" : type === "SIMPLE" ? "Producto simple" : "Fabricado"; }
function formatDate(value: string) { if (!value) return "—"; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat("es-AR", { day: "2-digit", month: "short", year: "numeric" }).format(date); }
function initials(name: string) { return name.split(" ").slice(0, 2).map((part) => part[0]).join("").toUpperCase(); }
function includesSearch(value: unknown, search: string) { return !search.trim() || JSON.stringify(value).toLocaleLowerCase("es").includes(search.trim().toLocaleLowerCase("es")); }
function formatQuantity(value: number) { return new Intl.NumberFormat("es-AR", { maximumFractionDigits: 2 }).format(value); }
